const cents = (value: number) => Math.round((Number(value) || 0) * 100) / 100;

type PaymentAllocation = Pick<SnowballAllocationResult, "billId" | "payment">;

export function diffAppliedSnowballAllocations(
  previous: PaymentAllocation[],
  previousApplied: boolean,
  next: PaymentAllocation[],
  nextApplied: boolean,
): Map<string, number> {
  const deltas = new Map<string, number>();
  const add = (allocation: PaymentAllocation, direction: number) => {
    deltas.set(allocation.billId, cents((deltas.get(allocation.billId) ?? 0) + allocation.payment * direction));
  };
  if (previousApplied) previous.forEach(allocation => add(allocation, -1));
  if (nextApplied) next.forEach(allocation => add(allocation, 1));
  return new Map([...deltas].filter(([, delta]) => Math.abs(delta) >= 0.005));
}

export function monthlyInterestCharge(balance: number, annualPercentageRate: number): number {
  return cents(Math.max(0, Number(balance) || 0) * (Math.max(0, Number(annualPercentageRate) || 0) / 100) / 12);
}

export function effectiveDebtMinimum(baseMinimum: number, rolledMinimum: number): number {
  return cents(Math.max(0, baseMinimum) + Math.max(0, rolledMinimum));
}

/**
 * The lender-required amount for one occurrence. Snowball rollover is an
 * optional payoff commitment and must never raise the amount used for
 * late/missed-payment status.
 */
export function requiredDebtMinimum(baseMinimum: number): number {
  return cents(Math.max(0, baseMinimum));
}

export function monthlyDebtAmount(baseMinimum: number, _rolledMinimum: number, settledAmount?: number): number {
  return settledAmount !== undefined && Number.isFinite(settledAmount)
    ? cents(Math.max(0, settledAmount))
    : requiredDebtMinimum(baseMinimum);
}

export function scheduledDebtPaymentAmount(amount: number, paymentDate: string, today: string, balance: number): number {
  if (amount >= 0 || paymentDate > today) return 0;
  return cents(Math.min(Math.abs(amount), Math.max(0, balance)));
}

export function orderDebts<T extends SnowballDebtInput>(debts: T[], method: DebtMethod): T[] {
  return [...debts].sort((a, b) => {
    if (method === "avalanche") {
      return b.apr - a.apr || a.balance - b.balance || a.id.localeCompare(b.id);
    }
    return a.balance - b.balance || b.apr - a.apr || a.id.localeCompare(b.id);
  });
}

export function allocateSnowballExtra(
  debts: SnowballDebtInput[],
  amount: number,
  method: DebtMethod,
  paymentDate: string,
): { allocations: SnowballAllocationResult[]; balances: Map<string, number>; payoffOrder: string[] } {
  const balances = new Map(debts.map(debt => [debt.id, cents(Math.max(0, debt.balance))]));
  const allocations: SnowballAllocationResult[] = [];
  const payoffOrder: string[] = [];
  let remaining = cents(Math.max(0, amount));

  while (remaining > 0.009) {
    const active = orderDebts(
      debts.filter(debt => debt.included && (balances.get(debt.id) ?? 0) > 0.009)
        .map(debt => ({ ...debt, balance: balances.get(debt.id) ?? 0 })),
      method,
    );
    const target = active[0];
    if (!target) break;
    const before = balances.get(target.id) ?? 0;
    const payment = cents(Math.min(before, remaining));
    const after = cents(Math.max(0, before - payment));
    balances.set(target.id, after);
    remaining = cents(remaining - payment);
    allocations.push({
      billId: target.id,
      billName: target.name,
      payment,
      balanceBefore: before,
      balanceAfter: after,
      paidOff: after <= 0.009,
      paymentDate,
    });
    if (after <= 0.009) payoffOrder.push(target.name);
  }

  return { allocations, balances, payoffOrder };
}

function addMonthPayment(
  payments: Map<string, SnowballMonthPayment>,
  debt: SnowballDebtInput,
  amount: number,
  kind: "scheduled" | "extra",
  balanceBefore: number,
  balanceAfter: number,
) {
  const clean = cents(amount);
  if (clean <= 0.009) return;
  const existing = payments.get(debt.id) ?? {
    billId: debt.id,
    billName: debt.name,
    dueDay: debt.dueDay,
    scheduledPayment: 0,
    extraPayment: 0,
    totalPayment: 0,
    balanceBefore,
    balanceAfter,
    paidOff: false,
  };
  if (kind === "scheduled") existing.scheduledPayment = cents(existing.scheduledPayment + clean);
  else existing.extraPayment = cents(existing.extraPayment + clean);
  existing.totalPayment = cents(existing.scheduledPayment + existing.extraPayment);
  existing.balanceBefore = Math.max(existing.balanceBefore, balanceBefore);
  existing.balanceAfter = balanceAfter;
  existing.paidOff = balanceAfter <= 0.009;
  payments.set(debt.id, existing);
}

function applyPoolToNextDebt(
  debts: SnowballDebtInput[],
  balances: Map<string, number>,
  payments: Map<string, SnowballMonthPayment>,
  method: DebtMethod,
  amount: number,
  kind: "scheduled" | "extra",
) {
  let pool = cents(Math.max(0, amount));
  while (pool > 0.009) {
    const target = orderDebts(
      debts
        .filter(debt => debt.included && (balances.get(debt.id) ?? 0) > 0.009)
        .map(debt => ({ ...debt, balance: balances.get(debt.id) ?? 0 })),
      method,
    )[0];
    if (!target) break;
    const original = debts.find(debt => debt.id === target.id) ?? target;
    const before = cents(balances.get(target.id) ?? 0);
    const payment = cents(Math.min(before, pool));
    const after = cents(Math.max(0, before - payment));
    balances.set(target.id, after);
    addMonthPayment(payments, original, payment, kind, before, after);
    pool = cents(pool - payment);
  }
  return cents(amount - pool);
}

export function projectSnowballMonth(options: {
  debts: SnowballDebtInput[];
  method: DebtMethod;
  startingBalances?: Map<string, number>;
  rolledPayment?: number;
  extraPayment?: number;
  applyInterest?: boolean;
}): SnowballMonthPlanResult {
  const balances = new Map(
    options.debts.map(debt => [
      debt.id,
      cents(Math.max(0, options.startingBalances?.get(debt.id) ?? debt.balance)),
    ]),
  );
  const payments = new Map<string, SnowballMonthPayment>();
  const activeIncludedAtStart = new Set(
    options.debts
      .filter(debt => debt.included && (balances.get(debt.id) ?? 0) > 0.009)
      .map(debt => debt.id),
  );
  let interest = 0;

  if (options.applyInterest !== false) {
    for (const debt of options.debts) {
      const before = balances.get(debt.id) ?? 0;
      if (before <= 0.009) continue;
      const charge = monthlyInterestCharge(before, debt.apr);
      balances.set(debt.id, cents(before + charge));
      interest = cents(interest + charge);
    }
  }

  let minimumPayments = 0;
  let scheduledPool = cents(Math.max(0, options.rolledPayment ?? 0));
  for (const debt of options.debts) {
    const before = cents(balances.get(debt.id) ?? 0);
    if (before <= 0.009) continue;
    const minimum = cents(Math.max(0, debt.minimum));
    const payment = cents(Math.min(before, minimum));
    const after = cents(Math.max(0, before - payment));
    balances.set(debt.id, after);
    minimumPayments = cents(minimumPayments + payment);
    addMonthPayment(payments, debt, payment, "scheduled", before, after);
    if (debt.included && minimum > payment) {
      scheduledPool = cents(scheduledPool + minimum - payment);
    }
  }

  const scheduledRolloverApplied = applyPoolToNextDebt(options.debts, balances, payments, options.method, scheduledPool, "scheduled");
  const extraPayment = applyPoolToNextDebt(options.debts, balances, payments, options.method, options.extraPayment ?? 0, "extra");
  const paidOffNames: string[] = [];
  const paidOffIds: string[] = [];
  for (const debt of options.debts) {
    if (!activeIncludedAtStart.has(debt.id)) continue;
    if ((balances.get(debt.id) ?? 0) > 0.009) continue;
    paidOffIds.push(debt.id);
    paidOffNames.push(debt.name);
  }
  const rolledPayment = cents(
    Math.max(0, options.rolledPayment ?? 0) +
    paidOffIds.reduce((sum, id) => {
      const debt = options.debts.find(item => item.id === id);
      return sum + Math.max(0, debt?.minimum ?? 0);
    }, 0),
  );
  const endingDebt = cents(options.debts
    .filter(debt => debt.included)
    .reduce((sum, debt) => sum + (balances.get(debt.id) ?? 0), 0));
  const paymentList = Array.from(payments.values()).map(payment => ({
    ...payment,
    scheduledPayment: cents(payment.scheduledPayment),
    extraPayment: cents(payment.extraPayment),
    totalPayment: cents(payment.totalPayment),
    balanceAfter: cents(balances.get(payment.billId) ?? payment.balanceAfter),
    paidOff: (balances.get(payment.billId) ?? payment.balanceAfter) <= 0.009,
  }));
  return {
    payments: paymentList,
    balances,
    payoffOrder: paidOffNames,
    paidOffNames,
    rolledPayment,
    minimumPayments,
    scheduledPayments: cents(minimumPayments + scheduledRolloverApplied),
    extraPayment,
    interest,
    endingDebt,
  };
}

function isoMonthDate(year: number, month: number, day: number): string {
  const lastDay = new Date(year, month + 1, 0).getDate();
  return `${year}-${String(month + 1).padStart(2, "0")}-${String(Math.min(lastDay, Math.max(1, day))).padStart(2, "0")}`;
}

function splitCents(total: number, parts: number): number[] {
  if (parts <= 0) return [];
  const totalCents = Math.round(cents(total) * 100);
  const base = Math.floor(totalCents / parts);
  const remainder = totalCents - base * parts;
  return Array.from({ length: parts }, (_, index) => (base + (index < remainder ? 1 : 0)) / 100);
}

/**
 * Builds the canonical dated debt plan used by every forecast surface.
 *
 * Required payments stay with their creditor first. Any amount above the
 * creditor's remaining balance becomes a same-day rollover pool for the next
 * eligible debt. The parent amount is never emitted alongside its child
 * allocations, so the returned rows are the complete cash-impact schedule.
 */
export function projectDatedSnowballMonth(options: {
  debts: DatedSnowballDebtInput[];
  method: DebtMethod;
  month: number;
  year: number;
  paymentDatesByDebtId?: ReadonlyMap<string, readonly string[]>;
  startingBalances?: Map<string, number>;
  rolledPayment?: number;
  extraPayment?: { amount: number; date: string };
}): DatedSnowballMonthPlanResult {
  const balances = new Map(
    options.debts.map(debt => [
      debt.id,
      cents(Math.max(0, options.startingBalances?.get(debt.id) ?? debt.balance)),
    ]),
  );
  const payments = new Map<string, SnowballMonthPayment>();
  const allocations: DatedDebtAllocation[] = [];
  const activeIncludedAtStart = new Set(
    options.debts
      .filter(debt => debt.included && (balances.get(debt.id) ?? 0) > 0.009)
      .map(debt => debt.id),
  );
  let interest = 0;
  let minimumPayments = 0;
  let unusedAmount = 0;
  let sequence = 0;

  for (const debt of options.debts) {
    const before = balances.get(debt.id) ?? 0;
    if (before <= 0.009) continue;
    const charge = monthlyInterestCharge(before, debt.apr);
    balances.set(debt.id, cents(before + charge));
    interest = cents(interest + charge);
  }

  type RequiredEvent = { date: string; debt: DatedSnowballDebtInput; amount: number };
  type PoolEvent = {
    date: string;
    amount: number;
    kind: Exclude<DatedDebtAllocationKind, "required">;
    targetBillId?: string;
    cascade?: boolean;
    sourceBillId?: string;
    sourceBillName?: string;
  };
  const requiredEvents: RequiredEvent[] = [];
  const poolEvents: PoolEvent[] = [];

  for (const debt of options.debts) {
    if (!activeIncludedAtStart.has(debt.id) && (balances.get(debt.id) ?? 0) <= 0.009) continue;
    const configuredDates = options.paymentDatesByDebtId?.get(debt.id) ?? [];
    const dates = configuredDates.length
      ? [...configuredDates].sort()
      : [isoMonthDate(options.year, options.month, debt.dueDay)];
    const amounts = debt.requiredPaymentsByDate
      ? dates.map(date => cents(Math.max(0, debt.requiredPaymentsByDate?.get(date) ?? 0)))
      : splitCents(
          Math.max(0, debt.requiredPayment ?? debt.minimum),
          dates.length,
        );
    dates.forEach((date, index) => {
      if ((amounts[index] ?? 0) > 0.009) requiredEvents.push({ date, debt, amount: amounts[index] ?? 0 });
    });
    const plannedExtra = cents(Math.max(0, debt.plannedExtraPayment ?? 0));
    if (plannedExtra > 0.009) {
      poolEvents.push({
        date: dates[0] ?? isoMonthDate(options.year, options.month, debt.dueDay),
        amount: plannedExtra,
        kind: "rollover",
        targetBillId: debt.id,
        cascade: debt.included,
      });
    }
  }

  const firstTarget = orderDebts(
    options.debts
      .filter(debt => debt.included && (balances.get(debt.id) ?? 0) > 0.009)
      .map(debt => ({ ...debt, balance: balances.get(debt.id) ?? 0 })),
    options.method,
  )[0];
  const firstTargetDates = firstTarget
    ? options.paymentDatesByDebtId?.get(firstTarget.id) ?? []
    : [];
  if ((options.rolledPayment ?? 0) > 0.009) {
    poolEvents.push({
      date: firstTargetDates[0] ?? isoMonthDate(options.year, options.month, firstTarget?.dueDay ?? 1),
      amount: cents(Math.max(0, options.rolledPayment ?? 0)),
      kind: "rollover",
    });
  }
  if ((options.extraPayment?.amount ?? 0) > 0.009) {
    poolEvents.push({
      date: options.extraPayment?.date ?? isoMonthDate(options.year, options.month, 1),
      amount: cents(Math.max(0, options.extraPayment?.amount ?? 0)),
      kind: "extra",
    });
  }

  const addAllocation = (
    target: SnowballDebtInput,
    amount: number,
    date: string,
    kind: DatedDebtAllocationKind,
    sourceAmount: number,
    source?: SnowballDebtInput,
  ) => {
    const payment = cents(amount);
    if (payment <= 0.009) return;
    const before = cents(balances.get(target.id) ?? 0);
    const applied = cents(Math.min(before, payment));
    if (applied <= 0.009) return;
    const after = cents(Math.max(0, before - applied));
    balances.set(target.id, after);
    addMonthPayment(payments, target, applied, kind === "extra" ? "extra" : "scheduled", before, after);
    allocations.push({
      id: `debt-plan:${date}:${source?.id ?? kind}:${target.id}:${kind}:${sequence++}`,
      date,
      sourceBillId: source?.id,
      sourceBillName: source?.name,
      targetBillId: target.id,
      targetBillName: target.name,
      kind,
      amount: applied,
      sourceAmount: cents(sourceAmount),
      balanceBefore: before,
      balanceAfter: after,
      paidOff: after <= 0.009,
    });
  };

  const applyPool = (event: PoolEvent) => {
    let remaining = cents(event.amount);
    let preferredTargetId = event.targetBillId;
    while (remaining > 0.009) {
      const preferred = preferredTargetId
        ? options.debts.find(debt => debt.id === preferredTargetId && (balances.get(debt.id) ?? 0) > 0.009)
        : undefined;
      const target = preferred ?? orderDebts(
        options.debts
          .filter(debt => debt.included && (balances.get(debt.id) ?? 0) > 0.009)
          .map(debt => ({ ...debt, balance: balances.get(debt.id) ?? 0 })),
        options.method,
      )[0];
      if (!target) break;
      const original = options.debts.find(debt => debt.id === target.id) ?? target;
      const before = balances.get(target.id) ?? 0;
      const applied = cents(Math.min(before, remaining));
      addAllocation(original, applied, event.date, event.kind, event.amount,
        event.sourceBillId ? options.debts.find(debt => debt.id === event.sourceBillId) : undefined);
      remaining = cents(remaining - applied);
      if (preferredTargetId) {
        preferredTargetId = undefined;
        if (event.cascade === false) break;
      }
    }
    unusedAmount = cents(unusedAmount + remaining);
  };

  const dates = [...new Set([
    ...requiredEvents.map(event => event.date),
    ...poolEvents.map(event => event.date),
  ])].sort();

  for (const date of dates) {
    const overflowPools: PoolEvent[] = [];
    requiredEvents
      .filter(event => event.date === date)
      .sort((left, right) => left.debt.id.localeCompare(right.debt.id))
      .forEach(event => {
        const before = cents(balances.get(event.debt.id) ?? 0);
        const ownPayment = cents(Math.min(before, event.amount));
        if (ownPayment > 0.009) {
          addAllocation(event.debt, ownPayment, date, "required", event.amount, event.debt);
          minimumPayments = cents(minimumPayments + ownPayment);
        }
        const overflow = cents(event.amount - ownPayment);
        if (overflow <= 0.009) return;
        if (event.debt.included) {
          overflowPools.push({
            date,
            amount: overflow,
            kind: "rollover",
            sourceBillId: event.debt.id,
            sourceBillName: event.debt.name,
          });
        } else {
          unusedAmount = cents(unusedAmount + overflow);
        }
      });
    overflowPools.forEach(applyPool);
    poolEvents.filter(event => event.date === date).forEach(applyPool);
  }

  const paidOffNames = options.debts
    .filter(debt => activeIncludedAtStart.has(debt.id) && (balances.get(debt.id) ?? 0) <= 0.009)
    .map(debt => debt.name);
  const paidOffIds = new Set(options.debts
    .filter(debt => activeIncludedAtStart.has(debt.id) && (balances.get(debt.id) ?? 0) <= 0.009)
    .map(debt => debt.id));
  const rolledPayment = cents(
    Math.max(0, options.rolledPayment ?? 0) +
    options.debts.reduce((sum, debt) => sum + (paidOffIds.has(debt.id) ? Math.max(0, debt.minimum) : 0), 0),
  );
  const endingDebt = cents(options.debts
    .filter(debt => debt.included)
    .reduce((sum, debt) => sum + (balances.get(debt.id) ?? 0), 0));
  const paymentList = Array.from(payments.values()).map(payment => ({
    ...payment,
    scheduledPayment: cents(payment.scheduledPayment),
    extraPayment: cents(payment.extraPayment),
    totalPayment: cents(payment.totalPayment),
    balanceAfter: cents(balances.get(payment.billId) ?? payment.balanceAfter),
    paidOff: (balances.get(payment.billId) ?? payment.balanceAfter) <= 0.009,
  }));
  const scheduledPayments = cents(allocations
    .filter(allocation => allocation.kind !== "extra")
    .reduce((sum, allocation) => sum + allocation.amount, 0));
  const extraPayment = cents(allocations
    .filter(allocation => allocation.kind === "extra")
    .reduce((sum, allocation) => sum + allocation.amount, 0));
  const plannedPayment = cents(scheduledPayments + extraPayment);

  return {
    payments: paymentList,
    balances,
    payoffOrder: paidOffNames,
    paidOffNames,
    rolledPayment,
    minimumPayments,
    scheduledPayments,
    extraPayment,
    interest,
    endingDebt,
    allocations,
    plannedPayment,
    unusedAmount,
  };
}

export interface PayoffSimulationOptions {
  debts: SnowballDebtInput[];
  method: DebtMethod;
  startMonth: number;
  startYear: number;
  firstMonthBalances: Map<string, number>;
  firstPayoffOrder?: string[];
  initialRolledPayment?: number;
  getExtraForMonth: (monthOffset: number, month: number, year: number, remainingDebt: number) => { extra: number; lowestBalance: number };
}

export function simulateSnowballPayoff(options: PayoffSimulationOptions): {
  months: SnowballMonthProjection[];
  payoffOrder: string[];
  debtFreeDate: string | null;
} {
  const balances = new Map(options.firstMonthBalances);
  const payoffOrder = [...(options.firstPayoffOrder ?? [])];
  const paidNames = new Set(payoffOrder);
  const months: SnowballMonthProjection[] = [];
  let rolledPayment = cents(options.initialRolledPayment ?? 0);

  for (let offset = 1; offset <= MAX_PAYOFF_MONTHS; offset++) {
    const absolute = options.startYear * 12 + options.startMonth + offset;
    const month = absolute % 12;
    const year = Math.floor(absolute / 12);
    const remainingDebtBeforePayment = options.debts
      .filter(debt => debt.included)
      .reduce((sum, debt) => sum + (balances.get(debt.id) ?? 0), 0);
    const safe = options.getExtraForMonth(offset, month, year, remainingDebtBeforePayment);
    const extra = cents(Math.min(Math.max(0, safe.extra), remainingDebtBeforePayment));
    const targetBefore = orderDebts(
      options.debts.filter(debt => debt.included && (balances.get(debt.id) ?? 0) > 0.009)
        .map(debt => ({ ...debt, balance: balances.get(debt.id) ?? 0 })),
      options.method,
    )[0];
    const monthPlan = projectSnowballMonth({
      debts: options.debts,
      method: options.method,
      startingBalances: balances,
      rolledPayment,
      extraPayment: extra,
    });
    balances.clear();
    monthPlan.balances.forEach((balance, id) => balances.set(id, balance));
    rolledPayment = monthPlan.rolledPayment;
    const paidOffNamesThisMonth = monthPlan.paidOffNames.filter(name => !paidNames.has(name));
    paidOffNamesThisMonth.forEach(name => {
      paidNames.add(name);
      payoffOrder.push(name);
    });
    months.push({
      month,
      year,
      targetName: targetBefore?.name ?? null,
      minimumPayments: monthPlan.minimumPayments,
      extraPayment: monthPlan.extraPayment,
      rolledPayment,
      interest: monthPlan.interest,
      endingDebt: monthPlan.endingDebt,
      lowestAccountBalance: safe.lowestBalance,
      paidOffNames: paidOffNamesThisMonth,
    });
    if (monthPlan.endingDebt <= 0.009) {
      return { months, payoffOrder, debtFreeDate: `${year}-${String(month + 1).padStart(2, "0")}` };
    }
  }

  return { months, payoffOrder, debtFreeDate: null };
}

export interface ScheduledBill {
  frequency: "monthly" | "quarterly" | "biweekly" | "weekly";
  due_day: number;
  day_of_week?: number;
  next_payment_date?: string;
  start_date?: string;
  end_date?: string;
}

export interface ScheduledIncome {
  amount: number;
  frequency: "monthly" | "biweekly" | "weekly";
  start_date?: string;
  next_payment_date?: string;
  amount_history?: { effective_from: string; amount: number }[];
  excluded_dates?: string[];
}

export interface ScheduledBillDateMove {
  bill_id: string;
  from_date: string;
  to_date: string;
  custom_amount?: number;
  is_skipped?: boolean;
  created_at?: string;
  updated_at?: string;
}

export interface SettledBillOverride {
  bill_id: string;
  month: number;
  year: number;
  paid_amount: number;
  actual_amount?: number;
  paid_date?: string;
}

const DAY_MS = 86_400_000;

type CalendarDateParts = { year: number; month: number; day: number };

function parseCalendarDate(value: string | undefined): CalendarDateParts | null {
  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(String(value ?? "").slice(0, 10));
  if (!match) return null;
  const parts = { year: Number(match[1]), month: Number(match[2]), day: Number(match[3]) };
  const parsed = new Date(Date.UTC(parts.year, parts.month - 1, parts.day));
  if (
    parsed.getUTCFullYear() !== parts.year
    || parsed.getUTCMonth() !== parts.month - 1
    || parsed.getUTCDate() !== parts.day
  ) return null;
  return parts;
}

function calendarDayNumber(parts: CalendarDateParts) {
  return Math.floor(Date.UTC(parts.year, parts.month - 1, parts.day) / DAY_MS);
}

function calendarDateFromDayNumber(dayNumber: number) {
  const date = new Date(dayNumber * DAY_MS);
  return `${date.getUTCFullYear()}-${String(date.getUTCMonth() + 1).padStart(2, "0")}-${String(date.getUTCDate()).padStart(2, "0")}`;
}

export function billSeriesEndDateBefore(occurrenceDate: string): string | undefined {
  const occurrence = parseCalendarDate(occurrenceDate.slice(0, 10));
  return occurrence
    ? calendarDateFromDayNumber(calendarDayNumber(occurrence) - 1)
    : undefined;
}

function firstOccurrenceOnOrAfter(anchorDay: number, targetDay: number, intervalDays: number) {
  return anchorDay + Math.ceil((targetDay - anchorDay) / intervalDays) * intervalDays;
}

function moveFreshness(move: ScheduledBillDateMove): number {
  const parsed = Date.parse(move.updated_at ?? move.created_at ?? "");
  return Number.isFinite(parsed) ? parsed : 0;
}

export function isValidDateInMonth(date: string, month: number, year: number): boolean {
  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(date);
  if (!match) return false;
  const parsedYear = Number(match[1]);
  const parsedMonth = Number(match[2]);
  const day = Number(match[3]);
  return parsedYear === year && parsedMonth === month + 1 && day >= 1 && day <= new Date(year, month + 1, 0).getDate();
}

export function resolveFinalizedBillOccurrenceDays(
  occurrences: number[],
  paidDate: string | undefined,
  month: number,
  year: number,
): number[] {
  if (occurrences.length !== 1 || !paidDate || !isValidDateInMonth(paidDate, month, year)) return [...occurrences];
  return [Number(paidDate.slice(8, 10))];
}

export function moveSettledBillOverrideDate<T extends SettledBillOverride>(
  overrides: T[],
  billId: string,
  occurrenceDate: string,
  previousDate: string,
  nextDate: string,
): T[] {
  const [year, month] = occurrenceDate.slice(0, 10).split("-").map(Number);
  if (![year, month].every(Number.isFinite)) return overrides;

  return overrides.map(override => {
    const isOccurrence = override.bill_id === billId && override.year === year && override.month === month - 1;
    const isSettled = override.actual_amount !== undefined || override.paid_amount > 0.005;
    if (!isOccurrence || !isSettled || override.paid_date?.slice(0, 10) !== previousDate.slice(0, 10)) return override;
    return { ...override, paid_date: nextDate.slice(0, 10) };
  });
}

export function isBillActiveForMonth(bill: ScheduledBill, month: number, year: number): boolean {
  const date = new Date(year, month, 1);
  if (bill.start_date) {
    const [startYear, startMonth] = bill.start_date.split("-").map(Number);
    if (date < new Date(startYear, startMonth - 1, 1)) return false;
  }
  if (bill.end_date) {
    const [endYear, endMonth] = bill.end_date.split("-").map(Number);
    if (date > new Date(endYear, endMonth - 1, 1)) return false;
  }
  return true;
}

export function getBillOccurrenceDays(bill: ScheduledBill, month: number, year: number): number[] {
  if (!isBillActiveForMonth(bill, month, year)) return [];
  const daysInMonth = new Date(year, month + 1, 0).getDate();
  const withinActiveDates = (day: number) => {
    const occurrence = `${year}-${String(month + 1).padStart(2, "0")}-${String(day).padStart(2, "0")}`;
    return (!bill.start_date || occurrence >= bill.start_date.slice(0, 10))
      && (!bill.end_date || occurrence <= bill.end_date.slice(0, 10));
  };
  if (bill.frequency === "weekly") {
    const days: number[] = [];
    const dayOfWeek = bill.day_of_week ?? dateDayOfWeek(bill.next_payment_date ?? bill.start_date) ?? 0;
    for (let day = 1; day <= daysInMonth; day++) {
      if (new Date(Date.UTC(year, month, day)).getUTCDay() === dayOfWeek && withinActiveDates(day)) days.push(day);
    }
    return days;
  }
  if (bill.frequency === "biweekly") {
    return occurrenceDaysFromAnchor(bill.next_payment_date ?? bill.start_date, bill.due_day, month, year, 14)
      .filter(withinActiveDates);
  }
  if (bill.frequency === "quarterly") {
    const anchor = bill.next_payment_date ?? bill.start_date;
    const match = anchor ? /^(\d{4})-(\d{2})-(\d{2})/.exec(anchor) : null;
    if (!match) return [];
    const anchorMonthIndex = Number(match[1]) * 12 + Number(match[2]) - 1;
    const requestedMonthIndex = year * 12 + month;
    if (requestedMonthIndex < anchorMonthIndex || (requestedMonthIndex - anchorMonthIndex) % 3 !== 0) return [];
    const day = Math.min(bill.due_day || Number(match[3]), daysInMonth);
    return day > 0 && withinActiveDates(day) ? [day] : [];
  }
  const day = Math.min(bill.due_day, daysInMonth);
  return day > 0 && withinActiveDates(day) ? [day] : [];
}

/** Resolve repeat edits as one occurrence, never as additional payments. */
export function resolveBillDateMoves<T extends ScheduledBillDateMove = ScheduledBillDateMove>(
  billId: string,
  moves: T[] = [],
  activeRange?: Pick<ScheduledBill, "start_date" | "end_date"> & Partial<ScheduledBill>,
): Array<T & ScheduledBillDateMove & { edit_from_date: string; source_dates: string[] }> {
  const latest = new Map<string, T>();
  for (const move of moves) {
    if (move.bill_id !== billId || !parseCalendarDate(move.from_date)
      || (!move.is_skipped && !parseCalendarDate(move.to_date))) continue;
    const existing = latest.get(move.from_date);
    if (!existing || moveFreshness(move) >= moveFreshness(existing)) latest.set(move.from_date, move);
  }
  const isNative = (date: string) => {
    const parts = parseCalendarDate(date);
    return parts && activeRange?.frequency && activeRange.due_day !== undefined
      ? getBillOccurrenceDays(activeRange as ScheduledBill, parts.month - 1, parts.year).includes(parts.day)
      : false;
  };
  const incoming = new Set(Array.from(latest.values())
    .filter(move => !move.is_skipped && move.from_date !== move.to_date)
    .filter(move => !isNative(move.to_date))
    .map(move => move.to_date));
  const roots = Array.from(latest.keys()).filter(date => !incoming.has(date)).sort();
  // If historical edges are available, an obsolete branch has provenance.
  // Never guess that an otherwise standalone/custom occurrence is an orphan.
  const obsoleteBranch = new Set<string>();
  for (const move of moves) {
    if (move.bill_id !== billId) continue;
    const current = latest.get(move.from_date);
    if (!current || current.to_date === move.to_date || move.is_skipped) continue;
    let date = move.to_date;
    const seen = new Set<string>();
    while (latest.has(date) && !seen.has(date) && !isNative(date)) {
      seen.add(date);
      obsoleteBranch.add(date);
      date = latest.get(date)!.to_date;
    }
  }
  const visited = new Set<string>();
  const resolved: Array<T & ScheduledBillDateMove & { edit_from_date: string; source_dates: string[] }> = [];
  const follow = (root: string) => {
    if (visited.has(root)) return;
    let date = root;
    let customAmount: number | undefined;
    let skipped = false;
    let editFrom = root;
    const chain = new Set<string>();
    while (latest.has(date) && !chain.has(date)) {
      chain.add(date);
      visited.add(date);
      const move = latest.get(date)!;
      editFrom = date;
      if (move.custom_amount !== undefined) customAmount = move.custom_amount;
      if (move.is_skipped) { skipped = true; break; }
      if (move.to_date === date) break;
      date = move.to_date;
      // Another native weekly/biweekly occurrence has its own obligation. It
      // cannot be consumed as an edit continuation just because dates touch.
      if (isNative(date) && date !== root) break;
    }
    // Corrupt cycles retain one original payment instead of hanging or creating
    // phantom intermediates. A later valid edit resolves this finite component.
    if (chain.has(date) && latest.get(date)?.to_date !== date) date = root;
    if ((activeRange?.start_date && root < activeRange.start_date.slice(0, 10))
      || (activeRange?.end_date && root > activeRange.end_date.slice(0, 10))) return;
    resolved.push({ ...latest.get(root)!, ...latest.get(editFrom)!, from_date: root, to_date: date,
      custom_amount: customAmount, is_skipped: skipped, edit_from_date: editFrom, source_dates: [...chain] });
  };
  roots.filter(date => !obsoleteBranch.has(date)).forEach(follow);
  Array.from(latest.keys()).sort().filter(date => !obsoleteBranch.has(date)).forEach(follow);
  return resolved;
}

export function applyBillDateMovesToOccurrenceDays(
  billId: string,
  month: number,
  year: number,
  occurrences: number[],
  moves: ScheduledBillDateMove[] = [],
  activeRange?: Pick<ScheduledBill, "start_date" | "end_date"> & Partial<ScheduledBill>,
): number[] {
  const monthPrefix = `${year}-${String(month + 1).padStart(2, "0")}`;
  const dateFromDay = (day: number) => `${monthPrefix}-${String(day).padStart(2, "0")}`;
  const activeMoves = resolveBillDateMoves(billId, moves, activeRange);
  const kept = occurrences.filter(day => !activeMoves.some(move =>
    move.bill_id === billId && move.from_date === dateFromDay(day)
  ));
  const movedIn = activeMoves
    .filter(move => !move.is_skipped && move.to_date.startsWith(monthPrefix))
    .map(move => Number(move.to_date.slice(8, 10)))
    .filter(day => Number.isFinite(day));
  return Array.from(new Set([...kept, ...movedIn])).sort((a, b) => a - b);
}

export function isIncomeActiveForMonth(income: ScheduledIncome, month: number, year: number): boolean {
  if (!income.start_date) return true;
  const [startYear, startMonth] = income.start_date.split("-").map(Number);
  return new Date(year, month, 1) >= new Date(startYear, startMonth - 1, 1);
}

export function getIncomeOccurrenceDays(income: ScheduledIncome, month: number, year: number): number[] {
  if (!isIncomeActiveForMonth(income, month, year)) return [];
  const daysInMonth = new Date(year, month + 1, 0).getDate();
  const excludedDates = new Set(normalizeIncomeExcludedDates(income.excluded_dates));
  const isIncluded = (day: number) => {
    const occurrence = `${year}-${String(month + 1).padStart(2, "0")}-${String(day).padStart(2, "0")}`;
    return !excludedDates.has(occurrence);
  };
  const onOrAfterStart = (day: number) => {
    if (!income.start_date) return true;
    const occurrence = `${year}-${String(month + 1).padStart(2, "0")}-${String(day).padStart(2, "0")}`;
    return occurrence >= income.start_date.slice(0, 10);
  };
  if (income.frequency === "monthly") {
    const anchorDate = income.next_payment_date || income.start_date;
    if (!anchorDate) return isIncluded(1) ? [1] : [];
    const [, , day] = anchorDate.split("-").map(Number);
    const occurrenceDay = Math.min(Math.max(day || 1, 1), daysInMonth);
    return onOrAfterStart(occurrenceDay) && isIncluded(occurrenceDay) ? [occurrenceDay] : [];
  }
  const intervalDays = income.frequency === "biweekly" ? 14 : 7;
  if (!income.next_payment_date) return [];
  const anchor = parseCalendarDate(income.next_payment_date);
  if (!anchor) return [];
  const monthStart = calendarDayNumber({ year, month: month + 1, day: 1 });
  const nextMonthStart = calendarDayNumber(
    month === 11
      ? { year: year + 1, month: 1, day: 1 }
      : { year, month: month + 2, day: 1 },
  );
  let cursor = firstOccurrenceOnOrAfter(calendarDayNumber(anchor), monthStart, intervalDays);
  const days: number[] = [];
  while (cursor < nextMonthStart) {
    days.push(new Date(cursor * DAY_MS).getUTCDate());
    cursor += intervalDays;
  }
  return days.filter(day => onOrAfterStart(day) && isIncluded(day));
}

export function billOccurrenceMoveConflicts(
  bill: ScheduledBill & { id?: string },
  fromDate: string,
  toDate: string,
  moves: ScheduledBillDateMove[] = [],
): boolean {
  const cleanFrom = fromDate.slice(0, 10);
  const cleanTo = toDate.slice(0, 10);
  if (cleanFrom === cleanTo) return false;
  const target = parseCalendarDate(cleanTo);
  if (!target) return false;
  if (getBillOccurrenceDays(bill, target.month - 1, target.year).includes(target.day)) return true;
  const latestByOriginalDate = new Map<string, ScheduledBillDateMove>();
  moves.filter(move => move.bill_id === bill.id).forEach(move => {
    const existing = latestByOriginalDate.get(move.from_date);
    if (!existing || moveFreshness(move) >= moveFreshness(existing)) latestByOriginalDate.set(move.from_date, move);
  });
  return Array.from(latestByOriginalDate.values()).some(move =>
    move.from_date !== cleanFrom && !move.is_skipped && move.to_date === cleanTo
  );
}

export function getUpcomingIncomeOccurrenceDates(
  income: ScheduledIncome,
  fromDate: string,
  count = 4,
): string[] {
  const from = parseCalendarDate(fromDate);
  if (!from || !Number.isSafeInteger(count) || count < 1) return [];
  if (income.frequency === "monthly") {
    const start = parseCalendarDate(income.start_date);
    const first = start && calendarDayNumber(start) > calendarDayNumber(from) ? start : from;
    const dates: string[] = [];
    const limit = Math.min(count, 52);
    // Each excluded date can skip at most one monthly occurrence.
    const searchMonths = limit + normalizeIncomeExcludedDates(income.excluded_dates).length + 1;
    for (let offset = 0; offset < searchMonths && dates.length < limit; offset++) {
      const cursor = new Date(first.year, first.month - 1 + offset, 1);
      const year = cursor.getFullYear(), month = cursor.getMonth();
      for (const day of getIncomeOccurrenceDays(income, month, year)) {
        const date = `${year}-${String(month + 1).padStart(2, "0")}-${String(day).padStart(2, "0")}`;
        if (date >= fromDate) dates.push(date);
      }
    }
    return dates;
  }
  const anchor = parseCalendarDate(income.next_payment_date);
  if (!anchor) return [];
  const intervalDays = income.frequency === "biweekly" ? 14 : 7;
  let cursor = firstOccurrenceOnOrAfter(
    calendarDayNumber(anchor),
    Math.max(calendarDayNumber(anchor), calendarDayNumber(from)),
    intervalDays,
  );
  return Array.from({ length: Math.min(count, 52) }, () => {
    const occurrence = calendarDateFromDayNumber(cursor);
    cursor += intervalDays;
    return occurrence;
  });
}

/** Store a real first payday separately from the recurring day-31 anchor. */
export function monthlyIncomeAnchorDate(firstPayDate: string, lastDay: boolean): string {
  const first = parseCalendarDate(firstPayDate);
  if (!lastDay || !first) return firstPayDate;
  for (let offset = 0; offset <= 2; offset++) {
    const month = new Date(first.year, first.month - 1 + offset, 1);
    if (new Date(month.getFullYear(), month.getMonth() + 1, 0).getDate() === 31) {
      return `${month.getFullYear()}-${String(month.getMonth() + 1).padStart(2, "0")}-31`;
    }
  }
  return firstPayDate;
}

/**
 * A bank deposit can post a few days before or after its planned payday. Keep
 * the bank date as the cash date, but settle the nearest scheduled occurrence
 * so the forecast does not leave a second copy of the same paycheck behind.
 */
export function resolveIncomeMatchOccurrenceDate(
  income: ScheduledIncome,
  transactionDate: string,
  requestedOccurrenceDate?: string,
): string | undefined {
  const reference = /^\d{4}-\d{2}-\d{2}$/.test(transactionDate.slice(0, 10))
    ? transactionDate.slice(0, 10)
    : undefined;
  const requested = requestedOccurrenceDate && /^\d{4}-\d{2}-\d{2}$/.test(requestedOccurrenceDate.slice(0, 10))
    ? requestedOccurrenceDate.slice(0, 10)
    : undefined;
  if (!reference) return requested;

  // A reviewer may intentionally assign a deposit to a more distant payday.
  // Validate that date against its own month before applying the nearby-date
  // search, whose distance limit is only meant for stale occurrence dates.
  const requestedParts = parseCalendarDate(requested);
  if (requestedParts && getIncomeOccurrenceDays(income, requestedParts.month - 1, requestedParts.year).includes(requestedParts.day)) {
    return requested;
  }

  const candidates = getIncomeMatchOccurrenceDates(income, reference);
  return candidates[0] ?? requested ?? reference;
}

export function getIncomeMatchOccurrenceDates(
  income: ScheduledIncome,
  transactionDate: string,
  maxDistanceDays = 14,
): string[] {
  const reference = /^\d{4}-\d{2}-\d{2}$/.test(transactionDate.slice(0, 10))
    ? transactionDate.slice(0, 10)
    : undefined;
  if (!reference) return [];

  const referenceTime = Date.parse(`${reference}T00:00:00Z`);
  const [referenceYear, referenceMonth] = reference.split("-").map(Number);
  const maximumDistance = Number.isFinite(maxDistanceDays) ? Math.max(0, maxDistanceDays) : 14;
  const candidates: string[] = [];
  for (let offset = -1; offset <= 1; offset += 1) {
    const cursor = new Date(referenceYear, referenceMonth - 1 + offset, 1);
    const year = cursor.getFullYear();
    const month = cursor.getMonth();
    getIncomeOccurrenceDays(income, month, year).forEach(day => {
      candidates.push(`${year}-${String(month + 1).padStart(2, "0")}-${String(day).padStart(2, "0")}`);
    });
  }

  return candidates
    .map(date => ({ date, distance: Math.abs(Date.parse(`${date}T00:00:00Z`) - referenceTime) / 86_400_000 }))
    .filter(candidate => Number.isFinite(candidate.distance) && candidate.distance <= maximumDistance)
    .sort((left, right) => left.distance - right.distance || left.date.localeCompare(right.date))
    .map(candidate => candidate.date);
}

export function getBillMatchOccurrenceDates(
  bill: ScheduledBill & { id?: string },
  transactionDate: string,
  maxDistanceDays = 14,
  moves: ScheduledBillDateMove[] = [],
): string[] {
  const reference = parseCalendarDate(transactionDate);
  if (!reference) return [];
  const referenceDay = calendarDayNumber(reference);
  const maximumDistance = Number.isFinite(maxDistanceDays) ? Math.max(0, maxDistanceDays) : 14;
  const candidates: string[] = [];

  for (let offset = -1; offset <= 1; offset += 1) {
    const monthCursor = new Date(Date.UTC(reference.year, reference.month - 1 + offset, 1));
    const year = monthCursor.getUTCFullYear();
    const month = monthCursor.getUTCMonth();
    const originalDays = getBillOccurrenceDays(bill, month, year);
    const days = bill.id
      ? applyBillDateMovesToOccurrenceDays(bill.id, month, year, originalDays, moves, bill)
      : originalDays;
    days.forEach((day) => {
      candidates.push(`${year}-${String(month + 1).padStart(2, "0")}-${String(day).padStart(2, "0")}`);
    });
  }

  return Array.from(new Set(candidates))
    .map((date) => {
      const parts = parseCalendarDate(date)!;
      return { date, distance: Math.abs(calendarDayNumber(parts) - referenceDay) };
    })
    .filter((candidate) => candidate.distance <= maximumDistance)
    .sort((left, right) => left.distance - right.distance || left.date.localeCompare(right.date))
    .map((candidate) => candidate.date);
}

export function normalizeIncomeExcludedDates(dates: unknown): string[] {
  if (!Array.isArray(dates)) return [];
  return Array.from(new Set(
    dates
      .filter((date): date is string => typeof date === "string")
      .map(date => date.slice(0, 10))
      .filter(date => /^\d{4}-\d{2}-\d{2}$/.test(date)),
  )).sort();
}

function dateDayOfWeek(date?: string): number | null {
  const parts = parseCalendarDate(date);
  if (!parts) return null;
  return new Date(Date.UTC(parts.year, parts.month - 1, parts.day)).getUTCDay();
}

function occurrenceDaysFromAnchor(anchorDate: string | undefined, fallbackDay: number, month: number, year: number, intervalDays: number): number[] {
  const daysInMonth = new Date(year, month + 1, 0).getDate();
  const fallback = Math.min(Math.max(1, fallbackDay || 1), daysInMonth);
  const anchor = anchorDate ?? `${year}-${String(month + 1).padStart(2, "0")}-${String(fallback).padStart(2, "0")}`;
  const anchorParts = parseCalendarDate(anchor);
  if (!anchorParts) return [fallback];
  const monthStart = calendarDayNumber({ year, month: month + 1, day: 1 });
  const nextMonthStart = calendarDayNumber(
    month === 11
      ? { year: year + 1, month: 1, day: 1 }
      : { year, month: month + 2, day: 1 },
  );
  let cursor = firstOccurrenceOnOrAfter(calendarDayNumber(anchorParts), monthStart, intervalDays);

  const days: number[] = [];
  while (cursor < nextMonthStart) {
    days.push(new Date(cursor * DAY_MS).getUTCDate());
    cursor += intervalDays;
  }
  return days;
}

export function getEffectiveIncomeAmount(income: ScheduledIncome, month: number, year: number): number {
  if (!income.amount_history?.length) return income.amount;
  const target = new Date(year, month, 1);
  const sorted = [...income.amount_history].sort((a, b) => a.effective_from.localeCompare(b.effective_from));
  let effective = income.amount;
  for (const entry of sorted) {
    const [entryYear, entryMonth] = entry.effective_from.split("-").map(Number);
    if (new Date(entryYear, entryMonth - 1, 1) <= target) effective = entry.amount;
  }
  return effective;
}

export function getLatestRecordedIncomeAmount(income: ScheduledIncome): number {
  if (!income.amount_history?.length) return income.amount;
  return [...income.amount_history]
    .sort((a, b) => a.effective_from.localeCompare(b.effective_from))
    .at(-1)?.amount ?? income.amount;
}

export function incomeAmountToMonthly(amount: number, frequency: ScheduledIncome["frequency"]): number {
  if (frequency === "biweekly") return amount * 26 / 12;
  if (frequency === "weekly") return amount * 52 / 12;
  return amount;
}

export type LatestIncomeChange = {
  currentAmount: number;
  difference: number;
  effectiveFrom: string;
  monthlyDifference: number;
  previousAmount: number;
};

export function getLatestIncomeChange(income: ScheduledIncome): LatestIncomeChange | null {
  if (!income.amount_history?.length) return null;
  const sorted = [...income.amount_history].sort((a, b) => a.effective_from.localeCompare(b.effective_from));
  const latest = sorted.at(-1);
  if (!latest) return null;
  const previousAmount = sorted.length > 1 ? sorted[sorted.length - 2].amount : income.amount;
  const difference = Math.round((latest.amount - previousAmount) * 100) / 100;
  return {
    currentAmount: latest.amount,
    difference,
    effectiveFrom: latest.effective_from,
    monthlyDifference: incomeAmountToMonthly(difference, income.frequency),
    previousAmount,
  };
}

