const strictNumber = (v: unknown): number | null => (typeof v === "number" || (typeof v === "string" && /^[-+]?(?:\d+\.?\d*|\.\d+)$/.test(v.trim()))) && Number.isFinite(Number(v)) ? Number(v) : null;
