export function billBaseAmountForMonth(
  bill: Bill,
  override?: MonthlyOverride,
): number {
  const savedAmount = Number.isFinite(bill.amount)
    ? Math.max(0, bill.amount)
    : 0;
  const customAmount = override?.custom_amount;
  if (customAmount === undefined || !Number.isFinite(customAmount))
    return savedAmount;
  // Debt bills should never disappear because of a stale/blank $0 override.
  // Positive overrides still allow one-month debt payment changes from Monthly.
  if (bill.is_debt && customAmount <= 0.005) return savedAmount;
  return Math.max(0, customAmount);
}

export function toAccountSnapshot(account: Account): AccountSnapshot {
  return {
    id: account.id,
    name: account.name,
    type: account.account_type,
    currentBalance: account.current_balance,
    balanceAsOf: account.balance_as_of,
    lastReconciledAt: account.last_reconciled_at,
    active: account.is_active,
  };
}

export function parseGoalTargetDate(
  targetDate: string,
): { year: number; month: number; day: number } | null {
  const datePart = targetDate.split("T")[0];
  const [year, month, day] = datePart.split("-").map(Number);
  if (
    ![year, month, day].every(Number.isFinite) ||
    month < 1 ||
    month > 12 ||
    day < 1 ||
    day > 31
  )
    return null;
  return { year, month: month - 1, day };
}

export function getGoalRemainingAmount(
  goal: Pick<Goal, "target_amount" | "current_amount" | "closed_at">,
): number {
  return spendingBucketSummary(goal).remaining;
}

export const hasPendingSnowballBalanceApply = (
  payment: Pick<ExtraPayment, "sources">,
) => (payment.sources ?? []).some((source) => source.pendingBalanceApply);

export const remainingSnowballAllocationAmount = (
  plannedAmount: number,
  match: ReviewAllocation | undefined,
) => {
  if (!match) return Math.max(0, Number(plannedAmount) || 0);
  if (match.settlement !== "partial") return 0;
  return Math.max(
    0,
    Number(match.plannedAmount ?? plannedAmount) - Number(match.amount || 0),
  );
};

export function incomeToMonthly(
  amount: number,
  frequency: IncomeItem["frequency"],
): number {
  if (frequency === "biweekly") return (amount * 26) / 12;
  if (frequency === "weekly") return (amount * 52) / 12;
  return amount;
}

export function safeLocalDateInTimeZone(date: Date, timeZone: string): string {
  try {
    return localDateInTimeZone(date, timeZone);
  } catch {
    return localDateInTimeZone(date, "UTC");
  }
}

/** Canonical read-only projection, extracted unchanged from BudgetContext. */
export function createFinancialProjection(
  snapshot: FinancialProjectionSnapshot,
  options: FinancialProjectionOptions,
) {
  const {
    settings,
    bills,
    overrides,
    billDateMoves,
    transactions,
    deletedTransactions,
    incomes,
    goals,
    extraPayments,
    decisions,
    accounts,
    connectedBankAccounts,
    transactionAccountIdentities,
    pendingBankTransactions,
    pendingPlanMatches,
  } = snapshot;
  const now = new Date(options.now.getTime());
  const householdTimeZone = options.timeZone;
  if (!Number.isFinite(now.getTime()))
    throw new Error("A valid projection clock is required");
  // ─── Overrides ────────────────────────────────────────────────────────────────
  const overridesByBillMonth = (() => {
    const index = new Map<string, MonthlyOverride>();
    overrides.forEach((override) => {
      index.set(
        `${override.bill_id}:${override.year}-${override.month}`,
        override,
      );
    });
    return index;
  })();

  const getOverride = (billId: string, month: number, year: number) =>
    overridesByBillMonth.get(`${billId}:${year}-${month}`);

  const matchedAllocationIndexes = (() =>
    buildMatchedFinancialAllocationIndexes(transactions, incomes))();

  const reviewedBillSettlements =
    matchedAllocationIndexes.reviewedBillSettlements;

  const reviewedBillOccurrences =
    matchedAllocationIndexes.reviewedBillOccurrences;

  const debtSourceCommitments = (() =>
    debtSourceCommitmentsForDebts(
      pendingPlanMatches,
      pendingBankTransactions,
      transactions,
      bills,
    ))();

  const debtSourceCommitmentsByOccurrence = (() =>
    new Map(
      debtSourceCommitments.map((commitment) => [
        `${commitment.sourceBillId}:${commitment.date}`,
        commitment,
      ]),
    ))();

  const getDebtSourceCommitment = (billId: string, occurrenceDate: string) =>
    debtSourceCommitmentsByOccurrence.get(`${billId}:${occurrenceDate}`);

  const getAmount = (bill: Bill, month: number, year: number): number => {
    const o = overridesByBillMonth.get(`${bill.id}:${year}-${month}`);
    if (bill.is_debt && o?.planned_debt_amount !== undefined) {
      return effectiveDebtOccurrenceAmount(0, 0, o.planned_debt_amount);
    }
    const base = billBaseAmountForMonth(bill, o);
    if (!bill.is_debt) return base;
    let settledAmount: number | undefined;
    if (bill.frequency === "monthly" && getBillOccurrencesInMonth(bill, month, year).length === 1) {
      const settlementKey = `${bill.id}:${year}-${String(month + 1).padStart(2, "0")}`;
      const reviewedSettlement = reviewedBillSettlements.get(settlementKey);
      if (reviewedSettlement?.status === "settled")
        settledAmount = reviewedSettlement.actualAmount;
      else if (
        !reviewedSettlement &&
        o?.actual_amount !== undefined &&
        o.paid_date
      )
        settledAmount = o.actual_amount;
    }
    return monthlyDebtAmount(
      base,
      Number(bill.snowball_minimum_boost ?? 0),
      settledAmount,
    );
  };

  const getPaidAmount = (billId: string, month: number, year: number): number =>
    overridesByBillMonth.get(`${billId}:${year}-${month}`)?.paid_amount ?? 0;

  const getCustomDueDay = (
    billId: string,
    month: number,
    year: number,
  ): number | undefined =>
    overridesByBillMonth.get(`${billId}:${year}-${month}`)?.custom_due_day;

  const applyBillDateMovesToOccurrences = (
    bill: Bill,
    month: number,
    year: number,
    occurrences: number[],
  ): number[] =>
    applyBillDateMovesToOccurrenceDays(
      bill.id,
      month,
      year,
      occurrences,
      billDateMoves,
      bill,
    );

  const getBillOccurrencesInMonth = (
    bill: Bill,
    month: number,
    year: number,
  ): number[] => {
    const daysInMonth = new Date(year, month + 1, 0).getDate();
    let occ = getBillOccurrenceDays(bill, month, year);
    const o = overridesByBillMonth.get(`${bill.id}:${year}-${month}`);
    if (
      o?.custom_due_day !== undefined &&
      (bill.frequency === "monthly" || bill.frequency === "quarterly")
    ) {
      occ = [Math.min(o.custom_due_day, daysInMonth)];
    }
    return applyBillDateMovesToOccurrences(bill, month, year, occ);
  };

  const getBillOccurrenceAmount = (bill: Bill, occurrenceDate: string): number => {
    const cleanDate = occurrenceDate.slice(0, 10);
    const exception = resolveBillDateMoves(bill.id, billDateMoves, bill)
      .filter(move => !move.is_skipped
        && (move.from_date === cleanDate || move.to_date === cleanDate))
      .sort((left, right) => String(right.updated_at ?? right.created_at).localeCompare(String(left.updated_at ?? left.created_at)))[0];
    return exception?.custom_amount !== undefined
      ? Math.max(0, exception.custom_amount)
      : getAmount(bill, Number(cleanDate.slice(5, 7)) - 1, Number(cleanDate.slice(0, 4)));
  };

  const getBillMonthlyTotal = (
    bill: Bill,
    month: number,
    year: number,
  ): number => {
    const occurrences = getBillOccurrencesInMonth(bill, month, year);
    if (occurrences.length === 0) return 0;
    return occurrences.reduce((total, day) => total + getBillOccurrenceAmount(
      bill,
      `${year}-${String(month + 1).padStart(2, "0")}-${String(day).padStart(2, "0")}`,
    ), 0);
  };

  const getBillEffectiveMonthlyTotal = (
    bill: Bill,
    month: number,
    year: number,
  ): number => {
    const override = overridesByBillMonth.get(`${bill.id}:${year}-${month}`);
    return override?.actual_amount !== undefined
      ? Math.max(0, override.actual_amount)
      : getBillMonthlyTotal(bill, month, year);
  };

  const monthlyBillsCache = (() => new Map<string, Bill[]>())();

  const getMonthlyBills = (month: number, year: number): Bill[] => {
    const key = `${year}-${month}`;
    const cached = monthlyBillsCache.get(key);
    if (cached) return cached;
    const result = bills.filter(
      (b) =>
        (b.is_recurring || b.is_debt) &&
        (isBillActiveForMonth(b, month, year) ||
          getBillOccurrencesInMonth(b, month, year).length > 0),
    );
    monthlyBillsCache.set(key, result);
    return result;
  };

  const debtMonthSettlementsCache = (() =>
    new Map<string, Map<string, DebtMonthSettlement>>())();

  const getDebtMonthSettlements = (month: number, year: number) => {
    const cacheKey = `${year}-${month}`;
    const cached = debtMonthSettlementsCache.get(cacheKey);
    if (cached) return cached;
    const result = new Map<string, DebtMonthSettlement>();
    getMonthlyBills(month, year)
      .filter((bill) => bill.is_debt)
      .forEach((bill) => {
        const override = overridesByBillMonth.get(
          `${bill.id}:${year}-${month}`,
        );
        const occurrenceDates = getBillOccurrencesInMonth(
          bill,
          month,
          year,
        ).map(
          (day) =>
            `${year}-${String(month + 1).padStart(2, "0")}-${String(day).padStart(2, "0")}`,
        );
        const reviewedForMonth = occurrenceDates.map((date) =>
          reviewedBillOccurrences.get(occurrenceKey(bill.id, date)),
        );
        const hasReviewedOccurrence = reviewedForMonth.some(Boolean);
        const rawSnapshotTotal = override?.required_debt_amount;
        const snapshotTotal =
          rawSnapshotTotal !== undefined && Number.isFinite(rawSnapshotTotal)
            ? Math.max(0, rawSnapshotTotal)
            : undefined;
        const snapshotParts = occurrenceDates.map((_, index) => {
          // A monthly legacy snapshot cannot identify an unreviewed sibling
          // once a separately reviewed, moved-in cycle is also in this month.
          // Keep each dated review authoritative and the sibling's own minimum.
          if (snapshotTotal === undefined || occurrenceDates.length === 0
            || (bill.frequency === "monthly" && hasReviewedOccurrence && occurrenceDates.length > 1))
            return undefined;
          const allocatedBefore =
            Math.round((snapshotTotal / occurrenceDates.length) * index * 100) /
            100;
          const allocatedThrough =
            index === occurrenceDates.length - 1
              ? snapshotTotal
              : Math.round(
                  (snapshotTotal / occurrenceDates.length) * (index + 1) * 100,
                ) / 100;
          return Math.max(0, allocatedThrough - allocatedBefore);
        });
        const fallbackPaidByDate = new Map<string, number>();
        if (!hasReviewedOccurrence && occurrenceDates.length > 0) {
          let paidRemaining = Math.max(
            0,
            Number(override?.actual_amount ?? override?.paid_amount) || 0,
          );
          const paidDate = override?.paid_date?.slice(0, 10);
          const orderedDates = [
            ...(paidDate && occurrenceDates.includes(paidDate)
              ? [paidDate]
              : []),
            ...occurrenceDates.filter((date) => date !== paidDate),
          ];
          orderedDates.forEach((date) => {
            const index = occurrenceDates.indexOf(date);
            const required =
              snapshotParts[index] ?? Math.max(0, Number(bill.amount) || 0);
            const applied = Math.min(required, paidRemaining);
            fallbackPaidByDate.set(date, applied);
            paidRemaining = Math.max(0, paidRemaining - applied);
          });
          if (paidRemaining > 0.005) {
            const extraDate =
              paidDate && occurrenceDates.includes(paidDate)
                ? paidDate
                : orderedDates[orderedDates.length - 1];
            if (extraDate) {
              fallbackPaidByDate.set(
                extraDate,
                (fallbackPaidByDate.get(extraDate) ?? 0) + paidRemaining,
              );
            }
          }
        }
        const occurrenceSettlements = occurrenceDates.map((date, index) =>
          resolveDebtOccurrenceSettlement({
            occurrenceDate: date,
            configuredObligation: bill.amount,
            reviewed: reviewedForMonth[index],
            paidAmount: fallbackPaidByDate.get(date) ?? 0,
            requiredAmountSnapshot: snapshotParts[index],
          }),
        );
        result.set(
          bill.id,
          summarizeDebtOccurrenceSettlements(
            occurrenceSettlements,
            override?.planned_debt_amount,
          ),
        );
      });
    debtMonthSettlementsCache.set(cacheKey, result);
    return result;
  };

  const getExtraPayment = (month: number, year: number) =>
    extraPayments.find(
      (ep) =>
        ep.month === month && ep.year === year && isValidExtraPaymentPlan(ep),
    );

  const debtSourceCommitmentsByMonth = (() =>
    indexRecordsByMonth(debtSourceCommitments))();

  const extraPaymentsByMonth = (() =>
    new Map(
      extraPayments
        .filter(isValidExtraPaymentPlan)
        .map(
          (payment) => [`${payment.year}-${payment.month}`, payment] as const,
        ),
    ))();

  interface DebtPlanProjectionCacheEntry {
    result: DatedSnowballMonthPlanResult;
    endingBalances: Map<string, number>;
    rolledPayment: number;
  }

  const debtPlanProjectionCache = (() =>
    new Map<string, DebtPlanProjectionCacheEntry>())();

  const getDebtPlanForMonth = (
    month: number,
    year: number,
  ): DatedSnowballMonthPlanResult | null => {
    if (!settings.debtPayoffEnabled) return null;
    const debtPlanAsOfMonth = safeLocalDateInTimeZone(
      now,
      householdTimeZone,
    ).slice(0, 7);
    const [startYear, startMonthNumber] = debtPlanAsOfMonth
      .split("-")
      .map(Number);
    const startMonth = startMonthNumber - 1;
    if (year < startYear || (year === startYear && month < startMonth))
      return null;
    const requestedKey = financialProjectionMonthCacheKey(
      debtPlanAsOfMonth,
      month,
      year,
    );
    const cachedRequested = debtPlanProjectionCache.get(requestedKey);
    if (cachedRequested) return cachedRequested.result;
    const debtBills = bills.filter((bill) => bill.is_debt);
    if (!debtBills.length) return null;
    const debtBillsById = new Map(debtBills.map((bill) => [bill.id, bill]));
    let balances = new Map(
      debtBills.map((bill) => [
        bill.id,
        Math.max(0, Number(bill.balance) || 0),
      ]),
    );
    // Persisted boosts are the already-freed snowball pool. Keep that money in
    // the forecast, but feed it to the allocator as rollover so it never becomes
    // part of a creditor's required minimum.
    let rolledPayment = snowballRolloverPlanTotal(debtBills);
    let result: DatedSnowballMonthPlanResult | null = null;
    let cursorMonth = startMonth;
    let cursorYear = startYear;
    let guard = 0;
    // Reuse the closest completed predecessor. A September read after August
    // no longer replays the complete August snowball projection.
    let priorMonth = month - 1;
    let priorYear = year;
    if (priorMonth < 0) {
      priorMonth = 11;
      priorYear -= 1;
    }
    while (
      priorYear > startYear ||
      (priorYear === startYear && priorMonth >= startMonth)
    ) {
      const predecessor = debtPlanProjectionCache.get(
        financialProjectionMonthCacheKey(
          debtPlanAsOfMonth,
          priorMonth,
          priorYear,
        ),
      );
      if (predecessor) {
        balances = new Map(predecessor.endingBalances);
        rolledPayment = predecessor.rolledPayment;
        cursorMonth = priorMonth + 1;
        cursorYear = priorYear;
        if (cursorMonth > 11) {
          cursorMonth = 0;
          cursorYear += 1;
        }
        break;
      }
      priorMonth -= 1;
      if (priorMonth < 0) {
        priorMonth = 11;
        priorYear -= 1;
      }
    }
    while (
      (cursorYear < year || (cursorYear === year && cursorMonth <= month)) &&
      guard < 240
    ) {
      const monthSettlements = getDebtMonthSettlements(cursorMonth, cursorYear);
      const cursorPrefix = `${cursorYear}-${String(cursorMonth + 1).padStart(2, "0")}`;
      const authoritativePaidByDebtId = new Map(
        debtBills.map((bill) => [
          bill.id,
          authoritativeDebtPaidAmountForMonth(
            monthSettlements.get(bill.id)?.paidAmount ?? 0,
            debtSourceCommitments,
            bill.id,
            cursorPrefix,
          ),
        ]),
      );
      const exactPlanDebtIds = new Set<string>();
      const debtsForMonth: DatedSnowballDebtInput[] = debtBills
        .filter((bill) => isBillActiveForMonth(bill, cursorMonth, cursorYear))
        .map((bill) => {
          const occurrenceCount = getBillOccurrencesInMonth(
            bill,
            cursorMonth,
            cursorYear,
          ).length;
          const currentRequiredAmount = requiredDebtPlanTotal(
            bill,
            occurrenceCount,
          );
          const override = overridesByBillMonth.get(
            `${bill.id}:${cursorYear}-${cursorMonth}`,
          );
          const exactPlannedAmount = exactDebtPlanTotal({
            plannedDebtAmount: override?.planned_debt_amount,
            customAmount: override?.custom_amount,
            occurrenceCount,
          });
          if (exactPlannedAmount !== undefined) exactPlanDebtIds.add(bill.id);
          const settlement = monthSettlements.get(bill.id);
          const requiredObligation =
            settlement?.configuredObligation ?? currentRequiredAmount;
          const payment = debtPlanPaymentBreakdown(
            requiredObligation,
            exactPlannedAmount,
          );
          const paidTowardExtra = Math.max(
            0,
            (authoritativePaidByDebtId.get(bill.id) ?? 0) - requiredObligation,
          );
          let requiredCashRemaining =
            settlement?.status === "settled" ? 0 : payment.requiredPayment;
          const requiredPaymentsByDate = settlement?.occurrences?.length
            ? new Map(
                settlement.occurrences.map((occurrence) => {
                  const amount = Math.min(
                    occurrence.configuredObligation,
                    requiredCashRemaining,
                  );
                  requiredCashRemaining = Math.max(
                    0,
                    requiredCashRemaining - amount,
                  );
                  return [occurrence.occurrenceDate, amount] as const;
                }),
              )
            : undefined;
          return {
            id: bill.id,
            name: bill.name,
            balance:
              balances.get(bill.id) ?? Math.max(0, Number(bill.balance) || 0),
            // `minimum` is always the original lender requirement. Current
            // Forecast edits are split into required cash and targeted extra.
            minimum: currentRequiredAmount,
            requiredPayment:
              settlement?.status === "settled" ? 0 : payment.requiredPayment,
            requiredPaymentsByDate,
            plannedExtraPayment: Math.max(
              0,
              payment.plannedExtraPayment - paidTowardExtra,
            ),
            apr: Number(bill.interest_rate) || 0,
            dueDay: bill.due_day,
            included: bill.include_in_snowball !== false,
          };
        });
      const paymentDatesByDebtId = new Map(
        debtsForMonth.map((debt) => {
          const bill = debtBillsById.get(debt.id);
          const dates = bill
            ? getBillOccurrencesInMonth(bill, cursorMonth, cursorYear).map(
                (day) =>
                  `${cursorYear}-${String(cursorMonth + 1).padStart(2, "0")}-${String(day).padStart(2, "0")}`,
              )
            : [];
          return [debt.id, dates] as const;
        }),
      );
      const savedExtra = extraPaymentsByMonth.get(
        `${cursorYear}-${cursorMonth}`,
      );
      const automaticTarget = orderDebts(
        debtsForMonth.filter((debt) => debt.included && debt.balance > 0.009),
        settings.paymentMethod,
      )[0];
      // A reviewed, pending, or posted-review payment above the lender minimum
      // has already consumed that much of this month's automatic rollover.
      const rolloverAlreadyPaid = automaticTarget
        ? Math.max(
            0,
            (authoritativePaidByDebtId.get(automaticTarget.id) ?? 0) -
              (monthSettlements.get(automaticTarget.id)?.configuredObligation ??
                automaticTarget.minimum),
          )
        : 0;
      const rolledPaymentForMonth = automaticDebtRolloverForMonth(
        rolledPayment,
        automaticTarget?.id,
        exactPlanDebtIds,
        rolloverAlreadyPaid,
      );
      result = projectDatedSnowballMonth({
        debts: debtsForMonth,
        method: settings.paymentMethod,
        month: cursorMonth,
        year: cursorYear,
        paymentDatesByDebtId,
        startingBalances: balances,
        rolledPayment: rolledPaymentForMonth,
        extraPayment: savedExtra
          ? {
              amount: savedExtra.amount,
              date:
                savedExtra.payment_date ??
                `${cursorYear}-${String(cursorMonth + 1).padStart(2, "0")}-01`,
            }
          : undefined,
      });
      const allocationsAfterReviewedPayments =
        remainingDebtAllocationsAfterReviewedPayments(
          result.allocations,
          monthSettlements,
        );
      const advancePlan = {
        ...result,
        allocations: allocationsAfterReviewedPayments,
        plannedPayment: allocationsAfterReviewedPayments.reduce(
          (sum, allocation) => sum + allocation.amount,
          0,
        ),
      };
      const projected = advanceDebtProjectionWithCommitments(
        advancePlan,
        debtsForMonth,
        rolledPayment,
        debtSourceCommitmentsByMonth.get(cursorPrefix) ?? [],
        result.allocations,
      );
      balances = projected.balances;
      rolledPayment = projected.rolledPayment;
      debtPlanProjectionCache.set(
        financialProjectionMonthCacheKey(
          debtPlanAsOfMonth,
          cursorMonth,
          cursorYear,
        ),
        {
          result,
          endingBalances: new Map(balances),
          rolledPayment,
        },
      );
      if (cursorYear === year && cursorMonth === month) break;
      cursorMonth += 1;
      if (cursorMonth > 11) {
        cursorMonth = 0;
        cursorYear += 1;
      }
      guard += 1;
    }
    return result;
  };

  const remainingDebtPlanCache = (() =>
    new Map<string, DatedSnowballMonthPlanResult | null>())();

  const getRemainingDebtPlanForMonth = (
    month: number,
    year: number,
  ): DatedSnowballMonthPlanResult | null => {
    const cacheKey = financialProjectionMonthCacheKey(
      safeLocalDateInTimeZone(now, householdTimeZone).slice(0, 7),
      month,
      year,
    );
    if (remainingDebtPlanCache.has(cacheKey)) {
      return remainingDebtPlanCache.get(cacheKey) ?? null;
    }
    const plan = getDebtPlanForMonth(month, year);
    if (!plan) {
      remainingDebtPlanCache.set(cacheKey, null);
      return null;
    }
    const billMatches = matchedAllocationIndexes.bill;
    const snowballMatches = matchedAllocationIndexes.snowball;
    const debtSettlements = getDebtMonthSettlements(month, year);
    const monthPrefix = `${year}-${String(month + 1).padStart(2, "0")}`;
    const reviewedBillIds =
      matchedAllocationIndexes.reviewedBillIdsByMonth.get(monthPrefix) ??
      new Set<string>();
    const overridePaidRemaining = new Map(
      Array.from(debtSettlements)
        .filter(
          ([billId, settlement]) =>
            !reviewedBillIds.has(billId) && settlement.paidAmount > 0.005,
        )
        .map(([billId, settlement]) => [billId, settlement.paidAmount]),
    );
    const settlements: DatedDebtSettlement[] = [];
    const seen = new Set<string>();
    plan.allocations.forEach((allocation) => {
      const sourceType = allocation.kind === "extra" ? "extra" : "bill";
      const billId =
        allocation.kind === "extra"
          ? allocation.targetBillId
          : allocation.sourceBillId;
      if (!billId) return;
      const key = `${sourceType}:${billId}:${allocation.date}`;
      if (seen.has(key)) return;
      seen.add(key);
      const match =
        sourceType === "extra"
          ? snowballMatches.get(occurrenceKey(billId, allocation.date))
          : billMatches.get(occurrenceKey(billId, allocation.date));
      if (match && Number(match.amount) > 0.005) {
        settlements.push({
          sourceType,
          billId,
          date: allocation.date,
          amount: Number(match.amount),
        });
      } else if (sourceType === "bill") {
        const fallbackPaid = overridePaidRemaining.get(billId) ?? 0;
        if (fallbackPaid <= 0.005) return;
        const applied = Math.min(
          fallbackPaid,
          Math.max(allocation.sourceAmount, allocation.amount),
        );
        settlements.push({
          sourceType,
          billId,
          date: allocation.date,
          amount: applied,
        });
        overridePaidRemaining.set(billId, Math.max(0, fallbackPaid - applied));
      }
    });
    const allocationsAfterSettlements = remainingDatedDebtAllocations(
      plan.allocations,
      settlements,
    );
    const sourceCommitments =
      debtSourceCommitmentsByMonth.get(monthPrefix) ?? [];
    const allocations = applyDebtSourceCommitments(
      allocationsAfterSettlements,
      sourceCommitments,
    );
    const result = {
      ...plan,
      allocations,
      plannedPayment: allocations.reduce(
        (sum, allocation) => sum + allocation.amount,
        0,
      ),
    };
    remainingDebtPlanCache.set(cacheKey, result);
    return result;
  };

  const getMonthlyIncome = (month?: number, year?: number) =>
    incomes
      .filter((i) =>
        month !== undefined && year !== undefined
          ? isIncomeActiveForMonth(i, month, year)
          : true,
      )
      .reduce((s, i) => {
        if (month !== undefined && year !== undefined) {
          const amt = getEffectiveIncomeAmount(i, month, year);
          return s + getIncomeOccurrenceDays(i, month, year).length * amt;
        }
        return (
          s + incomeToMonthly(getLatestRecordedIncomeAmount(i), i.frequency)
        );
      }, 0);

  const getIncomeOccurrencesInMonth = (month: number, year: number) =>
    incomes
      .filter((i) => isIncomeActiveForMonth(i, month, year))
      .map((i) => ({
        income: i,
        days: getIncomeOccurrenceDays(i, month, year),
        effectiveAmount: getEffectiveIncomeAmount(i, month, year),
      }))
      .filter((x) => x.days.length > 0);

  // ─── Cash Flow ────────────────────────────────────────────────────────────────
  const transactionLedger = (() =>
    buildTransactionLedger(
      [...transactions, ...deletedTransactions],
      transactions,
      transactionAccountIdentities,
      { suppressedTransactionIds: pendingManualReplacementIds(transactions, pendingPlanMatches, transactionAccountIdentities, bills) },
    ))();

  const forecastTransactionsByMonth = transactionLedger.cashTransactionsByMonth;

  const visibleCheckingTransactionsByDate =
    transactionLedger.visibleCheckingTransactionsByDate;

  const visibleTransactionIds = (() =>
    new Set(
      transactionLedger.visibleTransactions.map(
        (transaction) => transaction.id,
      ),
    ))();

  const buildCashFlow = (month: number, year: number): CashFlow => {
    const billMatches = matchedAllocationIndexes.bill;
    const incomeMatches = matchedAllocationIndexes.income;
    const snowballMatches = matchedAllocationIndexes.snowball;
    const monthlyIncome = incomes
      .filter((i) => isIncomeActiveForMonth(i, month, year))
      .reduce((sum, income) => {
        const amount = getEffectiveIncomeAmount(income, month, year);
        return (
          sum +
          getIncomeOccurrenceDays(income, month, year).reduce(
            (occurrenceSum, day) => {
              const date = `${year}-${String(month + 1).padStart(2, "0")}-${String(day).padStart(2, "0")}`;
              const match = incomeMatches.get(occurrenceKey(income.id, date));
              const remaining = remainingPlannedAmount(amount, match);
              return occurrenceSum + remaining;
            },
            0,
          )
        );
      }, 0);
    const activeBills = getMonthlyBills(month, year).filter(
      isBillEligibleForUpcomingPlan,
    );
    const debtPlan = getRemainingDebtPlanForMonth(month, year);
    const totalBillsDue = activeBills.reduce((sum, bill) => {
      if (bill.is_debt && debtPlan) return sum;
      const occurrences = getBillOccurrencesInMonth(bill, month, year);
      return (
        sum +
        occurrences.reduce((occurrenceSum, day) => {
          const date = `${year}-${String(month + 1).padStart(2, "0")}-${String(day).padStart(2, "0")}`;
          const match = billMatches.get(occurrenceKey(bill.id, date));
          const remaining = remainingPlannedAmount(getBillOccurrenceAmount(bill, date), match);
          return occurrenceSum + remaining;
        }, 0)
      );
    }, debtPlan?.plannedPayment ?? 0);
    const monthPrefix = `${year}-${String(month + 1).padStart(2, "0")}`;
    const totalPaid =
      matchedAllocationIndexes.paidBillAmountByMonth.get(monthPrefix) ?? 0;
    const monthTxs = forecastTransactionsByMonth.get(monthPrefix) ?? [];
    const netTransactions = monthTxs.reduce((s, t) => s + t.amount, 0);
    const snowballPayment = extraPayments.find(
      (ep) => ep.month === month && ep.year === year,
    );
    const snowballPaymentDate =
      snowballPayment?.payment_date ??
      `${year}-${String(month + 1).padStart(2, "0")}-01`;
    const snowballExtra = debtPlan
      ? 0
      : (snowballPayment?.allocations.reduce(
          (sum, allocation) =>
            sum +
            remainingSnowballAllocationAmount(
              allocation.payment,
              snowballMatches.get(
                occurrenceKey(allocation.billId, snowballPaymentDate),
              ),
            ),
          0,
        ) ?? 0);
    const monthEnd = `${monthPrefix}-${String(new Date(year, month + 1, 0).getDate()).padStart(2, "0")}`;
    const plannedDecisionNet = decisions
      .filter((d) => d.status === "planned" || d.status === "calendar")
      .reduce((sum, d) => {
        const occurrences = scenarioDates(d.scenario, monthEnd).filter((date) =>
          date.startsWith(monthPrefix),
        ).length;
        const signedAmount =
          d.scenario.type === "income_change"
            ? Math.abs(d.scenario.amount)
            : -Math.abs(d.scenario.amount);
        return sum + occurrences * signedAmount;
      }, 0);
    const goalAllocations = goals.reduce((sum, goal) => {
      if (goal.goal_type !== "planned_expense" || goal.archived_at || !goal.target_date) return sum;
      const target = parseGoalTargetDate(goal.target_date);
      return target?.year === year && target.month === month
        ? sum + getGoalRemainingAmount(goal)
        : sum;
    }, 0);
    return {
      monthlyIncome,
      totalBillsDue,
      totalPaid,
      netTransactions,
      goalAllocations,
      remaining:
        monthlyIncome -
        totalBillsDue -
        goalAllocations -
        snowballExtra +
        netTransactions +
        plannedDecisionNet,
    };
  };

  const cashFlowComputationCache = (() => new Map<string, CashFlow>())();

  const getCashFlow = (month: number, year: number): CashFlow =>
    getOrComputeRevisionValue(
      cashFlowComputationCache,
      financialProjectionMonthCacheKey(
        safeLocalDateInTimeZone(now, householdTimeZone),
        month,
        year,
      ),
      () => buildCashFlow(month, year),
    );

  // ─── Daily Balances ───────────────────────────────────────────────────────────
  const balanceComputationCache = (() => ({
    monthNet: new Map<string, number>(),
    carryover: new Map<string, number>(),
    bankAnchoredCarryover: new Set<string>(),
    daily: new Map<string, DailyBalance[]>(),
  }))();

  const buildDailyBalances = (month: number, year: number): DailyBalance[] => {
    const projectionAsOfDate = safeLocalDateInTimeZone(now, householdTimeZone);
    const requestedDebtPlan = getRemainingDebtPlanForMonth(month, year);
    const daysInMonth = new Date(year, month + 1, 0).getDate();
    const connectedBankAnchor = connectedCheckingObservedAnchor(
      connectedBankAccounts,
      householdTimeZone,
    );
    const bankAnchor =
      connectedBankAnchor ??
      operatingAccountAnchor(accounts.map(toAccountSnapshot));
    const computeMonthNet = (
      m: number,
      y: number,
      startExclusive?: string,
    ): number => {
      const key = financialProjectionMonthCacheKey(projectionAsOfDate, m, y);
      const cached = startExclusive
        ? undefined
        : balanceComputationCache.monthNet.get(key);
      if (cached !== undefined) return cached;
      const monthPrefix = `${y}-${String(m + 1).padStart(2, "0")}`;
      const planStartDate = settings.starting_balance_date;
      const includeDate = (date: string) =>
        (!planStartDate ||
          !planStartDate.startsWith(monthPrefix) ||
          date >= planStartDate) &&
        (!startExclusive || date > startExclusive);
      const billMatches = matchedAllocationIndexes.bill;
      const incomeMatches = matchedAllocationIndexes.income;
      const snowballMatches = matchedAllocationIndexes.snowball;
      const inc = incomes.reduce((sum, income) => {
        const amount = getEffectiveIncomeAmount(income, m, y);
        return (
          sum +
          getIncomeOccurrenceDays(income, m, y).reduce((occurrenceSum, day) => {
            const date = `${monthPrefix}-${String(day).padStart(2, "0")}`;
            if (!includeDate(date)) return occurrenceSum;
            const match = incomeMatches.get(occurrenceKey(income.id, date));
            return occurrenceSum + remainingPlannedAmount(amount, match);
          }, 0)
        );
      }, 0);
      const debtPlan = getRemainingDebtPlanForMonth(m, y);
      const bil = bills
        .filter(
          (b) =>
            (b.is_recurring || b.is_debt) && isBillEligibleForUpcomingPlan(b),
        )
        .reduce((s, b) => {
          const occ = getBillOccurrencesInMonth(b, m, y);
          if (occ.length === 0) return s;
          const hasReviewedOccurrence =
            matchedAllocationIndexes.reviewedBillIdsByMonth
              .get(monthPrefix)
              ?.has(b.id) ?? false;
          const override = overridesByBillMonth.get(`${b.id}:${y}-${m}`);
          if (b.is_debt && debtPlan) return s;
          const total = hasReviewedOccurrence
            ? getBillMonthlyTotal(b, m, y)
            : getBillEffectiveMonthlyTotal(b, m, y);
          if (total <= 0.005) return s;
          const dates = occ.map(
            (day) => `${monthPrefix}-${String(day).padStart(2, "0")}`,
          );
          return (
            s +
            dates.filter(includeDate).reduce((occurrenceSum, date) => {
              const match = billMatches.get(occurrenceKey(b.id, date));
              return (
                occurrenceSum +
                (override?.actual_amount !== undefined && !hasReviewedOccurrence
                  ? remainingPlannedAmount(total / dates.length, match)
                  : resolveBillOccurrencePayment({
                    occurrenceDate: date,
                    scheduledAmount: getBillOccurrenceAmount(b, date),
                    frequency: b.frequency,
                    match,
                    monthlyPaidAmount: override?.paid_amount,
                    monthlyPaidDate: override?.paid_date,
                  }).remainingAmount)
              );
            }, 0)
          );
        }, 0);
      const tx = (forecastTransactionsByMonth.get(monthPrefix) ?? [])
        .filter((t) => includeDate(t.date))
        .reduce((s, t) => s + t.amount, 0);
      const goalDeductions = goals.reduce((s, g) => {
        if (g.goal_type !== "planned_expense" || g.archived_at) return s;
        if (!g.target_date) return s;
        const targetDate = parseGoalTargetDate(g.target_date);
        const date = targetDate
          ? `${targetDate.year}-${String(targetDate.month + 1).padStart(2, "0")}-${String(targetDate.day).padStart(2, "0")}`
          : "";
        if (
          targetDate?.year === y &&
          targetDate.month === m &&
          includeDate(date)
        )
          return s + getGoalRemainingAmount(g);
        return s;
      }, 0);
      const snowball = debtPlan
        ? debtPlan.allocations
            .filter((allocation) => includeDate(allocation.date))
            .reduce((sum, allocation) => sum + allocation.amount, 0)
        : (() => {
            const monthlyExtra = extraPayments.find(
              (ep) => ep.month === m && ep.year === y,
            );
            const monthlyExtraDate =
              monthlyExtra?.payment_date ?? `${monthPrefix}-01`;
            return monthlyExtra && includeDate(monthlyExtraDate)
              ? monthlyExtra.allocations.reduce(
                  (sum, allocation) =>
                    sum +
                    remainingSnowballAllocationAmount(
                      allocation.payment,
                      snowballMatches.get(
                        occurrenceKey(allocation.billId, monthlyExtraDate),
                      ),
                    ),
                  0,
                )
              : 0;
          })();
      const monthEnd = `${y}-${String(m + 1).padStart(2, "0")}-${String(new Date(y, m + 1, 0).getDate()).padStart(2, "0")}`;
      const decisionNet = decisions
        .filter((d) => d.status === "planned" || d.status === "calendar")
        .reduce((sum, d) => {
          const count = scenarioDates(d.scenario, monthEnd).filter(
            (date) => date.startsWith(monthPrefix) && includeDate(date),
          ).length;
          const signed =
            d.scenario.type === "income_change"
              ? d.scenario.amount
              : -Math.abs(d.scenario.amount);
          return sum + count * signed;
        }, 0);
      const net = inc + tx - bil - goalDeductions - snowball + decisionNet;
      if (!startExclusive) balanceComputationCache.monthNet.set(key, net);
      return net;
    };
    const computeCarryover = (toMonth: number, toYear: number): number => {
      const key = financialProjectionMonthCacheKey(
        projectionAsOfDate,
        toMonth,
        toYear,
      );
      const cached = balanceComputationCache.carryover.get(key);
      if (cached !== undefined) return cached;
      const previousMonth = toMonth === 0 ? 11 : toMonth - 1;
      const previousYear = toMonth === 0 ? toYear - 1 : toYear;
      const previousKey = financialProjectionMonthCacheKey(
        projectionAsOfDate,
        previousMonth,
        previousYear,
      );
      if (bankAnchor) {
        const [bankYear, bankMonth] = bankAnchor.date.split("-").map(Number);
        const bankMonthIndex = bankMonth - 1;
        if (
          toYear > bankYear ||
          (toYear === bankYear && toMonth > bankMonthIndex)
        ) {
          const previousOpening =
            balanceComputationCache.carryover.get(previousKey);
          if (
            previousOpening !== undefined &&
            balanceComputationCache.bankAnchoredCarryover.has(previousKey)
          ) {
            const running =
              previousOpening + computeMonthNet(previousMonth, previousYear);
            balanceComputationCache.carryover.set(key, running);
            balanceComputationCache.bankAnchoredCarryover.add(key);
            return running;
          }
          // The observed month owns anchoring and unpaid reserves. Seed from
          // its exact closing balance, not a date-exclusive approximation.
          let running = buildDailyBalances(bankMonthIndex, bankYear).at(-1)?.balance ?? bankAnchor.balance;
          let m = bankMonthIndex + 1;
          let y = bankYear;
          if (m > 11) {
            m = 0;
            y += 1;
          }
          balanceComputationCache.carryover.set(
            financialProjectionMonthCacheKey(projectionAsOfDate, m, y),
            running,
          );
          balanceComputationCache.bankAnchoredCarryover.add(
            financialProjectionMonthCacheKey(projectionAsOfDate, m, y),
          );
          while (!(y === toYear && m === toMonth)) {
            running += computeMonthNet(m, y);
            m += 1;
            if (m > 11) {
              m = 0;
              y += 1;
            }
            balanceComputationCache.carryover.set(
              financialProjectionMonthCacheKey(projectionAsOfDate, m, y),
              running,
            );
            balanceComputationCache.bankAnchoredCarryover.add(
              financialProjectionMonthCacheKey(projectionAsOfDate, m, y),
            );
          }
          balanceComputationCache.carryover.set(key, running);
          return running;
        }
      }
      const previousOpening =
        balanceComputationCache.carryover.get(previousKey);
      if (previousOpening !== undefined) {
        const running =
          previousOpening + computeMonthNet(previousMonth, previousYear);
        balanceComputationCache.carryover.set(key, running);
        return running;
      }
      let anchorM: number, anchorY: number;
      if (settings.starting_balance_date) {
        const [sbY, sbM] = settings.starting_balance_date
          .split("-")
          .map(Number);
        anchorY = sbY;
        anchorM = sbM - 1;
      } else {
        const [asOfYear, asOfMonthNumber] = projectionAsOfDate
          .split("-")
          .map(Number);
        anchorM = asOfMonthNumber - 2;
        anchorY = asOfYear;
        if (anchorM < 0) {
          anchorM = 11;
          anchorY -= 1;
        }
      }
      if (toYear < anchorY || (toYear === anchorY && toMonth < anchorM))
        return 0;
      if (toYear === anchorY && toMonth === anchorM) {
        balanceComputationCache.carryover.set(key, settings.starting_balance);
        return settings.starting_balance;
      }
      let running = settings.starting_balance;
      let m = anchorM,
        y = anchorY;
      while (!(y === toYear && m === toMonth)) {
        running += computeMonthNet(m, y);
        m += 1;
        if (m > 11) {
          m = 0;
          y += 1;
        }
        balanceComputationCache.carryover.set(
          financialProjectionMonthCacheKey(projectionAsOfDate, m, y),
          running,
        );
      }
      balanceComputationCache.carryover.set(key, running);
      return running;
    };
    const carryover = computeCarryover(month, year);
    const financialEvents: FinancialEvent[] = [];
    const billMatches = matchedAllocationIndexes.bill;
    const incomeMatches = matchedAllocationIndexes.income;
    const snowballMatches = matchedAllocationIndexes.snowball;
    const incomeByDay: Record<number, number> = {};
    incomes.forEach((i) => {
      const occ = getIncomeOccurrenceDays(i, month, year);
      const amt = getEffectiveIncomeAmount(i, month, year);
      occ.forEach((d) => {
        const date = `${year}-${String(month + 1).padStart(2, "0")}-${String(d).padStart(2, "0")}`;
        const match = incomeMatches.get(occurrenceKey(i.id, date));
        const scheduledAmount = remainingPlannedAmount(amt, match);
        if (scheduledAmount <= 0.005) return;
        incomeByDay[d] = (incomeByDay[d] ?? 0) + scheduledAmount;
        financialEvents.push({
          id: `income:${i.id}:${year}-${month + 1}-${d}`,
          sourceType: "income",
          sourceId: i.id,
          date,
          kind: "scheduled_income",
          amount: scheduledAmount,
          status: "scheduled",
          name: i.name,
          configuredOccurrenceAmount: amt,
          settledOccurrenceAmount: Math.abs(Number(match?.amount) || 0),
        });
      });
    });
    const monthTxs =
      forecastTransactionsByMonth.get(
        `${year}-${String(month + 1).padStart(2, "0")}`,
      ) ?? [];
    monthTxs.forEach((t) => {
      const isBankActivity =
        t.source === "plaid" ||
        t.source === "statement" ||
        Boolean(t.import_hash);
      financialEvents.push({
        id: `transaction:${t.id}`,
        sourceType: "transaction",
        sourceId: t.id,
        date: t.date,
        kind: t.amount >= 0 ? "transaction_income" : "transaction_expense",
        amount: t.amount,
        status:
          !isBankActivity && t.amount > 0 && t.date >= projectionAsOfDate
            ? "scheduled"
            : "actual",
        name: t.note || t.category,
      });
    });
    const billsByDay: Record<number, number> = {};
    const debtPlan = requestedDebtPlan;
    bills
      .filter(
        (b) =>
          (b.is_recurring || b.is_debt) && isBillEligibleForUpcomingPlan(b),
      )
      .forEach((b) => {
        let occ = getBillOccurrencesInMonth(b, month, year);
        if (occ.length === 0) return;
        const o = overrides.find(
          (o) => o.bill_id === b.id && o.month === month && o.year === year,
        );
        const hasReviewedOccurrence =
          matchedAllocationIndexes.reviewedBillIdsByMonth
            .get(`${year}-${String(month + 1).padStart(2, "0")}`)
            ?.has(b.id) ?? false;
        if (b.is_debt && debtPlan) return;
        const total = hasReviewedOccurrence
          ? getBillMonthlyTotal(b, month, year)
          : getBillEffectiveMonthlyTotal(b, month, year);
        if (total <= 0.005) return;
        if (o?.actual_amount !== undefined && !hasReviewedOccurrence) {
          const finalizedOccurrences = resolveFinalizedBillOccurrenceDays(
            occ,
            o.paid_date,
            month,
            year,
          );
          const finalizedAmount =
            finalizedOccurrences.length > 0
              ? total / finalizedOccurrences.length
              : 0;
          finalizedOccurrences.forEach((d) => {
            const date = `${year}-${String(month + 1).padStart(2, "0")}-${String(d).padStart(2, "0")}`;
            const match = billMatches.get(occurrenceKey(b.id, date));
            const remaining = remainingPlannedAmount(finalizedAmount, match);
            if (remaining <= 0.005) return;
            billsByDay[d] = (billsByDay[d] ?? 0) + remaining;
            financialEvents.push({
              id: `bill:${b.id}:${year}-${month + 1}-${d}`,
              sourceType: "bill",
              sourceId: b.id,
              date,
              kind: "bill",
              amount: -remaining,
              status: match ? "planned" : "finalized",
              name: b.name,
              configuredOccurrenceAmount: finalizedAmount,
              settledOccurrenceAmount: Math.abs(Number(match?.amount) || 0),
              ...(b.is_debt ? { debtTargetBillId: b.id } : {}),
            });
          });
          return;
        }
        occ.forEach((d) => {
          const date = `${year}-${String(month + 1).padStart(2, "0")}-${String(d).padStart(2, "0")}`;
          const match = billMatches.get(occurrenceKey(b.id, date));
          const payment = resolveBillOccurrencePayment({
            occurrenceDate: date,
            scheduledAmount: getBillOccurrenceAmount(b, date),
            frequency: b.frequency,
            match,
            monthlyPaidAmount: o?.paid_amount,
            monthlyPaidDate: o?.paid_date,
          });
          const remaining = payment.remainingAmount;
          if (remaining <= 0.005) return;
          billsByDay[d] = (billsByDay[d] ?? 0) + remaining;
          financialEvents.push({
            id: `bill:${b.id}:${year}-${month + 1}-${d}`,
            sourceType: "bill",
            sourceId: b.id,
            date,
            kind: "bill",
            amount: -remaining,
            status: "planned",
            name: b.name,
            configuredOccurrenceAmount: getBillOccurrenceAmount(b, date),
            settledOccurrenceAmount: payment.paidAmount,
            ...(b.is_debt ? { debtTargetBillId: b.id } : {}),
          });
        });
      });
    const debtExtrasByDay: Record<number, number> = {};
    if (debtPlan) {
      const savedExtra = getExtraPayment(month, year);
      debtPlan.allocations.forEach((allocation) => {
        const day = Number(allocation.date.split("-")[2]);
        if (
          !Number.isFinite(day) ||
          day < 1 ||
          day > daysInMonth ||
          allocation.amount <= 0.005
        )
          return;
        debtExtrasByDay[day] = (debtExtrasByDay[day] ?? 0) + allocation.amount;
        const canonicalSourceId =
          allocation.sourceBillId ?? allocation.targetBillId;
        const sourceCommitment =
          allocation.kind === "extra"
            ? undefined
            : getDebtSourceCommitment(canonicalSourceId, allocation.date);
        financialEvents.push({
          id: allocation.id,
          sourceType: "extra_payment",
          sourceId:
            allocation.kind === "extra"
              ? (savedExtra?.id ?? allocation.targetBillId)
              : canonicalSourceId,
          date: allocation.date,
          kind: "debt_payment",
          amount: -allocation.amount,
          status:
            sourceCommitment?.state === "pending"
              ? "pending"
              : allocation.date > projectionAsOfDate
                ? "scheduled"
                : "planned",
          name: `${allocation.targetBillName} debt payment`,
          debtPlanSource:
            allocation.kind === "extra" ? "saved_extra" : "canonical",
          debtPlanAllocationKind: allocation.kind,
          debtTargetBillId: allocation.targetBillId,
        });
      });
    } else
      extraPayments
        .filter((ep) => ep.month === month && ep.year === year)
        .forEach((ep) => {
          const paymentDate =
            ep.payment_date ??
            `${year}-${String(month + 1).padStart(2, "0")}-01`;
          const day = Number(paymentDate.split("-")[2]);
          if (!Number.isFinite(day) || day < 1 || day > daysInMonth) return;
          const pending =
            hasPendingSnowballBalanceApply(ep) ||
            paymentDate > projectionAsOfDate;
          const remainingAllocations = ep.allocations
            .map((allocation) => ({
              ...allocation,
              remaining: remainingSnowballAllocationAmount(
                allocation.payment,
                snowballMatches.get(
                  occurrenceKey(allocation.billId, paymentDate),
                ),
              ),
            }))
            .filter((allocation) => allocation.remaining > 0.005);
          const remainingAmount = remainingAllocations.reduce(
            (sum, allocation) => sum + allocation.remaining,
            0,
          );
          if (remainingAmount <= 0.005) return;
          const targetNames = Array.from(
            new Set(
              remainingAllocations
                .map(
                  (allocation) =>
                    allocation.billName ||
                    bills.find((bill) => bill.id === allocation.billId)?.name,
                )
                .filter(Boolean),
            ),
          ).join(", ");
          debtExtrasByDay[day] = (debtExtrasByDay[day] ?? 0) + remainingAmount;
          financialEvents.push({
            id: `extra:${ep.id}:${year}-${month + 1}-${day}`,
            sourceType: "extra_payment",
            sourceId: ep.id,
            date: paymentDate,
            kind: "debt_payment",
            amount: -remainingAmount,
            status: pending ? "scheduled" : "applied",
            name: targetNames
              ? `${targetNames} debt payment`
              : "Snowball debt payment",
          });
        });
    const goalsByDay: Record<number, GoalExpense[]> = {};
    goals.forEach((g) => {
      if (g.goal_type !== "planned_expense" || g.archived_at) return;
      if (!g.target_date) return;
      const targetDate = parseGoalTargetDate(g.target_date);
      if (!targetDate || targetDate.year !== year || targetDate.month !== month)
        return;
      const day = targetDate.day;
      if (!goalsByDay[day]) goalsByDay[day] = [];
      const remaining = getGoalRemainingAmount(g);
      if (remaining > 0) {
        goalsByDay[day].push({ id: g.id, name: g.name, amount: remaining });
        financialEvents.push({
          id: `goal:${g.id}:${year}-${month + 1}-${day}`,
          sourceType: "goal",
          sourceId: g.id,
          date: `${year}-${String(month + 1).padStart(2, "0")}-${String(day).padStart(2, "0")}`,
          kind: "goal",
          amount: -remaining,
          status: "planned",
          name: g.name,
        });
      }
    });
    const plannedDecisionByDay: Record<number, number> = {};
    const rangeEnd = `${year}-${String(month + 1).padStart(2, "0")}-${String(daysInMonth).padStart(2, "0")}`;
    decisions
      .filter((d) => d.status === "planned" || d.status === "calendar")
      .forEach((decision) => {
        scenarioDates(decision.scenario, rangeEnd)
          .filter((date) =>
            date.startsWith(`${year}-${String(month + 1).padStart(2, "0")}`),
          )
          .forEach((date) => {
            const day = Number(date.slice(8, 10));
            const signed =
              decision.scenario.type === "income_change"
                ? decision.scenario.amount
                : -Math.abs(decision.scenario.amount);
            plannedDecisionByDay[day] =
              (plannedDecisionByDay[day] ?? 0) + signed;
            financialEvents.push({
              id: `decision:${decision.id}:${date}`,
              sourceType: "decision",
              sourceId: decision.id,
              date,
              kind: signed >= 0 ? "scheduled_income" : "transaction_expense",
              amount: signed,
              status: "planned",
              name: decision.name,
            });
          });
      });
    const currentMonthPrefix = `${year}-${String(month + 1).padStart(2, "0")}`;
    let openingBalance = carryover;
    // Keep original dates for calendar/history while unresolved obligations
    // reserve cash on the bank observation date in the balance projection.
    const displayEvents = suppressDebtBillPlanDuplicates(financialEvents);
    let balanceEvents = [...displayEvents];
    if (bankAnchor?.date.startsWith(currentMonthPrefix)) {
      // The bank balance still contains money reserved in older open buckets.
      // Restore that commitment once in the observed month without inventing
      // a second calendar occurrence or changing the original target date.
      goals.forEach((goal) => {
        if (goal.goal_type !== "planned_expense" || goal.archived_at || !goal.target_date) return;
        const target = parseGoalTargetDate(goal.target_date);
        if (!target) return;
        const targetDate = `${target.year}-${String(target.month + 1).padStart(2, "0")}-${String(target.day).padStart(2, "0")}`;
        const remaining = getGoalRemainingAmount(goal);
        if (targetDate >= `${currentMonthPrefix}-01` || remaining <= 0) return;
        balanceEvents.push({
          id: `goal:${goal.id}:${target.year}-${target.month + 1}-${target.day}`,
          sourceType: "goal",
          sourceId: goal.id,
          date: targetDate,
          kind: "goal",
          amount: -remaining,
          status: "planned",
          name: goal.name,
        });
      });
    }
    if (connectedBankAnchor?.date.startsWith(currentMonthPrefix)) {
      const settledTransactionEventIds = new Set(
        monthTxs
          .filter(
            (transaction) =>
              transaction.source === "plaid" ||
              transaction.source === "statement" ||
              Boolean(transaction.import_hash),
          )
          .map((transaction) => `transaction:${transaction.id}`),
      );
      const anchored = anchorForecastToBankBalance(
        balanceEvents,
        connectedBankAnchor.balance,
        connectedBankAnchor.date,
        settledTransactionEventIds,
        historicalMonthOpeningBalance(
          openingBalance,
          settings.starting_balance_date,
          `${currentMonthPrefix}-01`,
        ),
      );
      openingBalance = anchored.openingBalance;
      balanceEvents = anchored.events;
    } else if (bankAnchor?.date.startsWith(currentMonthPrefix)) {
      const anchored = anchorForecastToBankBalance(
        balanceEvents,
        bankAnchor.balance,
        bankAnchor.date,
        new Set(balanceEvents.filter(event => event.status === "actual" || event.status === "finalized" || event.status === "applied").map(event => event.id)),
        historicalMonthOpeningBalance(openingBalance, settings.starting_balance_date, `${currentMonthPrefix}-01`),
      );
      openingBalance = anchored.openingBalance;
      balanceEvents = anchored.events;
    }
    const forecast = forecastBalances({
      openingBalance,
      startDate: `${year}-${String(month + 1).padStart(2, "0")}-01`,
      endDate: `${year}-${String(month + 1).padStart(2, "0")}-${String(daysInMonth).padStart(2, "0")}`,
      events: balanceEvents,
    });

    const visibleEventsByDate = new Map<string, FinancialEvent[]>();
    displayEvents.forEach((event) => {
      if (
        event.sourceType === "transaction" &&
        !visibleTransactionIds.has(event.sourceId)
      )
        return;
      const bucket = visibleEventsByDate.get(event.date);
      if (bucket) bucket.push(event);
      else visibleEventsByDate.set(event.date, [event]);
    });
    const result: DailyBalance[] = [];
    for (let day = 1; day <= daysInMonth; day++) {
      const dayDate = `${year}-${String(month + 1).padStart(2, "0")}-${String(day).padStart(2, "0")}`;
      const dayTxs = visibleCheckingTransactionsByDate.get(dayDate) ?? [];
      const scheduledIncome = incomeByDay[day] ?? 0;
      const txIncome = dayTxs
        .filter((t) => t.amount > 0)
        .reduce((s, t) => s + t.amount, 0);
      const incomeToday = scheduledIncome + txIncome;
      const decisionNet = plannedDecisionByDay[day] ?? 0;
      const expenseToday =
        dayTxs
          .filter((t) => t.amount < 0)
          .reduce((s, t) => s + Math.abs(t.amount), 0) +
        (debtExtrasByDay[day] ?? 0) +
        Math.max(0, -decisionNet);
      const billsToday = billsByDay[day] ?? 0;
      const dayGoals = goalsByDay[day] ?? [];
      const forecastDay = forecast.days[day - 1];
      const visibleEvents = visibleEventsByDate.get(forecastDay.date) ?? [];
      const projectedInflow = forecastDay.events.reduce(
        (sum, event) => sum + Math.max(0, event.amount),
        0,
      );
      const projectedOutflow = forecastDay.events.reduce(
        (sum, event) => sum + Math.max(0, -event.amount),
        0,
      );
      result.push({
        day,
        income: incomeToday,
        scheduledIncome,
        expense: expenseToday,
        bills: billsToday,
        goalExpenses: dayGoals,
        net: forecastDay.net,
        balance: forecastDay.balance,
        balanceSource: "projected",
        balanceDate: forecastDay.date,
        projectedInflow,
        projectedOutflow,
        events: visibleEvents,
        projectionEvents: forecastDay.events.map((event) => ({ ...event })),
      });
    }
    return result;
  };

  const getDailyBalances = (month: number, year: number): DailyBalance[] =>
    getOrComputeRevisionValue(
      balanceComputationCache.daily,
      financialProjectionMonthCacheKey(
        safeLocalDateInTimeZone(now, householdTimeZone),
        month,
        year,
      ),
      () => buildDailyBalances(month, year),
    );
  return {
    getOverride,
    getAmount,
    getPaidAmount,
    getCustomDueDay,
    getBillOccurrencesInMonth,
    getBillOccurrenceAmount,
    getBillMonthlyTotal,
    getBillEffectiveMonthlyTotal,
    getMonthlyBills,
    getDebtMonthSettlements,
    getDebtSourceCommitment,
    getExtraPayment,
    getDebtPlanForMonth,
    getRemainingDebtPlanForMonth,
    getMonthlyIncome,
    getIncomeOccurrencesInMonth,
    getCashFlow,
    getDailyBalances,
    transactionLedger,
    matchedAllocationIndexes,
    debtSourceCommitments,
  };
}
export type FinancialProjection = ReturnType<typeof createFinancialProjection>;

export type DebtPaymentPlanSummary = {
  extraPayment: number;
  requiredMinimum: number;
  totalPlanned: number;
};

export type DebtPaymentProgress = {
  requiredAmount: number;
  plannedAmount: number;
  paidAmount: number;
  requiredRemaining: number;
  optionalExtraRemaining: number;
  isPaid: boolean;
  isPartial: boolean;
};

export type RetainedDebtPaymentBreakdown = {
  alreadyPaid: number;
  minimumRequired: number;
  minimumRemaining: number;
  scheduledPayment: number;
  extraPrincipal: number;
};

export type SnowballPaymentTransactionLike = {
  amount: number;
  date?: string | null;
  category?: string | null;
  note?: string | null;
  source?: string | null;
  review_resolution?: string | null;
  import_hash?: string | null;
  linked_bill_id?: string | null;
  debt_applied_bill_id?: string | null;
  debt_applied_amount?: number | null;
};

export type DatedSnowballPlanLike = {
  amount: number;
  date?: string | null;
};

export type SnowballTransactionEditDraft = {
  amount: number;
  debtId: string;
  paymentDate: string;
};

export type RequiredDebtPaymentLike = {
  amount: number;
  snowball_minimum_boost?: number | null;
};

export type SnowballRolloverPaymentLike = {
  snowball_minimum_boost?: number | null;
  include_in_snowball?: boolean | null;
};

function money(value: number) {
  return Math.round(Math.max(0, Number(value) || 0) * 100) / 100;
}

export const SNOWBALL_PLAN_SOURCE = "snowball_plan";

export function buildDebtPaymentPlanSummary(requiredMinimum: number, extraPayment: number): DebtPaymentPlanSummary {
  const minimum = money(requiredMinimum);
  const extra = money(extraPayment);
  return {
    extraPayment: extra,
    requiredMinimum: minimum,
    totalPlanned: money(minimum + extra),
  };
}

/** Status follows the lender minimum while optional payoff money stays visible. */
export function debtPaymentProgress(
  requiredAmount: number,
  plannedAmount: number,
  paidAmount: number,
): DebtPaymentProgress {
  const required = money(requiredAmount);
  const planned = money(plannedAmount);
  const paid = money(paidAmount);
  const requiredRemaining = money(required - paid);
  const optionalExtraRemaining = money(planned - Math.max(required, paid));
  const isPaid = required > 0.005 && requiredRemaining <= 0.005;
  return {
    requiredAmount: required,
    plannedAmount: planned,
    paidAmount: paid,
    requiredRemaining,
    optionalExtraRemaining,
    isPaid,
    isPartial: paid > 0.005 && !isPaid,
  };
}

/** Explains a choice to keep the original payment after an earlier payment. */
export function retainedDebtPaymentBreakdown(
  scheduledPayment: number,
  minimumRequired: number,
  alreadyPaid: number,
): RetainedDebtPaymentBreakdown | null {
  const scheduled = money(scheduledPayment);
  const minimum = money(minimumRequired);
  const paid = money(alreadyPaid);
  const minimumRemaining = money(minimum - paid);
  const extraPrincipal = money(scheduled - minimumRemaining);
  if (scheduled <= 0.005 || minimum <= 0.005 || paid <= 0.005 || extraPrincipal <= 0.005) return null;
  return {
    alreadyPaid: paid,
    minimumRequired: minimum,
    minimumRemaining,
    scheduledPayment: scheduled,
    extraPrincipal,
  };
}

export function isScheduledSnowballPlanTransaction(transaction: SnowballPaymentTransactionLike): boolean {
  return transaction.source === SNOWBALL_PLAN_SOURCE;
}

export function isSnowballPaymentTransaction(transaction: SnowballPaymentTransactionLike): boolean {
  if (transaction.review_resolution === "snowball" && Number(transaction.amount) < 0) return true;
  const linkedDebtId = transaction.debt_applied_bill_id ?? transaction.linked_bill_id;
  if (!linkedDebtId || Number(transaction.amount) >= 0) return false;

  const isGeneratedDebtSurplus = String(transaction.import_hash ?? "").startsWith("flowledger:debt-surplus:");
  const isNamedSnowballPayment = String(transaction.category ?? "").toLowerCase() === "debt"
    && /\bsnowball\b/i.test(String(transaction.note ?? ""));

  return isScheduledSnowballPlanTransaction(transaction) || isGeneratedDebtSurplus || isNamedSnowballPayment;
}

export function snowballPlanTotalThroughDate(
  plans: DatedSnowballPlanLike[],
  throughDate: string,
): number {
  const monthPrefix = /^\d{4}-\d{2}-\d{2}$/.test(throughDate) ? throughDate.slice(0, 7) : "";
  if (!monthPrefix) return 0;
  return money(plans.reduce((total, plan) => {
    const date = String(plan.date ?? "");
    if (!date.startsWith(`${monthPrefix}-`) || date > throughDate) return total;
    return total + Math.abs(Number(plan.amount) || 0);
  }, 0));
}

export function snowballPaymentName(transaction: SnowballPaymentTransactionLike, fallback = "Debt payment"): string {
  const name = String(transaction.note ?? "").replace(/\s+snowball(?:\s+payment)?$/i, "").trim();
  return name || fallback;
}

export function snowballTransactionEditDraft(
  transaction: SnowballPaymentTransactionLike,
): SnowballTransactionEditDraft | null {
  const debtId = transaction.debt_applied_bill_id ?? transaction.linked_bill_id;
  const paymentDate = String(transaction.date ?? "");
  if (!isSnowballPaymentTransaction(transaction) || !debtId || !/^\d{4}-\d{2}-\d{2}$/.test(paymentDate)) return null;
  return {
    amount: money(Math.abs(Number(transaction.amount))),
    debtId,
    paymentDate,
  };
}

export function replacementSnowballSafeMaximum(safeMaximum: number, existingAmount: number): number {
  return money(safeMaximum + existingAmount);
}

export function requiredDebtPlanTotal(
  debt: RequiredDebtPaymentLike,
  occurrenceCount = 1,
): number {
  const requiredPerOccurrence = Math.max(0, Number(debt.amount) || 0);
  return money(requiredPerOccurrence * Math.max(0, occurrenceCount));
}

/** Existing freed minimums form one monthly extra pool, never one per occurrence. */
export function snowballRolloverPlanTotal(
  debts: readonly SnowballRolloverPaymentLike[],
): number {
  return money(debts.reduce((total, debt) => (
    debt.include_in_snowball === false
      ? total
      : total + Math.max(0, Number(debt.snowball_minimum_boost) || 0)
  ), 0));
}

export function upsertSnowballPlanById<T extends { id: string }>(plans: T[], nextPlan: T): T[] {
  const existingIndex = plans.findIndex(plan => plan.id === nextPlan.id);
  if (existingIndex < 0) return [...plans, nextPlan];
  return plans.map(plan => plan.id === nextPlan.id ? nextPlan : plan);
}

export type DebtMonthSettlementStatus = "scheduled" | "partial" | "settled";

export type DebtOccurrenceSettlement = {
  occurrenceDate: string;
  configuredObligation: number;
  paidAmount: number;
  remainingRequired: number;
  status: DebtMonthSettlementStatus;
};

export type DebtMonthSettlement = {
  configuredObligation: number;
  paidAmount: number;
  remainingRequired: number;
  status: DebtMonthSettlementStatus;
  plannedDebtAmount?: number;
  /** Exact due-date truth used by overdue, Forecast, Flo, and Flow Score. */
  occurrences?: DebtOccurrenceSettlement[];
};

type ReviewedSettlement = {
  status: "partial" | "settled";
  actualAmount: number;
  /** Historical obligation captured by the reviewed occurrence. */
  requiredAmount?: number;
  occurrenceCount?: number;
};
type OverrideSettlement = { paid_amount: number; actual_amount?: number; paid_date?: string };

const cents = (value: number) => Math.round(Math.max(0, Number(value) || 0) * 100) / 100;

export function resolveDebtOccurrenceSettlement(input: {
  occurrenceDate: string;
  configuredObligation: number;
  reviewed?: Pick<ReviewedSettlement, "status" | "actualAmount" | "requiredAmount">;
  paidAmount?: number;
  requiredAmountSnapshot?: number;
}): DebtOccurrenceSettlement {
  const reviewedRequired = Number(input.reviewed?.requiredAmount);
  const snapshotRequired = Number(input.requiredAmountSnapshot);
  const configuredObligation = cents(
    Number.isFinite(reviewedRequired) && reviewedRequired >= 0
      ? reviewedRequired
      : Number.isFinite(snapshotRequired) && snapshotRequired >= 0
        ? snapshotRequired
        : input.configuredObligation,
  );
  const paidAmount = input.reviewed
    ? cents(input.reviewed.actualAmount)
    : cents(input.paidAmount ?? 0);
  const hasHistoricalRequirement = Boolean(input.reviewed)
    || (Number.isFinite(snapshotRequired) && snapshotRequired >= 0);
  const status: DebtMonthSettlementStatus = configuredObligation <= 0.005 && hasHistoricalRequirement
    ? "settled"
    : configuredObligation > 0.005 && paidAmount + 0.005 >= configuredObligation
      ? "settled"
      : paidAmount > 0.005
        ? "partial"
        : "scheduled";
  return {
    occurrenceDate: input.occurrenceDate,
    configuredObligation,
    paidAmount,
    remainingRequired: status === "settled" ? 0 : cents(configuredObligation - paidAmount),
    status,
  };
}

export function summarizeDebtOccurrenceSettlements(
  occurrences: readonly DebtOccurrenceSettlement[],
  plannedDebtAmount?: number,
): DebtMonthSettlement {
  const configuredObligation = cents(occurrences.reduce(
    (sum, occurrence) => sum + occurrence.configuredObligation,
    0,
  ));
  const paidAmount = cents(occurrences.reduce(
    (sum, occurrence) => sum + occurrence.paidAmount,
    0,
  ));
  const remainingRequired = cents(occurrences.reduce(
    (sum, occurrence) => sum + occurrence.remainingRequired,
    0,
  ));
  const status: DebtMonthSettlementStatus = occurrences.length > 0
    && occurrences.every(occurrence => occurrence.status === "settled")
    ? "settled"
    : paidAmount > 0.005
      ? "partial"
      : "scheduled";
  return {
    configuredObligation,
    paidAmount,
    remainingRequired,
    status,
    occurrences: [...occurrences],
    ...(plannedDebtAmount !== undefined ? { plannedDebtAmount: cents(plannedDebtAmount) } : {}),
  };
}

/** Month aggregates may include a completed moved payment and the next cycle. */
export function debtOccurrenceProgress(settlement: DebtMonthSettlement): {
  label: string; completedCount: number; nextDate?: string; hasPartial: boolean;
} {
  const occurrences = settlement.occurrences ?? [];
  const completedCount = occurrences.filter(item => item.status === "settled").length;
  const nextDate = occurrences.filter(item => item.remainingRequired > 0.005)
    .map(item => item.occurrenceDate).sort()[0];
  const hasPartial = occurrences.some(item => item.status === "partial");
  const label = completedCount > 0 && nextDate
    ? `${completedCount} payment${completedCount === 1 ? "" : "s"} complete · next due ${new Date(`${nextDate}T12:00:00`).toLocaleDateString("en-US", { month: "short", day: "numeric" })}`
    : settlement.status === "settled" ? "Paid this month"
      : hasPartial || (occurrences.length === 0 && settlement.status === "partial")
        ? "Partially paid" : "Scheduled";
  return { label, completedCount, nextDate, hasPartial };
}

export function effectiveDebtOccurrenceAmount(
  baseMinimum: number,
  snowballMinimumBoost: number,
  plannedDebtAmount?: number,
): number {
  return plannedDebtAmount !== undefined
    ? cents(plannedDebtAmount)
    : cents(Math.max(0, baseMinimum) + Math.max(0, snowballMinimumBoost));
}

export function configuredDebtMonthObligation(input: {
  baseMinimum: number;
  snowballMinimumBoost: number;
  occurrenceCount: number;
  plannedDebtAmount?: number;
}): number {
  // A forecast edit or snowball boost can change the planned cash outflow,
  // but neither changes what the lender required. Settlement and overdue
  // status therefore stay anchored to the saved original minimum.
  return cents(Math.max(0, input.baseMinimum) * Math.max(0, input.occurrenceCount));
}

/**
 * Returns the amount that should drive an overdue alert for one debt
 * occurrence. Planned snowball extras are optional and must not keep an
 * alert open after the lender minimum is paid. Historical zero/lower
 * requirements remain respected when they are explicitly recorded.
 */
export function lenderMinimumRequiredAmount(
  configuredAmount: number | undefined,
  lenderMinimum: number,
): number {
  const minimum = cents(lenderMinimum);
  const configured = Number(configuredAmount);
  return Number.isFinite(configured) && configured >= 0
    ? cents(Math.min(minimum, configured))
    : minimum;
}

/**
 * Splits one exact Forecast commitment without redefining the lender minimum.
 * An omitted override schedules the required amount; an explicit zero skips
 * the cash outflow while the full requirement remains available to status
 * and overdue calculations.
 */
export function debtPlanPaymentBreakdown(
  requiredAmount: number,
  exactPlannedAmount?: number,
): {
  requiredAmount: number;
  requiredPayment: number;
  plannedExtraPayment: number;
  plannedPayment: number;
} {
  const required = cents(requiredAmount);
  const planned = exactPlannedAmount === undefined ? required : cents(exactPlannedAmount);
  const requiredPayment = cents(Math.min(required, planned));
  return {
    requiredAmount: required,
    requiredPayment,
    plannedExtraPayment: cents(planned - requiredPayment),
    plannedPayment: planned,
  };
}

export function exactDebtPlanTotal(input: {
  plannedDebtAmount?: number;
  customAmount?: number;
  occurrenceCount: number;
}): number | undefined {
  const exactPerOccurrence = input.plannedDebtAmount !== undefined
    ? input.plannedDebtAmount
    : input.customAmount !== undefined
      && Number.isFinite(input.customAmount)
      && input.customAmount > 0.005
      ? input.customAmount
      : undefined;
  return exactPerOccurrence === undefined
    ? undefined
    : cents(Math.max(0, exactPerOccurrence) * Math.max(0, input.occurrenceCount));
}

/** An exact edit on the active target replaces, rather than stacks with, rollover. */
export function automaticDebtRolloverForMonth(
  rolloverAmount: number,
  automaticTargetId: string | undefined,
  exactPlanDebtIds: ReadonlySet<string>,
  targetPaidAboveRequired = 0,
): number {
  return automaticTargetId && exactPlanDebtIds.has(automaticTargetId)
    ? 0
    : cents(Math.max(0, rolloverAmount - Math.max(0, targetPaidAboveRequired)));
}

export function plannedDebtAmountError(amount: number, pendingAmount = 0): string | undefined {
  if (!Number.isFinite(amount) || amount < 0) return "Enter an amount of zero or more.";
  if (cents(amount) + 0.005 < cents(pendingAmount)) {
    return `A ${cents(pendingAmount).toFixed(2)} payment is already pending. The planned amount cannot be lower until it posts or disappears.`;
  }
  return undefined;
}

/** Converts an edited remaining payment back to the configured occurrence total. */
export function configuredDebtAmountForRemainingPayment(
  remainingPayment: number,
  settledPayment: number,
): number {
  return cents(Math.max(0, remainingPayment) + Math.max(0, settledPayment));
}

export function parsePlannedDebtAmount(value: string): number | undefined {
  const normalized = value.trim();
  if (!/^(?:\d+|\d+\.\d{1,2}|\.\d{1,2})$/.test(normalized)) return undefined;
  const amount = Number(normalized);
  return Number.isFinite(amount) ? cents(amount) : undefined;
}

export function parsePlannedDebtOccurrenceDate(value?: string): { year: number; month: number; day: number } | undefined {
  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(value ?? "");
  if (!match) return undefined;
  const year = Number(match[1]);
  const monthNumber = Number(match[2]);
  const day = Number(match[3]);
  const parsed = new Date(year, monthNumber - 1, day, 12);
  if (parsed.getFullYear() !== year || parsed.getMonth() !== monthNumber - 1 || parsed.getDate() !== day) return undefined;
  return { year, month: monthNumber - 1, day };
}

export function isPlannedDebtOccurrenceDate(value: string | undefined, occurrenceDays: readonly number[]): boolean {
  const parsed = parsePlannedDebtOccurrenceDate(value);
  return Boolean(parsed && occurrenceDays.includes(parsed.day));
}

export type DebtSourceCommitment = {
  sourceBillId: string;
  sourceBillName?: string;
  sourceBalance?: number;
  date: string;
  amount: number;
  state: "pending" | "posted";
};

/**
 * Pending/posted-review commitments are unreconciled payments in addition to
 * reviewed payments already applied this month. A bank item leaves the live
 * commitment set when review makes it part of `reviewedPaidAmount`, so the two
 * states cannot represent the same item at once.
 */
export function authoritativeDebtPaidAmountForMonth(
  reviewedPaidAmount: number,
  commitments: readonly DebtSourceCommitment[],
  sourceBillId: string,
  monthPrefix: string,
): number {
  const liveCommitments = commitments.filter(commitment => (
    commitment.sourceBillId === sourceBillId && commitment.date.startsWith(monthPrefix)
  ));
  return cents(reviewedPaidAmount + liveCommitments.reduce(
    (sum, commitment) => sum + commitment.amount,
    0,
  ));
}

/** Replaces each canonical source/date group with its authoritative bank commitment. */
export function applyDebtSourceCommitments(
  allocations: readonly DatedDebtAllocation[],
  commitments: readonly DebtSourceCommitment[],
): DatedDebtAllocation[] {
  const commitmentByKey = new Map(commitments.map(commitment => [
    `${commitment.sourceBillId}:${commitment.date}`,
    commitment,
  ]));
  const emittedKeys = new Set<string>();

  const pendingReplacement = (
    commitment: DebtSourceCommitment,
    group: readonly DatedDebtAllocation[],
    fallback: DatedDebtAllocation,
  ): DatedDebtAllocation[] => {
    const commitmentAmount = cents(commitment.amount);
    if (commitmentAmount <= 0.005) return [];
    const sourceName = commitment.sourceBillName ?? fallback.sourceBillName ?? fallback.targetBillName;
    const orderedTemplates = [
      ...group.filter(candidate => candidate.kind === "required"),
      ...group.filter(candidate => candidate.kind === "rollover"),
    ];
    const runningBalances = new Map<string, number>();
    const replacement: DatedDebtAllocation[] = [];
    let remaining = commitmentAmount;

    const append = (
      template: DatedDebtAllocation,
      amount: number,
      kind: "required" | "rollover",
    ) => {
      const payment = cents(amount);
      if (payment <= 0.005) return;
      const balanceBefore = runningBalances.get(template.targetBillId)
        ?? cents(template.balanceBefore ?? (template.targetBillId === commitment.sourceBillId ? commitment.sourceBalance : 0) ?? 0);
      const balanceAfter = cents(balanceBefore - payment);
      runningBalances.set(template.targetBillId, balanceAfter);
      replacement.push({
        ...template,
        id: `pending-debt:${commitment.sourceBillId}:${commitment.date}:${kind}:${replacement.length}`,
        sourceBillId: commitment.sourceBillId,
        sourceBillName: sourceName,
        kind,
        amount: payment,
        sourceAmount: commitmentAmount,
        balanceBefore,
        balanceAfter,
        paidOff: balanceAfter <= 0.005,
      });
    };

    orderedTemplates.forEach(template => {
      if (remaining <= 0.005) return;
      const applied = cents(Math.min(remaining, template.amount));
      append(template, applied, template.kind === "required" ? "required" : "rollover");
      remaining = cents(remaining - applied);
    });

    if (remaining > 0.005) {
      const lastRollover = [...orderedTemplates].reverse().find(template => template.kind === "rollover");
      const extraTemplate = lastRollover ?? group.find(template => template.targetBillId === commitment.sourceBillId) ?? fallback;
      append(extraTemplate, remaining, "rollover");
    }
    return replacement;
  };

  const result = allocations.flatMap(allocation => {
    if (allocation.kind === "extra" || !allocation.sourceBillId) return [{ ...allocation }];
    const key = `${allocation.sourceBillId}:${allocation.date}`;
    const commitment = commitmentByKey.get(key);
    if (!commitment) return [{ ...allocation }];
    if (emittedKeys.has(key)) return [];
    emittedKeys.add(key);
    if (commitment.state === "posted" || commitment.amount <= 0.005) return [];
    const group = allocations.filter(candidate => candidate.kind !== "extra"
      && candidate.sourceBillId === commitment.sourceBillId
      && candidate.date === commitment.date);
    const sourceTemplate = group.find(candidate => candidate.targetBillId === commitment.sourceBillId) ?? allocation;
    return pendingReplacement(commitment, group, sourceTemplate);
  });

  commitments.forEach(commitment => {
    const key = `${commitment.sourceBillId}:${commitment.date}`;
    if (emittedKeys.has(key) || commitment.state === "posted" || commitment.amount <= 0.005 || commitment.sourceBalance === undefined) return;
    const balanceBefore = cents(commitment.sourceBalance);
    const balanceAfter = cents(balanceBefore - commitment.amount);
    result.push({
      id: `pending-debt:${commitment.sourceBillId}:${commitment.date}`,
      date: commitment.date,
      sourceBillId: commitment.sourceBillId,
      sourceBillName: commitment.sourceBillName ?? "Debt payment",
      targetBillId: commitment.sourceBillId,
      targetBillName: commitment.sourceBillName ?? "Debt payment",
      // No canonical required row remains, so this live amount is payoff extra
      // rather than a new lender requirement.
      kind: "rollover",
      amount: cents(commitment.amount),
      sourceAmount: cents(commitment.amount),
      balanceBefore,
      balanceAfter,
      paidOff: balanceAfter <= 0.005,
    });
  });
  return result;
}

/** Removes reviewed month-to-date cash before advancing already-reduced balances. */
export function remainingDebtAllocationsAfterReviewedPayments(
  allocations: readonly DatedDebtAllocation[],
  settlements: ReadonlyMap<string, Pick<DebtMonthSettlement, "paidAmount" | "occurrences">>,
): DatedDebtAllocation[] {
  const remainingPaidByOccurrence = new Map<string, number>();
  const remainingPaidByBill = new Map<string, number>();
  settlements.forEach((settlement, billId) => {
    if (settlement.occurrences?.length) {
      settlement.occurrences.forEach(occurrence => {
        remainingPaidByOccurrence.set(
          `${billId}:${occurrence.occurrenceDate}`,
          cents(occurrence.paidAmount),
        );
      });
      return;
    }
    remainingPaidByBill.set(billId, cents(settlement.paidAmount));
  });
  const absorbedByIndex = new Map<number, number>();
  allocations
    .map((allocation, index) => ({ allocation, index }))
    // When the live balance already reflects a payment, canonical rollover is
    // the first duplicated portion. This matches dated remaining-plan math.
    .sort((left, right) => Number(left.allocation.kind !== "rollover") - Number(right.allocation.kind !== "rollover"))
    .forEach(({ allocation, index }) => {
      if (allocation.kind === "extra" || !allocation.sourceBillId) return;
      const occurrenceKey = `${allocation.sourceBillId}:${allocation.date}`;
      const hasOccurrencePayment = remainingPaidByOccurrence.has(occurrenceKey);
      const remainingPaid = hasOccurrencePayment
        ? remainingPaidByOccurrence.get(occurrenceKey) ?? 0
        : remainingPaidByBill.get(allocation.sourceBillId) ?? 0;
      if (remainingPaid <= 0.005) return;
      const absorbed = cents(Math.min(remainingPaid, allocation.amount));
      if (hasOccurrencePayment) {
        remainingPaidByOccurrence.set(occurrenceKey, cents(remainingPaid - absorbed));
      } else {
        remainingPaidByBill.set(allocation.sourceBillId, cents(remainingPaid - absorbed));
      }
      absorbedByIndex.set(index, absorbed);
    });
  return allocations.flatMap((allocation, index) => {
    const remaining = cents(allocation.amount - (absorbedByIndex.get(index) ?? 0));
    return remaining > 0.005 ? [{ ...allocation, amount: remaining }] : [];
  });
}

export function advanceDebtProjectionWithCommitments(
  plan: DatedSnowballMonthPlanResult,
  debts: readonly SnowballDebtInput[],
  openingRolledPayment: number,
  commitments: readonly DebtSourceCommitment[],
  openingAllocations: readonly DatedDebtAllocation[] = plan.allocations,
): { balances: Map<string, number>; rolledPayment: number; allocations: DatedDebtAllocation[] } {
  const allocations = applyDebtSourceCommitments(plan.allocations, commitments);
  const balances = new Map(plan.balances);
  openingAllocations.forEach(allocation => {
    balances.set(allocation.targetBillId, Math.max(
      balances.get(allocation.targetBillId) ?? 0,
      cents(allocation.balanceBefore),
    ));
  });
  const activeAtStart = new Set(debts
    .filter(debt => debt.included && (balances.get(debt.id) ?? 0) > 0.005)
    .map(debt => debt.id));
  const projectedAllocations = allocations.map(allocation => {
    const balanceBefore = cents(balances.get(allocation.targetBillId) ?? 0);
    const balanceAfter = cents(balanceBefore - allocation.amount);
    balances.set(allocation.targetBillId, balanceAfter);
    return { ...allocation, balanceBefore, balanceAfter, paidOff: balanceAfter <= 0.005 };
  });
  const rolledPayment = cents(openingRolledPayment + debts.reduce((sum, debt) => (
    debt.included && activeAtStart.has(debt.id) && (balances.get(debt.id) ?? 0) <= 0.005
      ? sum + Math.max(0, debt.minimum)
      : sum
  ), 0));
  return { balances, rolledPayment, allocations: projectedAllocations };
}

export function resolveDebtMonthSettlement(input: {
  configuredObligation: number;
  occurrenceCount?: number;
  reviewed?: ReviewedSettlement;
  override?: OverrideSettlement;
  plannedDebtAmount?: number;
}): DebtMonthSettlement {
  // A later edit to the recurring minimum applies to future occurrences. It
  // must not retroactively turn a previously reviewed exact payment into a
  // shortage. The review allocation preserves the obligation as it existed
  // when that occurrence was matched.
  const currentConfiguredObligation = cents(input.configuredObligation);
  const reviewedRequired = Number(input.reviewed?.requiredAmount);
  const reviewedOccurrenceCount = Math.max(0, Number(input.reviewed?.occurrenceCount) || 0);
  const configuredOccurrenceCount = Math.max(
    reviewedOccurrenceCount,
    Number(input.occurrenceCount) || reviewedOccurrenceCount,
  );
  const currentRequiredPerOccurrence = configuredOccurrenceCount > 0
    ? currentConfiguredObligation / configuredOccurrenceCount
    : currentConfiguredObligation;
  const unreviewedOccurrenceCount = Math.max(0, configuredOccurrenceCount - reviewedOccurrenceCount);
  const configuredObligation = cents(
    Number.isFinite(reviewedRequired)
      && reviewedRequired > 0.005
      && reviewedOccurrenceCount > 0
      // Preserve reviewed requirements occurrence by occurrence, then use
      // the current lender minimum only for dates that have not been reviewed.
      ? reviewedRequired + currentRequiredPerOccurrence * unreviewedOccurrenceCount
      : currentConfiguredObligation,
  );
  const reviewedPaid = input.reviewed ? cents(input.reviewed.actualAmount) : undefined;
  const overridePaid = input.override
    ? cents(input.override.actual_amount ?? input.override.paid_amount)
    : 0;
  const paidAmount = reviewedPaid ?? overridePaid;
  // Exact/full review choices have already normalized that occurrence's
  // required amount. Compare the accumulated dollars here so a reviewed date
  // cannot settle other weekly/biweekly occurrences that remain unpaid.
  const status: DebtMonthSettlementStatus = configuredObligation > 0.005 && paidAmount + 0.005 >= configuredObligation
    ? "settled"
    : paidAmount > 0.005
      ? "partial"
      : "scheduled";

  return {
    configuredObligation,
    paidAmount,
    remainingRequired: status === "settled" ? 0 : cents(configuredObligation - paidAmount),
    status,
    ...(input.plannedDebtAmount !== undefined ? { plannedDebtAmount: cents(input.plannedDebtAmount) } : {}),
  };
}

export type ExtraPaymentPlanLike = {
  amount: number;
  allocations: readonly { payment: number }[];
};

export function isValidExtraPaymentPlan(plan: ExtraPaymentPlanLike): boolean {
  const amount = cents(plan.amount);
  if (amount <= 0.005) return false;
  const allocationAmounts = plan.allocations.map(allocation => Number(allocation.payment) || 0);
  if (!allocationAmounts.some(payment => payment > 0.005) || allocationAmounts.some(payment => payment < -0.005)) return false;
  const allocationTotal = cents(allocationAmounts.reduce((sum, payment) => sum + payment, 0));
  return Math.abs(allocationTotal - amount) < 0.01;
}
import type { DatedDebtAllocation, DatedSnowballMonthPlanResult, SnowballDebtInput } from "./snowball.ts";

/** Stable cache input for every dated allocation that changes Forecast cash or chips. */
export function datedDebtPlanCacheSignature(plan: DatedSnowballMonthPlanResult | null): string {
  if (!plan) return "none";
  return plan.allocations
    .map(allocation => [
      allocation.id,
      allocation.date,
      allocation.sourceBillId ?? "",
      allocation.targetBillId,
      allocation.kind,
      cents(allocation.amount).toFixed(2),
    ].join(":"))
    .join("|");
}

export type FinancialEventKind =
  | "scheduled_income"
  | "transaction_income"
  | "transaction_expense"
  | "bill"
  | "goal"
  | "debt_payment"
  | "bank_adjustment";

export type FinancialEventStatus = "planned" | "scheduled" | "pending" | "finalized" | "actual" | "applied";

export interface FinancialEvent {
  id: string;
  sourceType: "income" | "transaction" | "bill" | "goal" | "extra_payment" | "decision" | "reconciliation";
  sourceId: string;
  date: string;
  kind: FinancialEventKind;
  /** Signed cash impact: income is positive; spending is negative. */
  amount: number;
  status: FinancialEventStatus;
  name?: string;
  /** Full configured occurrence total and already-settled component for simulator edits. */
  configuredOccurrenceAmount?: number;
  settledOccurrenceAmount?: number;
  debtPlanSource?: "canonical" | "saved_extra";
  debtPlanAllocationKind?: "required" | "rollover" | "extra";
  debtTargetBillId?: string;
}

export interface ForecastSnapshot {
  openingBalance: number;
  startDate: string;
  endDate: string;
  events: FinancialEvent[];
}

export interface BankAnchoredForecast {
  openingBalance: number;
  events: FinancialEvent[];
}

/**
 * A canonical debt projection already owns the remaining payment for its source
 * debt and date. Drop any legacy bill-plan row for that same occurrence so one
 * obligation can never reduce Forecast twice or render two calendar chips.
 */
export function suppressDebtBillPlanDuplicates(events: readonly FinancialEvent[]): FinancialEvent[] {
  const canonicalDebtOccurrenceKeys = new Set(events
    .filter(event => (event.kind === "debt_payment" || event.sourceType === "extra_payment")
      && Boolean(event.debtTargetBillId))
    .map(event => `${event.date}:${event.debtTargetBillId}`));

  return events.filter(event => !(
    (event.kind === "bill" || event.sourceType === "bill")
    && canonicalDebtOccurrenceKeys.has(`${event.date}:${event.sourceId}`)
  ));
}

/**
 * Builds the balance side of a connected-bank forecast.
 *
 * Before the bank's as-of date, only settled ledger events may move the balance.
 * When a stable opening balance is available, a newly observed bank change lands
 * on the as-of date instead of rewriting prior days. A matching same-day plan is
 * absorbed once the bank has already included it. Unpaid bill/bucket/minimum-payment
 * commitments remain reserved on the observation date; history stays unchanged.
 */
export function anchorForecastToBankBalance(
  events: FinancialEvent[],
  bankBalance: number,
  anchorDate: string,
  settledEventIds: ReadonlySet<string>,
  historicalOpeningBalance?: number,
): BankAnchoredForecast {
  const settledEvents = events.filter(event => event.date <= anchorDate && settledEventIds.has(event.id));
  const settledNetThroughAnchor = settledEvents.reduce((sum, event) => sum + event.amount, 0);
  const settledToday = settledEvents.filter(event => event.date === anchorDate);
  const absorbedPlanIds = new Set<string>();
  const sameAmount = (left: number, right: number) => Math.abs(left - right) < 0.005;
  const absorbMatchingPlan = (amount: number) => {
    // A bank delta is not evidence that an unrelated bill was paid. Retain the
    // existing paycheck de-duplication, but settle expenses only by source match.
    if (amount <= 0) return;
    const match = events.find(event =>
      event.date === anchorDate
      && event.kind === "scheduled_income"
      && !absorbedPlanIds.has(event.id)
      && (event.status === "planned" || event.status === "scheduled")
      && sameAmount(event.amount, amount));
    if (match) absorbedPlanIds.add(match.id);
  };
  settledToday.forEach(event => absorbMatchingPlan(event.amount));

  const hasStableOpeningBalance = Number.isFinite(historicalOpeningBalance);
  const openingBalance = hasStableOpeningBalance ? Number(historicalOpeningBalance) : bankBalance - settledNetThroughAnchor;
  const bankGap = hasStableOpeningBalance ? bankBalance - (openingBalance + settledNetThroughAnchor) : 0;
  if (Math.abs(bankGap) >= 0.005) absorbMatchingPlan(bankGap);

  const isUnpaidObligation = (event: FinancialEvent) => event.amount < 0
    && (event.status === "planned" || event.status === "scheduled" || event.status === "pending")
    && (event.kind === "bill" || event.kind === "goal" || (event.kind === "debt_payment" && event.debtPlanAllocationKind === "required"));
  const balanceEvents = events.filter(event =>
    !absorbedPlanIds.has(event.id)
    && (
      event.date > anchorDate
      || settledEventIds.has(event.id)
      || (event.date < anchorDate && isUnpaidObligation(event))
      || (event.date === anchorDate && (
        (event.amount < 0 && event.status !== "finalized" && event.status !== "applied")
        || event.status === "planned"
        || event.status === "scheduled"
      ))
    )
  ).map(event => event.date < anchorDate && !settledEventIds.has(event.id) && isUnpaidObligation(event)
    ? { ...event, date: anchorDate }
    : event);
  if (Math.abs(bankGap) >= 0.005) {
    balanceEvents.push({
      id: `bank-anchor:${anchorDate}`,
      sourceType: "reconciliation",
      sourceId: anchorDate,
      date: anchorDate,
      kind: "bank_adjustment",
      amount: bankGap,
      status: "actual",
      name: "Bank balance update",
    });
  }

  return {
    openingBalance,
    events: balanceEvents,
  };
}

export interface ForecastDiagnostic {
  code: "invalid_event" | "outside_range" | "duplicate_event";
  eventId: string;
}

export interface ForecastDay {
  date: string;
  events: FinancialEvent[];
  net: number;
  balance: number;
}

export interface ForecastResult {
  days: ForecastDay[];
  diagnostics: ForecastDiagnostic[];
  lowestBalance: number;
  lowestBalanceDate: string;
  endingBalance: number;
}

export interface AffordabilityResult {
  projectedBalance: number;
  lowestBalance: number;
  lowestBalanceDate: string;
  canAfford: boolean;
  shortfall: number;
  result: ForecastResult;
}

function parseDateOnly(value: string): Date | null {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) return null;
  const date = new Date(`${value}T00:00:00Z`);
  return Number.isNaN(date.getTime()) ? null : date;
}

function toDateOnly(date: Date): string {
  return date.toISOString().slice(0, 10);
}

export function buildFinancialEvents(events: FinancialEvent[]): {
  events: FinancialEvent[];
  diagnostics: ForecastDiagnostic[];
} {
  const diagnostics: ForecastDiagnostic[] = [];
  const seen = new Set<string>();
  const valid = suppressDebtBillPlanDuplicates(events).filter(event => {
    if (!event.id || !event.sourceId || !parseDateOnly(event.date) || !Number.isFinite(event.amount)) {
      diagnostics.push({ code: "invalid_event", eventId: event.id || "unknown" });
      return false;
    }
    if (seen.has(event.id)) {
      diagnostics.push({ code: "duplicate_event", eventId: event.id });
      return false;
    }
    seen.add(event.id);
    return true;
  });
  return {
    events: valid
      .map(event => ({ ...event, amount: Number(event.amount) }))
      .sort((a, b) => a.date.localeCompare(b.date) || a.id.localeCompare(b.id)),
    diagnostics,
  };
}

export function forecastBalances(snapshot: ForecastSnapshot): ForecastResult {
  const start = parseDateOnly(snapshot.startDate);
  const end = parseDateOnly(snapshot.endDate);
  if (!start || !end || end < start) throw new Error("Invalid forecast date range");

  const built = buildFinancialEvents(snapshot.events);
  const diagnostics = [...built.diagnostics];
  const eventsByDate = new Map<string, FinancialEvent[]>();
  built.events.forEach(event => {
    if (event.date < snapshot.startDate || event.date > snapshot.endDate) {
      diagnostics.push({ code: "outside_range", eventId: event.id });
      return;
    }
    eventsByDate.set(event.date, [...(eventsByDate.get(event.date) ?? []), event]);
  });

  const days: ForecastDay[] = [];
  let balance = Number(snapshot.openingBalance) || 0;
  let lowestBalance = balance;
  let lowestBalanceDate = snapshot.startDate;
  for (let cursor = new Date(start); cursor <= end; cursor.setUTCDate(cursor.getUTCDate() + 1)) {
    const date = toDateOnly(cursor);
    const events = eventsByDate.get(date) ?? [];
    const net = events.reduce((sum, event) => sum + event.amount, 0);
    balance += net;
    if (balance < lowestBalance) {
      lowestBalance = balance;
      lowestBalanceDate = date;
    }
    days.push({ date, events, net, balance });
  }
  return {
    days,
    diagnostics,
    lowestBalance,
    lowestBalanceDate,
    endingBalance: balance,
  };
}

export function evaluateAffordability(
  snapshot: ForecastSnapshot,
  amount: number,
  date: string,
  safetyFloor = 0,
): AffordabilityResult {
  const expense = Math.max(0, amount);
  const result = forecastBalances({
    ...snapshot,
    events: [
      ...snapshot.events,
      {
        id: `decision:${date}:${expense}`,
        sourceType: "decision",
        sourceId: `decision:${date}`,
        date,
        kind: "transaction_expense",
        amount: -expense,
        status: "planned",
      },
    ],
  });
  const target = result.days.find(day => day.date === date);
  const shortfall = Math.max(0, safetyFloor - result.lowestBalance);
  return {
    projectedBalance: target?.balance ?? result.endingBalance,
    lowestBalance: result.lowestBalance,
    lowestBalanceDate: result.lowestBalanceDate,
    canAfford: shortfall <= 0.009,
    shortfall,
    result,
  };
}

