export type AccountType = "checking" | "savings" | "cash";

export interface AccountSnapshot {
  id: string;
  name: string;
  type: AccountType;
  currentBalance: number;
  balanceAsOf: string;
  lastReconciledAt?: string;
  active: boolean;
}

export interface ForecastConfidence {
  level: "high" | "medium" | "low";
  label: "High" | "Medium" | "Low";
  reasons: string[];
}

export interface ImportedTransactionRow {
  date: string;
  amount: number;
  description: string;
  importHash: string;
}

export interface ConnectedCheckingSnapshot {
  account_subtype?: string;
  current_balance: number;
  current_balance_available?: boolean;
  is_active: boolean;
  updated_at?: string | null;
}

export function connectedCheckingBalance(accounts: ConnectedCheckingSnapshot[]): number | null {
  const checking = accounts.filter(account => account.is_active && account.account_subtype === "checking");
  if (checking.some(account => account.current_balance_available === false || !Number.isFinite(account.current_balance))) {
    return null;
  }
  return checking.length ? checking.reduce((sum, account) => sum + account.current_balance, 0) : null;
}

export function connectedCheckingAnchor(accounts: ConnectedCheckingSnapshot[], date: string): { balance: number; date: string } | null {
  const balance = connectedCheckingBalance(accounts);
  return balance === null ? null : { balance, date };
}

export function connectedCheckingObservedAnchor(
  accounts: ConnectedCheckingSnapshot[],
  timeZone: string,
): { balance: number; date: string } | null {
  const checking = accounts.filter(account => account.is_active && account.account_subtype === "checking");
  const balance = connectedCheckingBalance(checking);
  if (balance === null) return null;
  const observations = checking.map(account => account.updated_at);
  if (observations.some(value => typeof value !== "string" || !Number.isFinite(Date.parse(value)))) return null;
  try {
    const dates = observations.map(value => localDateInTimeZone(new Date(value!), timeZone));
    if (new Set(dates).size !== 1) return null;
    return { balance, date: dates[0] };
  } catch {
    return null;
  }
}

export function historicalMonthOpeningBalance(
  projectedOpeningBalance: number,
  balanceAsOfDate: string | undefined,
  monthStartDate: string,
): number | undefined {
  if (!Number.isFinite(projectedOpeningBalance)) return undefined;
  if (!/^\d{4}-\d{2}-\d{2}$/.test(balanceAsOfDate ?? "")) return undefined;
  if (!/^\d{4}-\d{2}-\d{2}$/.test(monthStartDate)) return undefined;
  return balanceAsOfDate! <= monthStartDate ? projectedOpeningBalance : undefined;
}

export function accountForecastValue(account: Pick<AccountSnapshot, "type" | "currentBalance">): number {
  return account.currentBalance;
}

export function totalForecastBalance(accounts: AccountSnapshot[]): number {
  return accounts.filter(account => account.active).reduce((sum, account) => sum + accountForecastValue(account), 0);
}

export function operatingAccountAnchor(accounts: AccountSnapshot[]): { balance: number; date: string } | null {
  const active = accounts.filter(account => account.active);
  if (!active.length) return null;
  const operating = active.filter(account => account.type === "checking" || account.type === "cash");
  if (!operating.length) return null;
  const dates = operating.map(account => account.balanceAsOf);
  if (dates.some(date => !/^\d{4}-\d{2}-\d{2}$/.test(date))) return null;
  const uniqueDates = new Set(dates);
  if (uniqueDates.size !== 1) return null;
  return { balance: totalForecastBalance(operating), date: dates[0] };
}

export function accountUpdatesOperatingAnchor(account: AccountSnapshot): boolean {
  return account.active && (account.type === "checking" || account.type === "cash");
}

export function bankBalanceAdjustment(
  openingBalance: number,
  bankBalance: number,
  reconciliationDate: string,
  events: Array<{ date: string; amount: number }>,
): number {
  const netThroughReconciliation = events
    .filter(event => event.date <= reconciliationDate)
    .reduce((sum, event) => sum + event.amount, 0);
  return bankBalance - (openingBalance + netThroughReconciliation);
}

export function evaluateForecastConfidence(
  accounts: AccountSnapshot[],
  hasIncome: boolean,
  hasBills: boolean,
  now = new Date()
): ForecastConfidence {
  const active = accounts.filter(account => account.active);
  const reasons: string[] = [];
  if (!active.length) reasons.push("Add an account balance");
  if (!hasIncome) reasons.push("Add an income source");
  if (!hasBills) reasons.push("Add recurring bills");

  let oldestDays = 0;
  if (active.length) {
    oldestDays = Math.max(...active.map(account => {
      const reviewed = account.lastReconciledAt ?? account.balanceAsOf;
      const elapsed = now.getTime() - new Date(`${reviewed.slice(0, 10)}T00:00:00`).getTime();
      return Number.isFinite(elapsed) ? Math.max(0, Math.floor(elapsed / 86_400_000)) : 999;
    }));
    if (oldestDays > 30) reasons.push("Reconcile accounts older than 30 days");
    else if (oldestDays > 7) reasons.push("Reconcile accounts for the strongest forecast");
  }

  if (!active.length || !hasIncome || !hasBills || oldestDays > 30) return { level: "low", label: "Low", reasons };
  if (oldestDays > 7) return { level: "medium", label: "Medium", reasons };
  return { level: "high", label: "High", reasons: ["Accounts and recurring cash flow are current"] };
}

function csvCells(line: string): string[] {
  const cells: string[] = [];
  let value = "";
  let quoted = false;
  for (let i = 0; i < line.length; i++) {
    const char = line[i];
    if (char === '"' && line[i + 1] === '"' && quoted) { value += '"'; i++; }
    else if (char === '"') quoted = !quoted;
    else if (char === "," && !quoted) { cells.push(value.trim()); value = ""; }
    else value += char;
  }
  cells.push(value.trim());
  return cells;
}

function normalizeDate(value: string): string | null {
  const trimmed = value.trim();
  const iso = /^(\d{4})-(\d{1,2})-(\d{1,2})$/.exec(trimmed);
  const us = /^(\d{1,2})\/(\d{1,2})\/(\d{2}|\d{4})$/.exec(trimmed);
  const parts = iso
    ? { year: Number(iso[1]), month: Number(iso[2]), day: Number(iso[3]) }
    : us
      ? { year: Number(us[3].length === 2 ? `20${us[3]}` : us[3]), month: Number(us[1]), day: Number(us[2]) }
      : null;
  if (!parts) return null;
  const parsed = new Date(Date.UTC(parts.year, parts.month - 1, parts.day));
  if (
    parsed.getUTCFullYear() !== parts.year
    || parsed.getUTCMonth() !== parts.month - 1
    || parsed.getUTCDate() !== parts.day
  ) {
    return null;
  }
  return `${parts.year}-${String(parts.month).padStart(2, "0")}-${String(parts.day).padStart(2, "0")}`;
}

export function transactionImportHash(accountId: string, date: string, amount: number, description: string): string {
  const input = `${accountId}|${date}|${amount.toFixed(2)}|${description.trim().toLowerCase().replace(/\s+/g, " ")}`;
  let hash = 2166136261;
  for (let i = 0; i < input.length; i++) {
    hash ^= input.charCodeAt(i);
    hash = Math.imul(hash, 16777619);
  }
  return `statement_${(hash >>> 0).toString(16).padStart(8, "0")}`;
}

export function parseStatementCsv(csv: string, accountId: string): ImportedTransactionRow[] {
  const lines = csv.replace(/^\uFEFF/, "").split(/\r?\n/).filter(line => line.trim());
  if (lines.length < 2) return [];
  const headers = csvCells(lines[0]).map(header => header.toLowerCase().replace(/[^a-z]/g, ""));
  const dateIndex = headers.findIndex(header => ["date", "transactiondate", "posteddate"].includes(header));
  const descriptionIndex = headers.findIndex(header => ["description", "name", "memo", "details", "merchant"].includes(header));
  const amountIndex = headers.findIndex(header => ["amount", "transactionamount"].includes(header));
  const debitIndex = headers.findIndex(header => ["debit", "withdrawal", "withdrawals"].includes(header));
  const creditIndex = headers.findIndex(header => ["credit", "deposit", "deposits"].includes(header));
  if (dateIndex < 0 || descriptionIndex < 0 || (amountIndex < 0 && debitIndex < 0 && creditIndex < 0)) return [];

  return lines.slice(1).flatMap(line => {
    const cells = csvCells(line);
    const date = normalizeDate(cells[dateIndex] ?? "");
    const description = (cells[descriptionIndex] ?? "").trim();
    const number = (value: string | undefined) => Number((value ?? "").replace(/[$,()]/g, match => match === "(" ? "-" : ""));
    let amount = amountIndex >= 0 ? number(cells[amountIndex]) : 0;
    if (amountIndex < 0) amount = (creditIndex >= 0 ? Math.abs(number(cells[creditIndex]) || 0) : 0) - (debitIndex >= 0 ? Math.abs(number(cells[debitIndex]) || 0) : 0);
    if (!date || !description || !Number.isFinite(amount) || amount === 0) return [];
    return [{ date, amount, description, importHash: transactionImportHash(accountId, date, amount, description) }];
  });
}

export type DailyBalanceSource = "projected" | "actual_close" | "unavailable";
export type DailyCheckingCloseLoadStatus = "loading" | "ready" | "error";

export interface DailyCheckingCloseSnapshot {
  balance_date: string;
  checking_balance: number;
  observed_at: string;
  account_count: number;
  source: "plaid_sync";
}

export interface DailyCheckingCloseLoadState {
  scopeKey: string | null;
  status: DailyCheckingCloseLoadStatus;
}

/**
 * Preserve React state identity when the optional close-history response is
 * byte-for-byte equivalent to the exact-scope cache already on screen.
 * Close rows arrive in a canonical newest-first order, so order is part of the
 * equality contract and a changed order is deliberately published.
 */
export function reuseDailyCheckingCloseSnapshots(
  current: DailyCheckingCloseSnapshot[],
  next: DailyCheckingCloseSnapshot[],
): DailyCheckingCloseSnapshot[] {
  if (
    current.length === next.length
    && current.every((row, index) => {
      const candidate = next[index];
      return candidate !== undefined
        && row.balance_date === candidate.balance_date
        && Object.is(row.checking_balance, candidate.checking_balance)
        && row.observed_at === candidate.observed_at
        && row.account_count === candidate.account_count
        && row.source === candidate.source;
    })
  ) return current;
  return next;
}

export function reuseDailyCheckingCloseLoadState(
  current: DailyCheckingCloseLoadState,
  next: DailyCheckingCloseLoadState,
): DailyCheckingCloseLoadState {
  return current.scopeKey === next.scopeKey && current.status === next.status
    ? current
    : next;
}

export interface DailyBalanceCloseMetadata {
  balanceSource: DailyBalanceSource;
  balanceDate: string;
  balanceObservedAt?: string;
  balanceUnavailableReason?: "history_loading" | "history_error" | "close_not_recorded";
}

export function calendarBalanceIsVisible(
  day: Pick<DailyBalanceCloseMetadata, "balanceSource"> | null | undefined,
): boolean {
  return Boolean(day && day.balanceSource !== "unavailable");
}

export type DailyCheckingClosePageResult = {
  data: DailyCheckingCloseSnapshot[] | null;
  error: { message: string } | null;
};

const ISO_DATE = /^\d{4}-\d{2}-\d{2}$/;

export function shouldApplyDailyCheckingCloseLoad(
  requestGeneration: number,
  latestGeneration: number,
  scopeIsCurrent: boolean,
): boolean {
  return scopeIsCurrent && requestGeneration === latestGeneration;
}

export function localDateInTimeZone(now: Date, timeZone: string): string {
  const parts = new Intl.DateTimeFormat("en-CA", {
    timeZone,
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
  }).formatToParts(now);
  const value = Object.fromEntries(parts.map(part => [part.type, part.value]));
  return `${value.year}-${value.month}-${value.day}`;
}

export function overlayCompletedDailyCheckingCloses<
  T extends { day: number; balance: number },
>(
  projectedDays: T[],
  month: number,
  year: number,
  snapshots: DailyCheckingCloseSnapshot[],
  householdLocalToday: string,
  _historyStatus: DailyCheckingCloseLoadStatus = "ready",
): Array<T & DailyBalanceCloseMetadata> {
  const monthPrefix = `${year}-${String(month + 1).padStart(2, "0")}`;
  const completedByDay = new Map<number, DailyCheckingCloseSnapshot>();

  if (ISO_DATE.test(householdLocalToday)) {
    snapshots.forEach(snapshot => {
      if (!ISO_DATE.test(snapshot.balance_date)) return;
      if (!snapshot.balance_date.startsWith(`${monthPrefix}-`)) return;
      if (snapshot.balance_date >= householdLocalToday) return;
      if (!Number.isFinite(snapshot.checking_balance)) return;
      const day = Number(snapshot.balance_date.slice(8, 10));
      const current = completedByDay.get(day);
      if (!current || snapshot.observed_at > current.observed_at) completedByDay.set(day, snapshot);
    });
  }

  return projectedDays.map(projected => {
    const balanceDate = `${monthPrefix}-${String(projected.day).padStart(2, "0")}`;
    if (!ISO_DATE.test(householdLocalToday) || balanceDate >= householdLocalToday) {
      return {
        ...projected,
        balanceSource: "projected",
        balanceDate,
      };
    }
    const actual = completedByDay.get(projected.day);
    if (!actual) {
      return {
        ...projected,
        balanceSource: "projected",
        balanceDate,
      };
    }
    // Close history replaces only this completed date. Today and future dates
    // are already anchored to the current bank balance by the projection engine.
    return {
      ...projected,
      balance: actual.checking_balance,
      balanceSource: "actual_close",
      balanceDate,
      balanceObservedAt: actual.observed_at,
    };
  });
}

export async function loadAllDailyCheckingCloses(
  fetchPage: (from: number, to: number) => Promise<DailyCheckingClosePageResult>,
  pageSize = 200,
): Promise<DailyCheckingClosePageResult> {
  const rows: DailyCheckingCloseSnapshot[] = [];
  for (let from = 0; ; from += pageSize) {
    const page = await fetchPage(from, from + pageSize - 1);
    if (page.error) return { data: null, error: page.error };
    const pageRows = page.data ?? [];
    rows.push(...pageRows);
    if (pageRows.length < pageSize) return { data: rows, error: null };
  }
}

export type DecisionType = "one_time_purchase" | "recurring_bill" | "income_change" | "payment_date_change" | "savings_contribution" | "extra_debt_payment";
export type DecisionVerdict = "safe" | "caution" | "unsafe";

export interface DecisionScenario {
  type: DecisionType;
  name: string;
  amount: number;
  date: string;
  frequency?: "once" | "weekly" | "biweekly" | "monthly";
  sourceId?: string;
  oldDate?: string;
}
export interface DecisionBaselineDay { date: string; balance: number }
export interface DecisionResult {
  verdict: DecisionVerdict;
  lowestBalance: number;
  lowestBalanceDate: string;
  monthlyCashFlowChange: number;
  saferAmount: number;
  explanation: string;
  affectedDates: string[];
}

function addDays(date: string, days: number) {
  const value = new Date(`${date}T00:00:00Z`); value.setUTCDate(value.getUTCDate() + days); return value.toISOString().slice(0, 10);
}
function addMonth(date: string) {
  const [y, m, d] = date.split("-").map(Number); const next = new Date(Date.UTC(y, m, 1));
  return `${next.getUTCFullYear()}-${String(next.getUTCMonth() + 1).padStart(2, "0")}-${String(Math.min(d, new Date(Date.UTC(next.getUTCFullYear(), next.getUTCMonth() + 1, 0)).getUTCDate())).padStart(2, "0")}`;
}
export function scenarioDates(scenario: DecisionScenario, endDate: string): string[] {
  if (scenario.type === "payment_date_change") return [scenario.date];
  const frequency = scenario.frequency ?? (scenario.type === "recurring_bill" || scenario.type === "income_change" ? "monthly" : "once");
  const dates: string[] = []; let date = scenario.date;
  while (date <= endDate) { dates.push(date); if (frequency === "once") break; date = frequency === "weekly" ? addDays(date, 7) : frequency === "biweekly" ? addDays(date, 14) : addMonth(date); }
  return dates;
}
export function evaluateDecision(days: DecisionBaselineDay[], scenario: DecisionScenario, safetyFloor: number): DecisionResult {
  if (!days.length) throw new Error("Decision forecast requires baseline days");
  const dates = scenarioDates(scenario, days[days.length - 1].date);
  const expense = scenario.type === "income_change" ? -scenario.amount : Math.abs(scenario.amount);
  let lowestBalance = Infinity, lowestBalanceDate = days[0].date;
  for (const day of days) {
    let adjustment = dates.filter(date => date <= day.date).length * expense;
    if (scenario.type === "payment_date_change" && scenario.oldDate) {
      adjustment = (scenario.oldDate <= day.date ? -Math.abs(scenario.amount) : 0) + (scenario.date <= day.date ? Math.abs(scenario.amount) : 0);
    }
    const balance = day.balance - adjustment;
    if (balance < lowestBalance) { lowestBalance = balance; lowestBalanceDate = day.date; }
  }
  const headroom = Math.max(0, lowestBalance - safetyFloor);
  const cautionBand = Math.max(100, safetyFloor * 0.5);
  const verdict: DecisionVerdict = lowestBalance < safetyFloor ? "unsafe" : lowestBalance < safetyFloor + cautionBand ? "caution" : "safe";
  const monthlyMultiplier = (scenario.frequency ?? "once") === "weekly" ? 52 / 12 : scenario.frequency === "biweekly" ? 26 / 12 : 1;
  const monthlyCashFlowChange = scenario.type === "recurring_bill" || scenario.type === "income_change" ? -expense * monthlyMultiplier : 0;
  const saferAmount = verdict === "unsafe" ? Math.max(0, Math.abs(scenario.amount) - (safetyFloor - lowestBalance)) : Math.abs(scenario.amount) + headroom;
  const explanation = verdict === "safe" ? `This keeps at least $${lowestBalance.toFixed(0)} available.` : verdict === "caution" ? `This keeps $${headroom.toFixed(0)} of breathing room above your floor.` : `Add $${(safetyFloor - lowestBalance).toFixed(0)} more breathing room or choose a later date to protect your safety floor.`;
  return { verdict, lowestBalance, lowestBalanceDate, monthlyCashFlowChange, saferAmount, explanation, affectedDates: dates };
}
export function compareDecisionVariants(days: DecisionBaselineDay[], scenarios: DecisionScenario[], safetyFloor: number) {
  return scenarios.slice(0, 3).map(scenario => ({ scenario, result: evaluateDecision(days, scenario, safetyFloor) }));
}

