function parseIsoDate(value: string) {
  const [year, month, day] = value.split("-").map(Number);
  if (![year, month, day].every(Number.isFinite)) return null;
  return Date.UTC(year, month - 1, day);
}

const GENERIC_BANK_TOKENS = new Set([
  "bank", "card", "debit", "electronic", "online", "payment", "pmt", "posted", "purchase", "transaction", "withdrawal",
]);

function normalizedTokens(value: string) {
  return value
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, " ")
    .trim()
    .split(/\s+/)
    .filter(token => token.length > 2 && !GENERIC_BANK_TOKENS.has(token));
}

export function buildForgottenBillDefaults(transaction: Pick<ReviewTransactionLike, "amount" | "date" | "note" | "merchant_name" | "category">): ForgottenBillDefaults {
  const parsedDay = Number(transaction.date.slice(8, 10));
  return {
    name: transaction.merchant_name?.trim() || transaction.note?.trim() || transaction.category || "New bill",
    amount: Math.abs(transaction.amount),
    category: transaction.category && transaction.category !== "Income" ? transaction.category : "Other",
    dueDay: Number.isFinite(parsedDay) && parsedDay > 0 ? parsedDay : 1,
    nextPaymentDate: transaction.date,
    startDate: transaction.date,
    isRecurring: true,
    frequency: "monthly",
  };
}

export function forgottenBillSettlement(actualAmount: number, plannedAmount: number): "exact" | "full" {
  return Math.abs(Math.abs(actualAmount) - Math.abs(plannedAmount)) < 0.005 ? "exact" : "full";
}

function previousMonthEnd(todayIso: string): string | null {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(todayIso)) return null;
  const year = Number(todayIso.slice(0, 4));
  const month = Number(todayIso.slice(5, 7));
  if (!Number.isInteger(year) || !Number.isInteger(month) || month < 1 || month > 12) return null;
  return new Date(Date.UTC(year, month - 1, 0)).toISOString().slice(0, 10);
}

export function buildReviewQueue<T extends ReviewTransactionLike>(
  transactions: T[],
  todayIso: string,
  focusTransactionId?: string,
): T[] {
  const monthPrefix = todayIso.slice(0, 7);
  const rolloverDate = previousMonthEnd(todayIso);
  const queue = transactions
    .filter(transaction => isReviewQueueCandidate(
      transaction,
      monthPrefix,
      rolloverDate,
      focusTransactionId,
    ))
    .sort((left, right) => left.date.localeCompare(right.date) || left.id.localeCompare(right.id));
  return prioritizeReviewTransaction(queue, focusTransactionId);
}

function isReviewQueueCandidate(
  transaction: ReviewTransactionLike,
  monthPrefix: string,
  rolloverDate: string | null,
  focusTransactionId?: string,
): boolean {
  return !transaction.removed_at
    && transaction.pending !== true
    && transaction.source === "plaid"
    && (
      transaction.id === focusTransactionId
      || transaction.date.startsWith(monthPrefix)
      || transaction.date === rolloverDate
    )
    && transaction.review_status === "needs_review";
}

/** Count-only Dashboard selector. It preserves buildReviewQueue membership
 * exactly without sorting a large current-month review list. */
export function countReviewQueue(
  transactions: ReviewTransactionLike[],
  todayIso: string,
  focusTransactionId?: string,
): number {
  const monthPrefix = todayIso.slice(0, 7);
  const rolloverDate = previousMonthEnd(todayIso);
  let count = 0;
  transactions.forEach(transaction => {
    if (isReviewQueueCandidate(
      transaction,
      monthPrefix,
      rolloverDate,
      focusTransactionId,
    )) count += 1;
  });
  return count;
}

export function reviewQueueAfterSkips<T extends Pick<ReviewTransactionLike, "id">>(queue: T[], skippedIds: string[]): T[] {
  if (skippedIds.length === 0) return queue;
  const skipped = new Set(skippedIds);
  return queue.filter(transaction => !skipped.has(transaction.id));
}

export function prioritizeReviewTransaction<T extends Pick<ReviewTransactionLike, "id">>(queue: T[], transactionId?: string): T[] {
  if (!transactionId || queue[0]?.id === transactionId) return queue;
  const focusedIndex = queue.findIndex(transaction => transaction.id === transactionId);
  if (focusedIndex < 0) return queue;
  return [queue[focusedIndex], ...queue.slice(0, focusedIndex), ...queue.slice(focusedIndex + 1)];
}

export function rankReviewTargets(transaction: Pick<ReviewTransactionLike, "amount" | "date" | "note" | "merchant_name" | "category">, targets: ReviewTarget[]): RankedReviewTarget[] {
  const actual = Math.abs(transaction.amount);
  const txDate = parseIsoDate(transaction.date);
  const descriptionTokens = new Set(normalizedTokens(transaction.merchant_name || transaction.note || transaction.category || ""));

  return targets.map(target => {
    const amountDifference = Math.abs(actual - target.plannedAmount);
    const amountRatio = target.plannedAmount > 0 ? amountDifference / target.plannedAmount : 1;
    const targetDate = parseIsoDate(target.occurrenceDate);
    const daysApart = txDate !== null && targetDate !== null ? Math.round(Math.abs(txDate - targetDate) / 86_400_000) : 99;
    const targetTokens = normalizedTokens(`${target.name} ${target.category}`);
    const tokenMatches = targetTokens.filter(token => descriptionTokens.has(token)).length;
    const reasons: string[] = [];
    let score = 0;

    if (amountDifference < 0.005) { score += 56; reasons.push("Exact amount"); }
    else if (amountRatio <= 0.05) { score += 45; reasons.push("Amount is very close"); }
    else if (amountRatio <= 0.2) { score += 28; reasons.push("Amount is close"); }
    else if (amountRatio <= 0.5) score += 10;

    if (daysApart === 0) { score += 30; reasons.push("Same date"); }
    else if (daysApart <= 2) { score += 24; reasons.push(`${daysApart} day${daysApart === 1 ? "" : "s"} from plan`); }
    else if (daysApart <= 7) { score += 14; reasons.push(`${daysApart} days from plan`); }
    else if (daysApart <= 14) score += 5;

    if (tokenMatches >= 2) { score += 30; reasons.push("Name strongly matches"); }
    else if (tokenMatches === 1) { score += 14; reasons.push("Name matches"); }
    if ((transaction.amount > 0) === (target.type === "income")) score += 4;

    return { ...target, score, daysApart, amountDifference, reasons };
  }).sort((left, right) => right.score - left.score || left.daysApart - right.daysApart || left.amountDifference - right.amountDifference);
}

export function incomeReviewTargets(
  incomes: ReviewIncomeLike[],
  transactionDate: string,
  matches: Map<string, ReviewAllocationLike>,
): ReviewTarget[] {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(transactionDate.slice(0, 10))) return [];
  const date = transactionDate.slice(0, 10);
  const [currentYear, currentMonthNumber] = date.split("-").map(Number);
  const currentMonth = currentMonthNumber - 1;
  const currentPrefix = date.slice(0, 7);
  const targets: ReviewTarget[] = [];

  incomes.forEach(income => {
    const occurrenceDates = new Set(
      getIncomeOccurrenceDays(income, currentMonth, currentYear)
        .map(day => `${currentPrefix}-${String(day).padStart(2, "0")}`),
    );
    getIncomeMatchOccurrenceDates(income, date)
      .filter(occurrenceDate => !occurrenceDate.startsWith(currentPrefix))
      .forEach(occurrenceDate => occurrenceDates.add(occurrenceDate));

    occurrenceDates.forEach(occurrenceDate => {
      const [year, monthNumber] = occurrenceDate.split("-").map(Number);
      const plannedAmount = getEffectiveIncomeAmount(income, monthNumber - 1, year);
      const previous = matches.get(occurrenceKey(income.id, occurrenceDate));
      const remaining = Math.max(0, plannedAmount - Number(previous?.amount || 0));
      if (remaining <= 0.005) return;
      targets.push({
        type: "income",
        id: income.id,
        name: income.name,
        category: "Income",
        plannedAmount: remaining,
        occurrenceDate,
      });
    });
  });

  return targets;
}

function normalizedMerchant(value: string) {
  return normalizedTokens(value).join(" ");
}

function allocationMatchesTarget(allocation: ReviewAllocationLike, target: ReviewTarget) {
  if (!allocation.targetId || allocation.targetId !== target.id) return false;
  if (target.type === "bill") return allocation.type === "bill";
  if (target.type === "income") return allocation.type === "income";
  if (target.type === "snowball") return allocation.type === "extra_principal";
  if (target.type === "manual") {
    return allocation.type === "planned_expense" && allocation.source === "transaction";
  }
  if (target.type === "goal" || target.type === "decision") {
    return allocation.type === "planned_expense" && allocation.source === target.type;
  }
  return false;
}

export function applyMatchMemory(
  current: Pick<ReviewTransactionLike, "id" | "note" | "merchant_name" | "category">,
  rankedTargets: RankedReviewTarget[],
  history: ReviewTransactionLike[],
): RankedReviewTarget[] {
  const currentMerchant = normalizedMerchant(current.merchant_name || current.note || current.category || "");
  if (!currentMerchant) return rankedTargets;

  return rankedTargets.map(target => {
    const count = history.filter(transaction => {
      if (transaction.id === current.id || transaction.review_status !== "matched") return false;
      const merchant = normalizedMerchant(transaction.merchant_name || transaction.note || transaction.category || "");
      return merchant === currentMerchant
        && (transaction.review_allocations ?? []).some(allocation => allocationMatchesTarget(allocation, target));
    }).length;
    if (!count) return target;
    return {
      ...target,
      score: target.score + 38 + Math.min(12, (count - 1) * 4),
      reasons: [`Matched here ${count === 1 ? "before" : `${count} times`}`, ...target.reasons],
    };
  }).sort((left, right) => right.score - left.score || left.daysApart - right.daysApart || left.amountDifference - right.amountDifference);
}

/** Put a household's explicit subscription-to-bill choice ahead of guesses. */
export function prioritizeSavedBillTarget(
  rankedTargets: RankedReviewTarget[],
  billId?: string | null,
): RankedReviewTarget[] {
  if (!billId) return rankedTargets;
  const preferred = rankedTargets.filter(target => target.type === "bill" && target.id === billId);
  if (!preferred.length) return rankedTargets;
  const other = rankedTargets.filter(target => target.type !== "bill" || target.id !== billId);
  return [
    ...preferred.map(target => ({
      ...target,
      score: Math.max(target.score, 1_000),
      reasons: ["Linked from Subscriptions", ...target.reasons.filter(reason => reason !== "Linked from Subscriptions")],
    })),
    ...other,
  ];
}

export function allocationTotal(allocations: ReviewAllocationLike[] | undefined): number {
  return Math.round((allocations ?? []).reduce((sum, allocation) => sum + Math.max(0, Number(allocation.amount) || 0), 0) * 100) / 100;
}

export function allocationAmount(transaction: ReviewTransactionLike, type: ReviewAllocationLike["type"]): number {
  return Math.round((transaction.review_allocations ?? [])
    .filter(allocation => allocation.type === type)
    .reduce((sum, allocation) => sum + Math.max(0, allocation.amount), 0) * 100) / 100;
}

export function reviewSettlementSummary(transaction: Pick<ReviewTransactionLike, "amount" | "review_allocations">): { amount: number; paid: number; remaining: number } {
  const paid = Math.round(Math.abs(Number(transaction.amount) || 0) * 100) / 100;
  const allocations = (transaction.review_allocations ?? []).filter(allocation => allocation.type !== "transfer");
  if (allocations.length === 0) return { amount: paid, paid, remaining: 0 };

  const amount = Math.round(allocations.reduce((sum, allocation) => {
    const planned = allocation.plannedAmount ?? allocation.amount;
    return sum + Math.max(0, Number(planned) || 0);
  }, 0) * 100) / 100;
  const remaining = Math.round(allocations.reduce((sum, allocation) => {
    if (allocation.settlement !== "partial") return sum;
    return sum + Math.max(0, Number(allocation.plannedAmount ?? allocation.amount) - Number(allocation.amount || 0));
  }, 0) * 100) / 100;

  return { amount: amount || paid, paid, remaining };
}

export function occurrenceKey(targetId: string, occurrenceDate: string): string {
  return `${targetId}:${occurrenceDate.slice(0, 10)}`;
}

/** Resolve only the lookup copy; saved allocation dates remain an audit of the original review. */
export function resolvedMatchedIncomeAllocation(
  allocation: ReviewAllocationLike,
  transactionDate: string,
  incomesById: ReadonlyMap<string, ReviewIncomeLike>,
): ReviewAllocationLike {
  if (allocation.type !== "income" || !allocation.targetId || !allocation.occurrenceDate) return allocation;
  const income = incomesById.get(allocation.targetId);
  if (!income) return allocation;
  const occurrenceDate = resolveIncomeMatchOccurrenceDate(income, transactionDate, allocation.occurrenceDate);
  return occurrenceDate && occurrenceDate !== allocation.occurrenceDate
    ? { ...allocation, occurrenceDate }
    : allocation;
}

/** Remaining amount for a reviewed card, counted once per current occurrence. */
export function reviewTransactionRemaining(
  transaction: Pick<ReviewTransactionLike, "amount" | "date" | "review_allocations">,
  billMatches: ReadonlyMap<string, ReviewAllocationLike>,
  incomeMatches: ReadonlyMap<string, ReviewAllocationLike>,
  incomesById: ReadonlyMap<string, ReviewIncomeLike>,
): number {
  const partialAllocations = (transaction.review_allocations ?? [])
    .filter(allocation => allocation.settlement === "partial");
  if (partialAllocations.length === 0) return reviewSettlementSummary(transaction).remaining;

  const counted = new Set<string>();
  const remaining = partialAllocations.reduce((sum, storedAllocation) => {
    const allocation = resolvedMatchedIncomeAllocation(storedAllocation, transaction.date, incomesById);
    if (!allocation.targetId || !allocation.occurrenceDate) {
      return sum + Math.max(0, Number(allocation.plannedAmount ?? allocation.amount) - Number(allocation.amount));
    }
    const key = occurrenceKey(allocation.targetId, allocation.occurrenceDate);
    const aggregate = allocation.type === "bill"
      ? billMatches.get(key)
      : allocation.type === "income"
        ? incomeMatches.get(key)
        : undefined;
    if (!aggregate) {
      return sum + Math.max(0, Number(allocation.plannedAmount ?? allocation.amount) - Number(allocation.amount));
    }
    const countedKey = `${allocation.type}:${key}`;
    if (counted.has(countedKey)) return sum;
    counted.add(countedKey);
    return sum + Math.max(0, Number(aggregate.plannedAmount ?? allocation.plannedAmount ?? aggregate.amount) - Number(aggregate.amount));
  }, 0);
  return Math.round(remaining * 100) / 100;
}

export function groupPlannedExpenseAllocations(
  transactions: ReviewTransactionLike[],
): PlannedExpenseAllocationGroup[] {
  const groups = new Map<string, PlannedExpenseAllocationGroup>();

  transactions.forEach(transaction => {
    if (transaction.review_status !== "matched") return;
    (transaction.review_allocations ?? []).forEach(allocation => {
      const source = allocation.source
        ?? (transaction.review_resolution === "goal" || transaction.review_resolution === "decision"
          ? transaction.review_resolution
          : undefined);
      if (allocation.type !== "planned_expense" || !allocation.targetId || !source) return;
      const occurrenceDate = allocation.occurrenceDate?.slice(0, 10) || transaction.date.slice(0, 10);
      const key = `${source}:${allocation.targetId}:${occurrenceDate}`;
      const existing = groups.get(key);
      const spentAmount = Math.max(0, Number(allocation.amount) || 0);
      const plannedAmount = Math.max(0, Number(allocation.plannedAmount ?? allocation.amount) || 0);

      if (!existing) {
        groups.set(key, {
          key,
          targetId: allocation.targetId,
          source,
          name: allocation.name || transaction.note || "Planned spending",
          occurrenceDate,
          plannedAmount,
          spentAmount,
          settlement: allocation.settlement,
          transactionIds: [transaction.id],
        });
        return;
      }

      existing.plannedAmount = Math.max(existing.plannedAmount, plannedAmount);
      existing.spentAmount = Math.round((existing.spentAmount + spentAmount) * 100) / 100;
      if (allocation.settlement && allocation.settlement !== "partial") existing.settlement = allocation.settlement;
      if (!existing.transactionIds.includes(transaction.id)) existing.transactionIds.push(transaction.id);
    });
  });

  return Array.from(groups.values()).sort((left, right) =>
    left.occurrenceDate.localeCompare(right.occurrenceDate) || left.name.localeCompare(right.name));
}

export function matchedOccurrenceKeys(
  transactions: ReviewTransactionLike[],
  type: "bill" | "income",
): Set<string> {
  const keys = new Set<string>();
  transactions.forEach(transaction => {
    if (transaction.review_status !== "matched") return;
    (transaction.review_allocations ?? []).forEach(allocation => {
      if (allocation.type !== type || !allocation.targetId || !allocation.occurrenceDate) return;
      keys.add(occurrenceKey(allocation.targetId, allocation.occurrenceDate));
    });
  });
  return keys;
}

export function matchedOccurrenceAllocations(
  transactions: ReviewTransactionLike[],
  type: "bill" | "income" | "extra_principal",
  resolution?: string,
  incomes?: ReviewIncomeLike[],
): Map<string, ReviewAllocationLike> {
  const matches = new Map<string, ReviewAllocationLike>();
  const incomesById = new Map(incomes?.map(income => [income.id, income]));
  transactions.forEach(transaction => {
    if (transaction.review_status !== "matched") return;
    if (resolution && transaction.review_resolution !== resolution) return;
    (transaction.review_allocations ?? []).forEach(storedAllocation => {
      const allocation = type === "income"
        ? resolvedMatchedIncomeAllocation(storedAllocation, transaction.date, incomesById)
        : storedAllocation;
      if (allocation.type !== type || !allocation.targetId || !allocation.occurrenceDate) return;
      const key = occurrenceKey(allocation.targetId, allocation.occurrenceDate);
      const existing = matches.get(key);
      const allocationAmount = Math.max(0, Number(allocation.amount) || 0);
      const allocationPlanned = Math.max(
        allocationAmount,
        Number(allocation.plannedAmount ?? allocation.amount) || 0,
      );
      const allocationClosed = allocation.settlement === "exact" || allocation.settlement === "full";
      if (!existing) {
        matches.set(key, {
          ...allocation,
          amount: allocationAmount,
          // Exact and user-confirmed full payments define the completed
          // occurrence at the amount actually paid. The old planned value may
          // include a snowball target that was never lender-required.
          plannedAmount: allocationClosed ? allocationAmount : allocationPlanned,
        });
        return;
      }
      const amount = Math.round((Number(existing.amount || 0) + allocationAmount) * 100) / 100;
      const historicalPlannedAmount = Math.max(
        Number(existing.plannedAmount || 0),
        allocationPlanned,
      );
      const existingClosed = existing.settlement === "exact" || existing.settlement === "full";
      const explicitlyClosed = existingClosed || allocationClosed;
      const closedSettlement = allocationClosed ? allocation.settlement : existing.settlement;
      matches.set(key, {
        ...allocation,
        amount,
        plannedAmount: explicitlyClosed ? amount : historicalPlannedAmount,
        settlement: explicitlyClosed
          ? closedSettlement
          : historicalPlannedAmount > 0 && amount + 0.005 < historicalPlannedAmount
            ? "partial"
            : allocation.settlement,
      });
    });
  });
  return matches;
}

export function matchedIncomeOccurrenceAllocations(
  transactions: ReviewTransactionLike[],
  incomes: ReviewIncomeLike[],
): Map<string, ReviewAllocationLike> {
  return matchedOccurrenceAllocations(transactions, "income", undefined, incomes);
}

export function groupReviewTargets(targets: RankedReviewTarget[]) {
  return {
    setAside: targets.filter(target => target.type === "goal" || target.type === "decision"),
    bills: targets.filter(target => target.type === "bill" || target.type === "snowball"),
    manual: targets.filter(target => target.type === "manual"),
    income: targets.filter(target => target.type === "income"),
  };
}

export function scheduledSnowballReviewTargets(
  transactions: ReviewTransactionLike[],
  monthPrefix: string,
  _matches: Map<string, ReviewAllocationLike>,
): ReviewTarget[] {
  const targets = new Map<string, ReviewTarget>();

  transactions.forEach(transaction => {
    if (
      transaction.removed_at
      || transaction.pending
      || transaction.amount >= 0
      || !transaction.date.startsWith(monthPrefix)
      || !isScheduledSnowballPlanTransaction(transaction)
    ) return;

    const debtId = transaction.debt_applied_bill_id ?? transaction.linked_bill_id;
    if (!debtId) return;

    const occurrenceDate = transaction.date.slice(0, 10);
    // Scheduled plan rows store their current unmatched remainder. Prior
    // reconciliations are still useful for summaries, but subtracting them
    // here would count a partial payment twice.
    const remaining = Math.abs(Number(transaction.amount) || 0);
    if (remaining <= 0.005) return;

    const name = snowballPaymentName(transaction, "Debt");
    targets.set(occurrenceKey(debtId, occurrenceDate), {
      type: "snowball",
      id: debtId,
      name: `${name} snowball`,
      category: "Debt",
      plannedAmount: remaining,
      occurrenceDate,
      isDebt: true,
    });
  });

  return Array.from(targets.values());
}

export type ReviewedBillMonthSettlement = {
  status: "partial" | "settled";
  actualAmount: number;
  /** Lender-required amount captured when the occurrence was reviewed. */
  requiredAmount: number;
  /** Number of distinct reviewed occurrences represented by this month. */
  occurrenceCount: number;
};

export type ReviewedBillOccurrenceSettlement = {
  billId: string;
  occurrenceDate: string;
  status: "partial" | "settled";
  actualAmount: number;
  requiredAmount: number;
};

/**
 * Preserves the decision made for each due date. Monthly totals alone cannot
 * describe a weekly bill whose first occurrence closed at a lower confirmed
 * amount while later occurrences still use the current lender minimum.
 */
export function reviewedBillOccurrenceSettlements(
  transactions: ReviewTransactionLike[],
): Map<string, ReviewedBillOccurrenceSettlement> {
  const occurrences = new Map<string, {
    billId: string;
    occurrenceDate: string;
    actualAmount: number;
    plannedAmount: number;
    explicitlyClosed: boolean;
  }>();

  transactions.forEach(transaction => {
    if (transaction.review_status !== "matched") return;
    (transaction.review_allocations ?? []).forEach(allocation => {
      if (allocation.type !== "bill" || !allocation.targetId || !allocation.occurrenceDate) return;
      const occurrenceDate = allocation.occurrenceDate.slice(0, 10);
      const key = occurrenceKey(allocation.targetId, occurrenceDate);
      const existing = occurrences.get(key);
      occurrences.set(key, {
        billId: allocation.targetId,
        occurrenceDate,
        actualAmount: Math.round(((existing?.actualAmount ?? 0) + Math.max(0, Number(allocation.amount) || 0)) * 100) / 100,
        plannedAmount: Math.max(
          existing?.plannedAmount ?? 0,
          Math.max(0, Number(allocation.plannedAmount ?? allocation.amount) || 0),
        ),
        explicitlyClosed: Boolean(existing?.explicitlyClosed
          || allocation.settlement === "exact"
          || allocation.settlement === "full"),
      });
    });
  });

  return new Map(Array.from(occurrences, ([key, occurrence]) => {
    const requiredAmount = occurrence.explicitlyClosed
      ? occurrence.actualAmount
      : Math.max(occurrence.actualAmount, occurrence.plannedAmount);
    return [key, {
      billId: occurrence.billId,
      occurrenceDate: occurrence.occurrenceDate,
      status: occurrence.explicitlyClosed || occurrence.actualAmount + 0.005 >= requiredAmount
        ? "settled" as const
        : "partial" as const,
      actualAmount: occurrence.actualAmount,
      requiredAmount: Math.round(requiredAmount * 100) / 100,
    }];
  }));
}

export function reviewedBillMonthSettlements(
  transactions: ReviewTransactionLike[],
): Map<string, ReviewedBillMonthSettlement> {
  return reviewedBillMonthSettlementsFromOccurrences(
    reviewedBillOccurrenceSettlements(transactions),
  );
}

export function reviewedBillMonthSettlementsFromOccurrences(
  occurrences: ReadonlyMap<string, ReviewedBillOccurrenceSettlement>,
): Map<string, ReviewedBillMonthSettlement> {
  const settlements = new Map<string, ReviewedBillMonthSettlement>();
  occurrences.forEach(occurrence => {
    const key = `${occurrence.billId}:${occurrence.occurrenceDate.slice(0, 7)}`;
    const existing = settlements.get(key);
    settlements.set(key, {
      status: existing?.status === "partial" || occurrence.status === "partial" ? "partial" : "settled",
      actualAmount: Math.round(((existing?.actualAmount ?? 0) + occurrence.actualAmount) * 100) / 100,
      requiredAmount: Math.round(((existing?.requiredAmount ?? 0) + occurrence.requiredAmount) * 100) / 100,
      occurrenceCount: (existing?.occurrenceCount ?? 0) + 1,
    });
  });

  return settlements;
}

export function reviewedBillMonthSettlement(
  transactions: ReviewTransactionLike[],
  billId: string,
  monthPrefix: string,
): { status: "none" | ReviewedBillMonthSettlement["status"]; actualAmount: number } {
  return reviewedBillMonthSettlements(transactions).get(`${billId}:${monthPrefix}`)
    ?? { status: "none", actualAmount: 0 };
}

export function allocationLabel(transaction: ReviewTransactionLike): string | null {
  if (transaction.user_edited_at && transaction.note.trim()) return transaction.note.trim();
  const allocations = transaction.review_allocations ?? [];
  if (allocations.length === 0) return null;
  return allocations.map(allocation => {
    const label = allocation.name || allocation.category || (allocation.type === "transfer" ? "Transfer" : "Reviewed");
    return allocations.length > 1 ? `${label} $${allocation.amount.toFixed(2)}` : label;
  }).join(" + ");
}

export type TransactionDisplayNameInput = Pick<ReviewTransactionLike, "note" | "category" | "merchant_name" | "user_edited_at" | "match_reason" | "review_resolution" | "review_allocations">;

export function transactionDisplayName(transaction: TransactionDisplayNameInput, plannedLabel?: string): string {
  const note = transaction.note.trim();
  if (transaction.user_edited_at && note) return note;
  if (plannedLabel) return plannedLabel;
  if (transaction.match_reason === "confirmed_bucket_replacement" && note) return note;
  if (transaction.review_resolution === "manual" || transaction.match_reason === "confirmed_manual_match" || transaction.match_reason === "confirmed_manual_transaction_match") {
    // An explicitly matched manual transaction retains its saved name in its
    // transaction allocation. Goal allocation names identify the whole bucket.
    const savedName = transaction.review_allocations?.find(allocation => allocation?.type === "planned_expense" && allocation.source === "transaction" && typeof allocation.name === "string" && allocation.name.trim())?.name?.trim();
    if (savedName) return savedName;
  }
  return transaction.merchant_name?.trim() || note || transaction.category || "Transaction";
}

export function transactionCategoryParts(transaction: ReviewTransactionLike): { category: string; amount: number; label: string }[] {
  if (transaction.amount >= 0 || transaction.review_status === "transfer" || transaction.review_status === "needs_review") return [];
  if (transaction.user_edited_at && transaction.review_resolution === "category") {
    const category = transaction.category || "Other";
    return [{ category, amount: transaction.amount, label: transaction.note.trim() || category }];
  }
  const allocations = transaction.review_allocations ?? [];
  if (allocations.length === 0) {
    return [{ category: transaction.category || "Other", amount: transaction.amount, label: transaction.note || transaction.category || "Transaction" }];
  }
  return allocations.flatMap(allocation => {
    if (allocation.type === "income" || allocation.type === "transfer") return [];
    const category = allocation.type === "extra_principal" ? "Debt" : allocation.category || transaction.category || "Other";
    return [{ category, amount: -Math.abs(allocation.amount), label: allocation.name || allocation.category || transaction.note || category }];
  });
}

export function reviewAllocationsAreBalanced(transaction: Pick<ReviewTransactionLike, "amount" | "review_allocations">): boolean {
  return Math.abs(allocationTotal(transaction.review_allocations) - Math.abs(transaction.amount)) < 0.005;
}

export interface BillOccurrenceMatchLike {
  amount?: number;
  plannedAmount?: number;
  settlement?: string;
}
export interface BillOccurrencePaymentInput {
  occurrenceDate: string;
  scheduledAmount: number;
  frequency: string;
  match?: BillOccurrenceMatchLike;
  monthlyPaidAmount?: number;
  monthlyPaidDate?: string;
}

export interface BillOccurrencePaymentView {
  scheduledAmount: number;
  paidAmount: number;
  remainingAmount: number;
  isPaid: boolean;
  isPartial: boolean;
}

function currency(value: number | undefined): number {
  const safe = Math.max(0, Number(value) || 0);
  return Math.round((safe + Number.EPSILON) * 100) / 100;
}

/** Resolve one bill occurrence without leaking a month paid total to every date. */
export function resolveBillOccurrencePayment(input: BillOccurrencePaymentInput): BillOccurrencePaymentView {
  const matchedPaid = currency(input.match?.amount);
  const hasExactMatch = Boolean(input.match);
  const matchClosesOccurrence = input.match?.settlement === "exact" || input.match?.settlement === "full";
  const reviewedPlanned = currency(input.match?.plannedAmount);
  const scheduledAmount = matchClosesOccurrence
    ? matchedPaid
    : input.match?.settlement === "partial" && reviewedPlanned > 0.005
      ? reviewedPlanned
      : currency(input.scheduledAmount);
  const isMultiOccurrence = input.frequency === "weekly" || input.frequency === "biweekly";
  const legacyPaid = !hasExactMatch && input.monthlyPaidDate === input.occurrenceDate
    ? currency(input.monthlyPaidAmount)
    : 0;
  // Legacy weekly/biweekly overrides may contain a whole-month total. They can
  // settle their dated occurrence, but must not overstate or spill to another.
  const paidAmount = hasExactMatch
    ? matchedPaid
    : isMultiOccurrence
      ? Math.min(scheduledAmount, legacyPaid)
      : legacyPaid;
  const remainingAmount = currency(Math.max(0, scheduledAmount - paidAmount));
  const isPaid = scheduledAmount > 0.005 && paidAmount >= scheduledAmount - 0.005;

  return {
    scheduledAmount,
    paidAmount,
    remainingAmount,
    isPaid,
    isPartial: paidAmount > 0.005 && !isPaid,
  };
}

export interface SpendingBucketAmounts {
  target_amount: number;
  current_amount: number;
  closed_at?: string | null;
}

export interface SpendingBucketSummary {
  planned: number;
  spent: number;
  remaining: number;
  released: number;
  closed: boolean;
}

export interface SpendingBucketMatch {
  settlement: "exact" | "partial" | "split";
  applied: number;
  extra: number;
}

export interface SpendingBucketCandidate extends SpendingBucketAmounts {
  goal_type: "savings" | "planned_expense";
  archived_at?: string | null;
}

export interface CreateSpendingBucketMatchInput {
  name: string;
  targetAmount: number;
  targetDate: string;
  transactionAmount: number;
}

export interface ValidSpendingBucketMatch {
  name: string;
  targetAmount: number;
  targetDate: string;
  transactionAmount: number;
  settlement: "exact" | "partial";
}

export function spendingBucketSummary(bucket: SpendingBucketAmounts): SpendingBucketSummary {
  const planned = Math.max(0, Number(bucket.target_amount) || 0);
  const spent = Math.max(0, Number(bucket.current_amount) || 0);
  const unused = Math.max(0, planned - spent);
  const closed = Boolean(bucket.closed_at);
  return {
    planned,
    spent,
    remaining: closed ? 0 : unused,
    released: closed ? unused : 0,
    closed,
  };
}

export function isOpenSpendingBucket(bucket: SpendingBucketAmounts): boolean {
  const summary = spendingBucketSummary(bucket);
  return !summary.closed && summary.remaining > 0.005;
}

export function isEligibleSpendingBucketMatch(bucket: SpendingBucketCandidate): boolean {
  return bucket.goal_type === "planned_expense" && !bucket.archived_at && isOpenSpendingBucket(bucket);
}

export function bucketEffectiveRouteDate(today: string, targetDate: string): string {
  const normalizedToday = today.slice(0, 10);
  const normalizedTarget = targetDate.slice(0, 10);
  if (!validIsoDate(normalizedToday)) throw new Error("Choose a valid current date.");
  if (!validIsoDate(normalizedTarget)) throw new Error("Choose a valid bucket target date.");
  return normalizedTarget > normalizedToday ? normalizedTarget : normalizedToday;
}

export function spendingBucketMatch(expenseAmount: number, remainingAmount: number): SpendingBucketMatch {
  const expense = Math.round(Math.max(0, Math.abs(Number(expenseAmount) || 0)) * 100) / 100;
  const remaining = Math.round(Math.max(0, Number(remainingAmount) || 0) * 100) / 100;
  if (Math.abs(expense - remaining) < 0.005) {
    return { settlement: "exact", applied: expense, extra: 0 };
  }
  if (expense < remaining) {
    return { settlement: "partial", applied: expense, extra: 0 };
  }
  return {
    settlement: "split",
    applied: remaining,
    extra: Math.round(Math.max(0, expense - remaining) * 100) / 100,
  };
}

function validIsoDate(value: string): boolean {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) return false;
  const [year, month, day] = value.split("-").map(Number);
  const date = new Date(Date.UTC(year, month - 1, day));
  return date.getUTCFullYear() === year
    && date.getUTCMonth() === month - 1
    && date.getUTCDate() === day;
}

export function validateCreateSpendingBucketMatch(
  input: CreateSpendingBucketMatchInput,
): ValidSpendingBucketMatch {
  const name = input.name.trim();
  if (!name) throw new Error("Enter a name for this spending bucket.");
  if (name.length > 120) throw new Error("Keep the spending bucket name to 120 characters or fewer.");
  if (!validIsoDate(input.targetDate)) throw new Error("Choose a valid target date.");

  const transactionAmount = Math.round(Math.abs(Number(input.transactionAmount)) * 100) / 100;
  const targetAmount = Math.round(Number(input.targetAmount) * 100) / 100;
  if (!Number.isFinite(transactionAmount) || transactionAmount <= 0) {
    throw new Error("This transaction does not have a valid money-out amount.");
  }
  if (!Number.isFinite(targetAmount) || targetAmount <= 0) {
    throw new Error("Enter a positive spending bucket amount.");
  }
  if (targetAmount + 0.005 < transactionAmount) {
    throw new Error(`Bucket amount must be at least $${transactionAmount.toFixed(2)} to include this transaction.`);
  }

  return {
    name,
    targetAmount,
    targetDate: input.targetDate,
    transactionAmount,
    settlement: Math.abs(targetAmount - transactionAmount) < 0.005 ? "exact" : "partial",
  };
}

/** A navigation request can open choices only for a live bucket in this exact loaded scope. */
export function requestedBucketCloseGoal<T extends SpendingBucketCandidate & { id: string }>(input: {
  bucketId?: string;
  requestedScope?: string;
  currentScope: string;
  ready: boolean;
  canEdit: boolean;
  goals: readonly T[];
}): T | null {
  if (!input.ready || !input.canEdit || !input.bucketId || input.requestedScope !== input.currentScope) return null;
  return input.goals.find(goal => goal.id === input.bucketId && goal.goal_type === "planned_expense" && !goal.closed_at && !goal.archived_at) ?? null;
}

export const CLOSED_DEBT_BALANCE_THRESHOLD = 0.009;

/** Closed debts stay available for history, but must not create future obligations. */
export function isBillEligibleForUpcomingPlan(
  bill: { is_debt: boolean; balance?: number | null },
) {
  return !bill.is_debt || Number(bill.balance ?? 0) > CLOSED_DEBT_BALANCE_THRESHOLD;
}

/** Past months keep their history; current and future planning omit closed debts. */
export function isBillVisibleForPlanningMonth(
  bill: { is_debt: boolean; balance?: number | null },
  month: number,
  year: number,
  currentMonth: number,
  currentYear: number,
) {
  const viewedMonth = year * 12 + month;
  const currentMonthIndex = currentYear * 12 + currentMonth;
  return viewedMonth < currentMonthIndex || isBillEligibleForUpcomingPlan(bill);
}

import {
  classifyCheckingLedgerTransaction,
  createPlaidTransactionAccountKindClassifier,
} from "./billMatching.ts";

export interface LedgerAllocationLike {
  amount?: number | null;
  plannedAmount?: number | null;
  settlement?: string | null;
}

export interface LedgerTransactionLike {
  id: string;
  date: string;
  amount: number;
  source?: string | null;
  import_hash?: string | null;
  plaid_transaction_id?: string | null;
  plaid_account_id?: string | null;
  removed_at?: string | null;
  deleted_at?: string | null;
  pending?: boolean | null;
  review_status?: string | null;
  review_allocations?: LedgerAllocationLike[] | null;
}

export interface LedgerConnectedAccountLike {
  id?: string | null;
  plaid_account_id?: string | null;
  account_type?: string | null;
  account_subtype?: string | null;
  is_active?: boolean | null;
}

export interface LedgerIssue {
  code: "duplicate_transaction_id" | "duplicate_plaid_transaction_id" | "allocation_mismatch" | "unknown_plaid_account";
  transactionId: string;
  detail: string;
}

export interface TransactionLedgerSnapshot<T extends LedgerTransactionLike> {
  /** Posted checking activity that changes cash, including hidden posted bank history. */
  cashTransactions: T[];
  /** Active rows that may be shown in Activity and calendar detail. */
  visibleTransactions: T[];
  /** Active checking rows used by day cards and activity summaries. */
  visibleCheckingTransactions: T[];
  cashTransactionsByMonth: ReadonlyMap<string, T[]>;
  visibleCheckingTransactionsByDate: ReadonlyMap<string, T[]>;
  cashByDate: ReadonlyMap<string, number>;
  issues: LedgerIssue[];
}

const CENT_TOLERANCE = 0.005;

export interface AccountAwareTransactionSelection<T> {
  included: T[];
  excludedNonCash: T[];
  unknownPlaid: T[];
}

/** Shared Activity/Review selector. Plaid rows appear only when their retained
 * account identity is checking; non-Plaid imports keep their existing behavior. */
export function selectFlowLedgerTransactions<T extends LedgerTransactionLike>(
  transactions: readonly T[],
  connectedAccounts: readonly LedgerConnectedAccountLike[],
): AccountAwareTransactionSelection<T> {
  const classifyAccountKind = createPlaidTransactionAccountKindClassifier(
    connectedAccounts,
  );
  return transactions.reduce<AccountAwareTransactionSelection<T>>((result, transaction) => {
    const kind = classifyAccountKind(transaction);
    if (kind === "checking" || kind === "not_plaid") result.included.push(transaction);
    else if (kind === "unknown") result.unknownPlaid.push(transaction);
    else result.excludedNonCash.push(transaction);
    return result;
  }, { included: [], excludedNonCash: [], unknownPlaid: [] });
}

function allocationTotal(transaction: LedgerTransactionLike): number {
  return (transaction.review_allocations ?? []).reduce(
    (sum, allocation) => sum + Math.abs(Number(allocation.amount) || 0),
    0,
  );
}

/**
 * Creates the one authoritative transaction view used by forecasts and summaries.
 *
 * The same row can be hidden from the UI and still remain in cash history when it
 * is a posted bank transaction. Pending and removed bank rows never change cash.
 */
export function buildTransactionLedger<T extends LedgerTransactionLike>(
  allTransactions: readonly T[],
  visibleTransactions: readonly T[],
  connectedAccounts: readonly LedgerConnectedAccountLike[],
  options?: { suppressedTransactionIds?: ReadonlySet<string> },
): TransactionLedgerSnapshot<T> {
  const issues: LedgerIssue[] = [];
  const uniqueById = new Map<string, T>();
  const plaidIds = new Map<string, string>();

  allTransactions.forEach(transaction => {
    if (uniqueById.has(transaction.id)) {
      issues.push({
        code: "duplicate_transaction_id",
        transactionId: transaction.id,
        detail: "The same transaction row appeared more than once.",
      });
      return;
    }
    uniqueById.set(transaction.id, transaction);

    if (transaction.plaid_transaction_id && !transaction.removed_at && transaction.pending !== true) {
      const first = plaidIds.get(transaction.plaid_transaction_id);
      if (first) {
        issues.push({
          code: "duplicate_plaid_transaction_id",
          transactionId: transaction.id,
          detail: `Posted bank ID also appears on ${first}.`,
        });
      } else {
        plaidIds.set(transaction.plaid_transaction_id, transaction.id);
      }
    }

    const allocations = transaction.review_allocations ?? [];
    if (
      allocations.length > 0
      && transaction.review_status !== "needs_review"
      && Math.abs(allocationTotal(transaction) - Math.abs(Number(transaction.amount) || 0)) >= CENT_TOLERANCE
    ) {
      issues.push({
        code: "allocation_mismatch",
        transactionId: transaction.id,
        detail: "Review allocations do not equal the bank transaction amount.",
      });
    }
  });

  const visibleIds = new Set<string>();
  visibleTransactions.forEach(transaction => visibleIds.add(transaction.id));
  const classifyAccountKind = createPlaidTransactionAccountKindClassifier(
    connectedAccounts,
  );
  const cashTransactions: T[] = [];
  const visible: T[] = [];
  const visibleChecking: T[] = [];
  const cashTransactionsByMonth = new Map<string, T[]>();
  const visibleCheckingTransactionsByDate = new Map<string, T[]>();
  const cashByDate = new Map<string, number>();
  const pushIndexed = (
    index: Map<string, T[]>,
    key: string,
    transaction: T,
  ) => {
    const bucket = index.get(key);
    if (bucket) bucket.push(transaction);
    else index.set(key, [transaction]);
  };
  uniqueById.forEach(transaction => {
    // Callers may consolidate an explicitly linked provisional replacement.
    // Keep the original rows outside this view for review and settlement facts.
    if (options?.suppressedTransactionIds?.has(transaction.id)) return;
    const classification = classifyCheckingLedgerTransaction(
      transaction,
      connectedAccounts,
      classifyAccountKind(transaction),
    );
    if (classification.accountKind === "unknown") {
      issues.push({
        code: "unknown_plaid_account",
        transactionId: transaction.id,
        detail: "Plaid transaction account identity is unavailable; cash impact was excluded.",
      });
    }
    if (classification.checkingForecast) {
      cashTransactions.push(transaction);
      pushIndexed(
        cashTransactionsByMonth,
        transaction.date.slice(0, 7),
        transaction,
      );
      cashByDate.set(
        transaction.date,
        (cashByDate.get(transaction.date) ?? 0) + Number(transaction.amount || 0),
      );
    }
    const included = classification.accountKind === "checking"
      || classification.accountKind === "not_plaid";
    if (!included || !classification.active || !visibleIds.has(transaction.id)) return;
    visible.push(transaction);
    if (classification.checkingBalance) {
      visibleChecking.push(transaction);
      pushIndexed(
        visibleCheckingTransactionsByDate,
        transaction.date.slice(0, 10),
        transaction,
      );
    }
  });

  return {
    cashTransactions,
    visibleTransactions: visible,
    visibleCheckingTransactions: visibleChecking,
    cashTransactionsByMonth,
    visibleCheckingTransactionsByDate,
    cashByDate,
    issues,
  };
}

/**
 * A settled full/exact match replaces its plan. A partial match leaves only the
 * unpaid part. This helper keeps bills, income, and snowball plans consistent.
 */
export function remainingPlannedAmount(
  plannedAmount: number,
  match?: LedgerAllocationLike | null,
): number {
  const planned = Math.max(0, Number(match?.plannedAmount ?? plannedAmount) || 0);
  if (!match) return planned;
  if (match.settlement !== "partial") return 0;
  return Math.max(0, planned - Math.abs(Number(match.amount) || 0));
}

import type { PendingPlanMatch } from "./pendingPlanMatches.ts";
import { isBucketLinkedManualPurchase } from "./bucketPurchases.ts";
export interface BillMatchTransaction {
  date: string;
  amount: number;
  description: string;
  category?: string;
}

export interface BillMatchCandidate {
  billId: string;
  name: string;
  category: string;
  plannedAmount: number;
  occurrenceDates: string[];
}

export interface ManualActivityMatchCandidate {
  id: string;
  date: string;
  amount: number;
  category: string;
  note?: string | null;
  source?: string | null;
  import_hash?: string | null;
  transfer_group_id?: string | null;
  pending?: boolean | null;
  removed_at?: string | null;
  deleted_at?: string | null;
  linked_bill_id?: string | null;
  debt_applied_bill_id?: string | null;
  debt_applied_amount?: number | null;
  linked_plan_id?: string | null;
  review_status?: string | null;
  linked_plan_type?: string | null;
  review_resolution?: string | null;
  review_allocations?: { type?: string | null; source?: string | null; targetId?: string | null; amount?: number | null }[] | null;
}

/**
 * Manual Activity can be replaced by the matching posted Plaid row. A debt
 * application is intentionally allowed: reconciliation transfers that audit
 * link to the bank-backed row without applying the balance change twice.
 */
export function manualActivityMatchCandidates(
  transactions: ManualActivityMatchCandidate[],
  transactionDate: string,
  excludedTransactionId?: string,
  bills: readonly { id: string; is_debt?: boolean | null }[] = [],
  includeBucketPurchases = false,
  pendingMatches: readonly PendingPlanMatch[] = [],
): BillMatchCandidate[] {
  const monthPrefix = transactionDate.slice(0, 7);
  const explicitManualIds = new Set(pendingMatches.filter(match => match.status === "ready_review" && match.target_type === "manual" && match.posted_transaction_id === excludedTransactionId).map(match => match.target_id));
  const debtIds = new Set(bills.filter(bill => bill.is_debt).map(bill => bill.id));
  return transactions
    .filter(transaction =>
      transaction.id !== excludedTransactionId
      && transaction.source !== "plaid"
      && !transaction.import_hash
      && !transaction.transfer_group_id
      && transaction.amount < 0
      && (transaction.date.startsWith(monthPrefix) || (includeBucketPurchases && explicitManualIds.has(transaction.id) && isBucketLinkedManualPurchase(transaction)))
      && transaction.pending !== true
      && !transaction.removed_at
      && !transaction.deleted_at
      && (!transaction.linked_bill_id || ((transaction.source == null || transaction.source === "manual") && debtIds.has(transaction.linked_bill_id)))
      && ((!transaction.linked_plan_id && transaction.review_status !== "matched")
        || (includeBucketPurchases && isBucketLinkedManualPurchase(transaction)))
      && transaction.category !== "Transfer")
    .map(transaction => ({
      billId: transaction.id,
      name: transaction.note?.trim() || transaction.category || "Manual activity",
      category: transaction.category,
      plannedAmount: Math.abs(transaction.amount),
      occurrenceDates: [transaction.date],
    }));
}

export interface RankedBillMatch extends BillMatchCandidate {
  score: number;
  confidence: "strong" | "likely" | "possible";
  amountDifference: number;
  daysApart: number | null;
  nearestOccurrenceDate: string | null;
  reasons: string[];
}

const DAY_MS = 24 * 60 * 60 * 1000;

function dateToUtcDay(value: string): number | null {
  const [year, month, day] = value.split("-").map(Number);
  if (!year || !month || !day) return null;
  return Date.UTC(year, month - 1, day) / DAY_MS;
}

function tokens(value: string): string[] {
  return value
    .toLowerCase()
    .replace(/[^a-z0-9\s]/g, " ")
    .split(/\s+/)
    .filter(token => token.length >= 3 && !["payment", "purchase", "debit", "online"].includes(token));
}

function nearestOccurrence(transactionDate: string, occurrenceDates: string[]): { date: string; distance: number } | null {
  const txDay = dateToUtcDay(transactionDate);
  if (txDay === null || occurrenceDates.length === 0) return null;
  return occurrenceDates.reduce<{ date: string; distance: number } | null>((nearest, date) => {
    const candidateDay = dateToUtcDay(date);
    if (candidateDay === null) return nearest;
    const distance = Math.abs(candidateDay - txDay);
    return nearest === null || distance < nearest.distance ? { date, distance } : nearest;
  }, null);
}

export function rankBillMatches(
  transaction: BillMatchTransaction,
  candidates: BillMatchCandidate[],
): RankedBillMatch[] {
  const actualAmount = Math.abs(Number(transaction.amount) || 0);
  const descriptionTokens = new Set(tokens(transaction.description));

  return candidates
    .filter(candidate => candidate.plannedAmount > 0 && candidate.occurrenceDates.length > 0)
    .map(candidate => {
      const plannedAmount = Math.abs(candidate.plannedAmount);
      const amountDifference = Math.abs(actualAmount - plannedAmount);
      const amountRatio = plannedAmount > 0 ? amountDifference / plannedAmount : 1;
      const nearest = nearestOccurrence(transaction.date, candidate.occurrenceDates);
      const daysApart = nearest?.distance ?? null;
      const nameTokens = tokens(candidate.name);
      const tokenMatches = nameTokens.filter(token => descriptionTokens.has(token)).length;
      const reasons: string[] = [];
      let score = 0;

      if (amountDifference <= 0.01) {
        score += 55;
        reasons.push("exact amount");
      } else if (amountRatio <= 0.03 || amountDifference <= 2) {
        score += 45;
        reasons.push("very close amount");
      } else if (amountRatio <= 0.1 || amountDifference <= 10) {
        score += 28;
        reasons.push("close amount");
      } else if (amountRatio <= 0.25) {
        score += 10;
      }

      if (daysApart !== null) {
        if (daysApart <= 2) {
          score += 25;
          reasons.push("near the due date");
        } else if (daysApart <= 7) {
          score += 18;
          reasons.push("within a week of the due date");
        } else if (daysApart <= 14) {
          score += 8;
        }
      }

      if (tokenMatches > 0) {
        score += Math.min(20, tokenMatches * 12);
        reasons.push("merchant name looks similar");
      }
      if (transaction.category && transaction.category === candidate.category) {
        score += 8;
        reasons.push("same category");
      }

      const boundedScore = Math.min(100, score);
      return {
        ...candidate,
        score: boundedScore,
        confidence: boundedScore >= 70 ? "strong" as const : boundedScore >= 48 ? "likely" as const : "possible" as const,
        amountDifference,
        daysApart,
        nearestOccurrenceDate: nearest?.date ?? null,
        reasons,
      };
    })
    .sort((left, right) =>
      right.score - left.score
      || left.amountDifference - right.amountDifference
      || (left.daysApart ?? Number.MAX_SAFE_INTEGER) - (right.daysApart ?? Number.MAX_SAFE_INTEGER)
      || left.name.localeCompare(right.name),
    );
}

interface ConfirmedBillMatchLike {
  linked_bill_id?: string | null;
  match_reason?: string | null;
  review_status?: string | null;
  review_resolution?: string | null;
  matched_occurrence_date?: string | null;
  review_allocations?: Array<{
    type?: string | null;
    targetId?: string | null;
    occurrenceDate?: string | null;
  }>;
}

export function confirmedBillMatchId(transaction: ConfirmedBillMatchLike): string | null {
  if (transaction.match_reason !== "confirmed_bill_match") return null;
  if (transaction.linked_bill_id) return transaction.linked_bill_id;
  if (transaction.review_status !== "matched" || transaction.review_resolution !== "bill") return null;
  return transaction.review_allocations?.find(allocation => allocation.type === "bill" && allocation.targetId)?.targetId ?? null;
}

export function confirmedBillMatchOccurrenceDate(transaction: ConfirmedBillMatchLike): string | null {
  if (!confirmedBillMatchId(transaction)) return null;
  return transaction.matched_occurrence_date
    ?? transaction.review_allocations?.find(allocation => allocation.type === "bill")?.occurrenceDate
    ?? null;
}

export function isConfirmedBillMatch(transaction: ConfirmedBillMatchLike): boolean {
  return confirmedBillMatchId(transaction) !== null;
}

export function canMatchExpenseToBill(transaction: {
  amount: number;
  source?: string | null;
  import_hash?: string | null;
  transfer_group_id?: string | null;
  linked_bill_id?: string | null;
  debt_applied_bill_id?: string | null;
  match_reason?: string | null;
}): boolean {
  if (!Number.isFinite(transaction.amount) || transaction.amount >= 0) return false;
  if (transaction.source === "plaid" || isConfirmedBillMatch(transaction)) return true;
  return !transaction.import_hash
    && !transaction.transfer_group_id
    && !transaction.linked_bill_id
    && !transaction.debt_applied_bill_id;
}

export function isMatchedPaymentLowerThanPlanned(transactionAmount: number, plannedAmount: number): boolean {
  if (!Number.isFinite(transactionAmount) || !Number.isFinite(plannedAmount) || plannedAmount <= 0) return false;
  return Math.abs(transactionAmount) + 0.005 < plannedAmount;
}

export function resolveMatchedBillBudget(plannedAmount: number, recurringBillAmount: number): number {
  const planned = Number.isFinite(plannedAmount) ? Math.max(0, plannedAmount) : 0;
  const recurring = Number.isFinite(recurringBillAmount) ? Math.max(0, recurringBillAmount) : 0;
  return Math.max(planned, recurring);
}

export function isActiveTransaction(transaction: {
  removed_at?: string | null;
  deleted_at?: string | null;
  pending?: boolean | null;
}): boolean {
  return !transaction.removed_at && !transaction.deleted_at && transaction.pending !== true;
}

export function isDeletedTransaction(transaction: {
  removed_at?: string | null;
  deleted_at?: string | null;
}): boolean {
  return Boolean(transaction.deleted_at) && !transaction.removed_at;
}

/**
 * Keep unresolved bank activity visible without letting it change money totals
 * before the matching plan item is known.
 */
export function isCashFlowTransaction(transaction: {
  removed_at?: string | null;
  deleted_at?: string | null;
  pending?: boolean | null;
  review_status?: string | null;
}): boolean {
  return isActiveTransaction(transaction)
    && transaction.review_status !== "needs_review"
    && transaction.review_status !== "transfer";
}

export interface ConnectedTransactionAccount {
  id?: string | null;
  plaid_account_id?: string | null;
  account_type?: string | null;
  account_subtype?: string | null;
  is_active?: boolean | null;
}

export interface CheckingLedgerTransaction {
  source?: string | null;
  import_hash?: string | null;
  plaid_account_id?: string | null;
  removed_at?: string | null;
  deleted_at?: string | null;
  pending?: boolean | null;
  review_status?: string | null;
}

function connectedTransactionAccount(
  transaction: CheckingLedgerTransaction,
  connectedAccounts: readonly ConnectedTransactionAccount[],
): ConnectedTransactionAccount | undefined {
  if (transaction.source !== "plaid" || !transaction.plaid_account_id) return undefined;
  return connectedAccounts.find(account =>
    account.plaid_account_id === transaction.plaid_account_id
    || account.id === transaction.plaid_account_id
  );
}

function isCheckingConnectedAccount(sourceAccount?: ConnectedTransactionAccount): boolean {
  if (!sourceAccount) return false;
  const type = String(sourceAccount.account_type || "").trim().toLowerCase();
  const subtype = String(sourceAccount.account_subtype || "").trim().toLowerCase();
  return type === "depository" && subtype === "checking";
}

export type PlaidTransactionAccountKind = "checking" | "non_cash" | "unknown" | "not_plaid";

export interface CheckingLedgerTransactionClassification {
  accountKind: PlaidTransactionAccountKind;
  active: boolean;
  checkingBalance: boolean;
  checkingForecast: boolean;
}

/**
 * Plaid rows are classified against every retained account identity, including
 * inactive/reconnected accounts. Unknown Plaid identities fail closed so card
 * or savings activity can never be assumed to be checking cash.
 */
export function plaidTransactionAccountKind(
  transaction: CheckingLedgerTransaction,
  connectedAccounts: readonly ConnectedTransactionAccount[],
): PlaidTransactionAccountKind {
  if (transaction.source !== "plaid") return "not_plaid";
  const sourceAccount = connectedTransactionAccount(transaction, connectedAccounts);
  if (!sourceAccount) return "unknown";
  return isCheckingConnectedAccount(sourceAccount) ? "checking" : "non_cash";
}

/** Build one immutable account-identity lookup for whole-ledger classification. */
export function createPlaidTransactionAccountKindClassifier(
  connectedAccounts: readonly ConnectedTransactionAccount[],
): (transaction: CheckingLedgerTransaction) => PlaidTransactionAccountKind {
  const kindByIdentity = new Map<string, PlaidTransactionAccountKind>();
  connectedAccounts.forEach(account => {
    const kind = isCheckingConnectedAccount(account) ? "checking" : "non_cash";
    [account.plaid_account_id, account.id].forEach(identity => {
      if (identity && !kindByIdentity.has(identity)) kindByIdentity.set(identity, kind);
    });
  });
  return transaction => {
    if (transaction.source !== "plaid") return "not_plaid";
    if (!transaction.plaid_account_id) return "unknown";
    return kindByIdentity.get(transaction.plaid_account_id) ?? "unknown";
  };
}

/** Compute the shared cash/visibility classification once for ledger builders. */
export function classifyCheckingLedgerTransaction(
  transaction: CheckingLedgerTransaction,
  connectedAccounts: readonly ConnectedTransactionAccount[],
  preparedAccountKind?: PlaidTransactionAccountKind,
): CheckingLedgerTransactionClassification {
  const accountKind = preparedAccountKind
    ?? plaidTransactionAccountKind(transaction, connectedAccounts);
  const active = isActiveTransaction(transaction);
  const checkingBalance = active && (
    transaction.source === "plaid"
      ? accountKind === "checking"
      : transaction.review_status !== "transfer"
  );
  const isPostedBankRow = (transaction.source === "plaid" || Boolean(transaction.import_hash))
    && !transaction.removed_at
    && transaction.pending !== true;
  const checkingForecast = checkingBalance || Boolean(
    transaction.deleted_at
    && isPostedBankRow
    && (
      transaction.source === "plaid"
        ? accountKind === "checking"
        : transaction.review_status !== "transfer"
    ),
  );
  return { accountKind, active, checkingBalance, checkingForecast };
}

/**
 * Posted bank activity changes the checking ledger before it is reviewed.
 * Review status controls categorization, never whether cash moved. Transfers
 * still count only on the checking side so account-to-account moves are not
 * doubled.
 */
export function isCheckingBalanceTransaction(
  transaction: CheckingLedgerTransaction,
  connectedAccounts: readonly ConnectedTransactionAccount[],
): boolean {
  return classifyCheckingLedgerTransaction(transaction, connectedAccounts)
    .checkingBalance;
}

/**
 * Hiding a posted bank row must not erase money that already moved.
 * Keep its cash impact in forecasts without restoring it to user-facing lists.
 */
export function isCheckingForecastLedgerTransaction(
  transaction: CheckingLedgerTransaction,
  connectedAccounts: readonly ConnectedTransactionAccount[],
): boolean {
  return classifyCheckingLedgerTransaction(transaction, connectedAccounts)
    .checkingForecast;
}

import type { Goal, ReviewAllocation, Transaction } from "./financialProjectionTypes.ts";

export type BucketPurchaseIntent = {
  bucketId: string;
  transactionId: string;
  transaction?: Pick<Transaction, "amount" | "date" | "category" | "note" | "account_id">;
};

type PurchaseLike = {
  amount: number; source?: string | null; import_hash?: string | null; transfer_group_id?: string | null;
  linked_bill_id?: string | null; linked_income_id?: string | null; linked_plan_id?: string | null; linked_plan_type?: string | null;
  debt_applied_bill_id?: string | null; debt_applied_amount?: number | null; review_status?: string | null; review_resolution?: string | null;
  review_allocations?: readonly { type?: string | null; source?: string | null; targetId?: string | null; amount?: number | null }[] | null;
};

export function bucketPurchaseAllocation(transaction: PurchaseLike, bucketId?: string): number {
  if (transaction.linked_plan_type !== "goal" || !transaction.linked_plan_id
    || (bucketId && transaction.linked_plan_id !== bucketId)) return 0;
  return Math.round((transaction.review_allocations ?? []).reduce((sum, allocation) =>
    allocation.type === "planned_expense" && allocation.targetId === transaction.linked_plan_id
      && (allocation.source == null || allocation.source === "goal")
      ? sum + Math.max(0, Number(allocation.amount) || 0) : sum, 0) * 100) / 100;
}

export function isBucketLinkedManualPurchase(transaction: PurchaseLike): boolean {
  return (transaction.source == null || transaction.source === "manual")
    && !transaction.import_hash && !transaction.transfer_group_id && !transaction.linked_bill_id
    && !transaction.linked_income_id && !transaction.debt_applied_bill_id
    && !(Math.abs(transaction.debt_applied_amount ?? 0) > 0.005)
    && transaction.review_status === "matched" && transaction.review_resolution === "goal"
    && transaction.amount < 0 && bucketPurchaseAllocation(transaction) > 0;
}

export function bucketPurchaseCandidates(transactions: readonly Transaction[], kind: "bank" | "manual", search = ""): Transaction[] {
  const query = search.trim().toLocaleLowerCase();
  return transactions.filter(transaction => {
    const bank = transaction.source === "plaid" || transaction.source === "statement";
    return (kind === "bank" ? bank : !bank && (transaction.source == null || transaction.source === "manual") && !transaction.import_hash)
      && Number.isFinite(transaction.amount) && transaction.amount < 0 && !transaction.pending
      && !transaction.removed_at && !transaction.deleted_at && !transaction.transfer_group_id
      && transaction.category !== "Transfer" && !transaction.linked_bill_id && !transaction.linked_income_id
      && !transaction.linked_plan_id && !transaction.debt_applied_bill_id
      && !(Math.abs(transaction.debt_applied_amount ?? 0) > 0.005)
      && transaction.review_status !== "matched" && transaction.review_status !== "transfer"
      && !transaction.review_allocations?.some(allocation => allocation.type !== "category")
      && (!query || `${transaction.merchant_name ?? ""} ${transaction.note} ${transaction.category} ${transaction.date} ${Math.abs(transaction.amount).toFixed(2)}`.toLocaleLowerCase().includes(query));
  }).slice().sort((left, right) => right.date.localeCompare(left.date) || left.id.localeCompare(right.id));
}

export function bucketPurchaseHistory(transactions: readonly Transaction[], bucketId: string) {
  return transactions.filter(transaction => !transaction.deleted_at && !transaction.removed_at && !transaction.pending)
    .map(transaction => ({ transaction, allocated: bucketPurchaseAllocation(transaction, bucketId) }))
    .filter(purchase => purchase.allocated > 0)
    .sort((left, right) => right.transaction.date.localeCompare(left.transaction.date) || left.transaction.id.localeCompare(right.transaction.id));
}

export function bucketPurchaseTransaction(transaction: Transaction, goal: Pick<Goal, "id">): Transaction {
  const allocation: ReviewAllocation = { type: "planned_expense", source: "goal", targetId: goal.id,
    amount: Math.abs(transaction.amount), occurrenceDate: transaction.date, settlement: "partial" };
  return { ...transaction, linked_plan_type: "goal", linked_plan_id: goal.id,
    review_status: "matched", review_resolution: "goal", review_allocations: [allocation],
    matched_occurrence_date: transaction.date, match_reason: "confirmed_bucket_purchase", match_confidence: 1 };
}

import type { DebtSourceCommitment } from "./debtPlanDomain.ts";

export type PendingPlanMatchStatus = "active" | "ready_review" | "completed" | "expired" | "cancelled";

export interface PendingPlanMatch {
  id: string;
  pending_plaid_transaction_id: string;
  pending_account_id?: string;
  target_type: "bill" | "manual";
  target_id: string;
  target_name: string;
  occurrence_date: string;
  planned_amount: number;
  pending_amount: number;
  pending_transaction_date: string;
  status: PendingPlanMatchStatus;
  posted_transaction_id?: string;
  posted_plaid_transaction_id?: string;
  posted_amount?: number;
  created_at: string;
  updated_at: string;
}

export interface PendingTransactionIdentity {
  plaid_transaction_id: string;
}

export interface PostedTransactionIdentity {
  id: string;
  plaid_transaction_id?: string;
  review_status?: string;
}

export interface DebtSourceIdentity {
  id: string;
  name?: string;
  balance: number;
  is_debt: boolean;
}

export function livePendingPlanMatchForOccurrence(
  matches: PendingPlanMatch[],
  pendingTransactions: PendingTransactionIdentity[],
  billId: string,
  occurrenceDate: string,
): PendingPlanMatch | undefined {
  const liveIds = new Set(pendingTransactions.map(transaction => transaction.plaid_transaction_id));
  return matches.find(match => match.status === "active"
    && match.target_type === "bill"
    && liveIds.has(match.pending_plaid_transaction_id)
    && match.target_id === billId
    && match.occurrence_date === occurrenceDate);
}

export function debtSourceCommitmentsFromPendingMatches(
  matches: PendingPlanMatch[],
  pendingTransactions: PendingTransactionIdentity[],
  postedTransactions: PostedTransactionIdentity[],
): DebtSourceCommitment[] {
  const livePendingIds = new Set(pendingTransactions.map(transaction => transaction.plaid_transaction_id));
  const postedIds = new Set(postedTransactions
    // A posted pending match protects the dated obligation only while the
    // replacement charge is waiting for review. Once the transaction is
    // resolved, its review allocation is authoritative; retaining the old
    // commitment would suppress the remaining partial balance a second time.
    .filter(transaction => transaction.review_status === undefined || transaction.review_status === "needs_review")
    .flatMap(transaction => [
      transaction.id,
      ...(transaction.plaid_transaction_id ? [transaction.plaid_transaction_id] : []),
    ]));
  const candidates = matches.flatMap<DebtSourceCommitment>(match => {
    if (match.target_type !== "bill") return [];
    if (match.status === "active" && livePendingIds.has(match.pending_plaid_transaction_id)) {
      return [{ sourceBillId: match.target_id, sourceBillName: match.target_name, date: match.occurrence_date, amount: match.pending_amount, state: "pending" as const }];
    }
    if (match.status === "ready_review"
      && Boolean(match.posted_transaction_id || match.posted_plaid_transaction_id)
      && (Boolean(match.posted_transaction_id && postedIds.has(match.posted_transaction_id))
        || Boolean(match.posted_plaid_transaction_id && postedIds.has(match.posted_plaid_transaction_id)))) {
      return [{
        sourceBillId: match.target_id,
        sourceBillName: match.target_name,
        date: match.occurrence_date,
        // The posted transaction is already real cash even while it waits for
        // review. Keep its amount for payoff-extra consumption math; the
        // `posted` state still tells the projector to remove the source row.
        amount: Math.max(0, Number(match.posted_amount) || 0),
        state: "posted" as const,
      }];
    }
    return [];
  });
  const grouped = new Map<string, DebtSourceCommitment[]>();
  candidates.forEach(commitment => {
    const key = `${commitment.sourceBillId}:${commitment.date}`;
    grouped.set(key, [...(grouped.get(key) ?? []), commitment]);
  });
  return Array.from(grouped.values(), commitments => {
    const posted = commitments.filter(commitment => commitment.state === "posted");
    if (posted.length) return {
      ...posted[0]!,
      amount: Math.round(posted.reduce((sum, commitment) => sum + Math.max(0, Number(commitment.amount) || 0), 0) * 100) / 100,
      state: "posted" as const,
    };
    const first = commitments[0]!;
    return {
      ...first,
      amount: Math.round(commitments.reduce((sum, commitment) => sum + Math.max(0, Number(commitment.amount) || 0), 0) * 100) / 100,
      state: "pending" as const,
    };
  }).sort((left, right) => left.date.localeCompare(right.date) || left.sourceBillId.localeCompare(right.sourceBillId));
}

/** Keeps ordinary matched bills out of the canonical debt-payment projection. */
export function debtSourceCommitmentsForDebts(
  matches: PendingPlanMatch[],
  pendingTransactions: PendingTransactionIdentity[],
  postedTransactions: PostedTransactionIdentity[],
  sources: DebtSourceIdentity[],
): DebtSourceCommitment[] {
  const debtById = new Map(sources
    .filter(source => source.is_debt)
    .map(source => [source.id, source]));

  return debtSourceCommitmentsFromPendingMatches(matches, pendingTransactions, postedTransactions)
    .flatMap(commitment => {
      const source = debtById.get(commitment.sourceBillId);
      if (!source) return [];
      return [{
        ...commitment,
        sourceBillName: commitment.sourceBillName || source.name,
        sourceBalance: source.balance,
      }];
    });
}

export function debtSourceCommitmentForOccurrence(
  matches: PendingPlanMatch[],
  pendingTransactions: PendingTransactionIdentity[],
  postedTransactions: PostedTransactionIdentity[],
  billId: string,
  occurrenceDate: string,
): DebtSourceCommitment | undefined {
  return debtSourceCommitmentsFromPendingMatches(matches, pendingTransactions, postedTransactions)
    .find(commitment => commitment.sourceBillId === billId && commitment.date === occurrenceDate);
}

export function activePendingPlanMatches(
  matches: PendingPlanMatch[],
  pendingTransactions: PendingTransactionIdentity[],
): PendingPlanMatch[] {
  const livePendingIds = new Set(pendingTransactions.map(transaction => transaction.plaid_transaction_id));
  return matches.filter(match =>
    match.status === "ready_review"
    || (match.status === "active" && livePendingIds.has(match.pending_plaid_transaction_id)));
}

export function unmatchedPendingTransactions<T extends PendingTransactionIdentity>(
  matches: PendingPlanMatch[],
  pendingTransactions: T[],
): T[] {
  const matchedPendingIds = new Set(
    activePendingPlanMatches(matches, pendingTransactions)
      .map(match => match.pending_plaid_transaction_id),
  );
  return pendingTransactions.filter(
    transaction => !matchedPendingIds.has(transaction.plaid_transaction_id),
  );
}

export function pendingPlanMatchForOccurrence(
  matches: PendingPlanMatch[],
  pendingTransactions: PendingTransactionIdentity[],
  billId: string,
  occurrenceDate: string,
): PendingPlanMatch | undefined {
  return activePendingPlanMatches(matches, pendingTransactions)
    .find(match =>
      match.target_type === "bill"
      && match.target_id === billId
      && match.occurrence_date === occurrenceDate);
}

export function pendingOccurrenceDatesForBill(
  matches: PendingPlanMatch[],
  pendingTransactions: PendingTransactionIdentity[],
  billId: string,
): string[] {
  return activePendingPlanMatches(matches, pendingTransactions)
    .filter(match => match.target_type === "bill" && match.target_id === billId)
    .map(match => match.occurrence_date);
}

export function pendingOccurrenceKeySet(
  matches: PendingPlanMatch[],
  pendingTransactions: PendingTransactionIdentity[],
): Set<string> {
  return new Set(activePendingPlanMatches(matches, pendingTransactions)
    .filter(match => match.target_type === "bill")
    .map(match => `${match.target_id}:${match.occurrence_date}`));
}

export function pendingMatchStatusLabel(match: PendingPlanMatch): string {
  return match.status === "ready_review" ? "REVIEW PAYMENT" : "PAYMENT PENDING";
}

export function prioritizePendingPlanTarget<T extends {
  type: string;
  id: string;
  occurrenceDate: string;
  score: number;
  reasons: string[];
}>(
  targets: T[],
  postedTransactionId: string,
  matches: PendingPlanMatch[],
): T[] {
  const linked = matches.find(match =>
    match.status === "ready_review"
    && match.posted_transaction_id === postedTransactionId);
  if (!linked) return targets;

  return targets
    .map(target => target.type === linked.target_type
      && target.id === linked.target_id
      && target.occurrenceDate === linked.occurrence_date
      ? {
          ...target,
          score: Math.max(target.score, 100),
          reasons: ["Matched while pending", ...target.reasons.filter(reason => reason !== "Matched while pending")],
        }
      : target)
    .sort((left, right) => right.score - left.score);
}

import { isBucketLinkedManualPurchase } from "./bucketPurchases.ts";
import { createPlaidTransactionAccountKindClassifier, isActiveTransaction } from "./billMatching.ts";
import type { LedgerConnectedAccountLike, LedgerTransactionLike } from "./ledgerEngine.ts";
import type { PendingPlanMatch } from "./pendingPlanMatches.ts";

type Scope = { household_id?: string | null; budget_id?: string | null };
type ReplacementTransaction = LedgerTransactionLike & Scope & {
  category?: string;
  transfer_group_id?: string | null;
  linked_plan_id?: string | null;
  linked_bill_id?: string | null;
  linked_plan_type?: string | null;
  review_resolution?: string | null;
  review_allocations?: { type?: string | null; source?: string | null; targetId?: string | null; amount?: number | null }[] | null;
};

function sameAvailableScope(...rows: Scope[]): boolean {
  return (["household_id", "budget_id"] as const).every(key =>
    new Set(rows.map(row => row[key]).filter(Boolean)).size <= 1);
}

function validDate(value: string): boolean {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) return false;
  const [year, month, day] = value.split("-").map(Number);
  const date = new Date(Date.UTC(year, month - 1, day));
  return date.getUTCFullYear() === year && date.getUTCMonth() === month - 1 && date.getUTCDate() === day;
}

/** An explicit pending link can identify one cash event before review finishes.
 * This suppresses only its duplicate manual representation in forecast/calendar
 * views. Raw transactions and manual debt-settlement facts stay untouched. */
export function pendingManualReplacementIds<T extends ReplacementTransaction>(
  transactions: readonly T[], matches: readonly (PendingPlanMatch & Scope)[], accounts: readonly LedgerConnectedAccountLike[],
  bills: readonly { id: string; is_debt?: boolean | null }[] = [],
): ReadonlySet<string> {
  const readyMatches = matches.filter(match => match.status === "ready_review" && match.target_type === "manual");
  if (!readyMatches.length) return new Set();
  const byId = new Map<string, T | null>();
  const byPlaidId = new Map<string, T | null>();
  for (const transaction of transactions) {
    byId.set(transaction.id, byId.has(transaction.id) ? null : transaction);
    if (transaction.plaid_transaction_id) byPlaidId.set(transaction.plaid_transaction_id,
      byPlaidId.has(transaction.plaid_transaction_id) ? null : transaction);
  }
  const classifyAccount = createPlaidTransactionAccountKindClassifier(accounts);
  const debtIds = new Set(bills.filter(bill => bill.is_debt).map(bill => bill.id));
  const accountAliases = new Map<string, string | null>();
  for (const account of accounts) {
    const identity = account.plaid_account_id || account.id;
    if (!identity) continue;
    for (const alias of [account.id, account.plaid_account_id]) {
      if (!alias) continue;
      accountAliases.set(alias, accountAliases.has(alias) && accountAliases.get(alias) !== identity ? null : identity);
    }
  }
  const pairs: Array<{ manual: string; posted: string }> = [];
  const bankByManual = new Map<string, Set<string>>();
  const manualByBank = new Map<string, Set<string>>();
  for (const match of readyMatches) {
    const manual = byId.get(match.target_id);
    const byPostedId = match.posted_transaction_id ? byId.get(match.posted_transaction_id) : undefined;
    const byPostedPlaid = match.posted_plaid_transaction_id ? byPlaidId.get(match.posted_plaid_transaction_id) : undefined;
    if ((match.posted_transaction_id && !byPostedId) || (match.posted_plaid_transaction_id && !byPostedPlaid)) continue;
    if (byPostedId && byPostedPlaid && byPostedId.id !== byPostedPlaid.id) continue;
    const posted = byPostedId || byPostedPlaid;
    if (!manual || !posted || manual.id === posted.id) continue;
    if (posted.plaid_transaction_id && byPlaidId.get(posted.plaid_transaction_id) !== posted) continue;
    if (!isActiveTransaction(manual) || !isActiveTransaction(posted)) continue;
    if (!Number.isFinite(manual.amount) || manual.amount >= 0 || !Number.isFinite(posted.amount) || posted.amount >= 0) continue;
    if (!Number.isFinite(match.planned_amount) || match.planned_amount <= 0 || Math.abs(Math.abs(manual.amount) - match.planned_amount) > 0.005) continue;
    if (!Number.isFinite(match.pending_amount) || match.pending_amount <= 0) continue;
    if (!validDate(manual.date) || !validDate(posted.date) || !validDate(match.pending_transaction_date) || manual.date !== match.occurrence_date || manual.date.slice(0, 7) !== match.pending_transaction_date.slice(0, 7)) continue;
    if (manual.source === "plaid" || manual.import_hash || manual.transfer_group_id || ((!isBucketLinkedManualPurchase(manual)) && (manual.linked_plan_id || manual.review_status === "matched")) || manual.category === "Transfer" || manual.review_status === "transfer") continue;
    if (manual.linked_bill_id && ((manual.source != null && manual.source !== "manual") || !debtIds.has(manual.linked_bill_id))) continue;
    if (posted.source !== "plaid" || posted.review_status !== "needs_review" || classifyAccount(posted) !== "checking") continue;
    if (match.pending_account_id && match.pending_account_id !== posted.plaid_account_id) {
      const pendingAccount = accountAliases.get(match.pending_account_id);
      if (!pendingAccount || pendingAccount !== accountAliases.get(posted.plaid_account_id || "")) continue;
    }
    if (!sameAvailableScope(manual, posted, match)) continue;
    pairs.push({ manual: manual.id, posted: posted.id });
    const banks = bankByManual.get(manual.id) ?? new Set<string>(); banks.add(posted.id); bankByManual.set(manual.id, banks);
    const manuals = manualByBank.get(posted.id) ?? new Set<string>(); manuals.add(manual.id); manualByBank.set(posted.id, manuals);
  }
  return new Set(pairs.filter(pair => bankByManual.get(pair.manual)?.size === 1 && manualByBank.get(pair.posted)?.size === 1).map(pair => pair.manual));
}

import {
  occurrenceKey,
  resolvedMatchedIncomeAllocation,
  reviewedBillMonthSettlementsFromOccurrences,
  type ReviewAllocationLike,
  type ReviewIncomeLike,
  type ReviewTransactionLike,
  type ReviewedBillMonthSettlement,
  type ReviewedBillOccurrenceSettlement,
} from "./reviewCenter.ts";

export interface FinancialDateRecord {
  date: string;
}

export interface FinancialProjectionIndexes<
  TTransaction extends FinancialDateRecord,
  TForecastTransaction extends FinancialDateRecord,
  TVisibleTransaction extends FinancialDateRecord,
  TCommitment extends FinancialDateRecord,
> {
  transactionsByMonth: Map<string, TTransaction[]>;
  forecastTransactionsByMonth: Map<string, TForecastTransaction[]>;
  visibleTransactionsByDate: Map<string, TVisibleTransaction[]>;
  commitmentsByMonth: Map<string, TCommitment[]>;
}

function pushIndexed<K, T>(index: Map<K, T[]>, key: K, value: T) {
  const bucket = index.get(key);
  if (bucket) bucket.push(value);
  else index.set(key, [value]);
}

export function indexRecordsByMonth<T extends FinancialDateRecord>(
  records: readonly T[],
): Map<string, T[]> {
  const index = new Map<string, T[]>();
  records.forEach(record => pushIndexed(index, record.date.slice(0, 7), record));
  return index;
}

export function indexRecordsByDate<T extends FinancialDateRecord>(
  records: readonly T[],
): Map<string, T[]> {
  const index = new Map<string, T[]>();
  records.forEach(record => pushIndexed(index, record.date.slice(0, 10), record));
  return index;
}

export function buildFinancialProjectionIndexes<
  TTransaction extends FinancialDateRecord,
  TForecastTransaction extends FinancialDateRecord,
  TVisibleTransaction extends FinancialDateRecord,
  TCommitment extends FinancialDateRecord,
>(input: {
  transactions: readonly TTransaction[];
  forecastTransactions: readonly TForecastTransaction[];
  visibleTransactions: readonly TVisibleTransaction[];
  commitments: readonly TCommitment[];
}): FinancialProjectionIndexes<
  TTransaction,
  TForecastTransaction,
  TVisibleTransaction,
  TCommitment
> {
  return {
    transactionsByMonth: indexRecordsByMonth(input.transactions),
    forecastTransactionsByMonth: indexRecordsByMonth(input.forecastTransactions),
    visibleTransactionsByDate: indexRecordsByDate(input.visibleTransactions),
    commitmentsByMonth: indexRecordsByMonth(input.commitments),
  };
}

export interface MatchedFinancialAllocationIndexes {
  bill: Map<string, ReviewAllocationLike>;
  income: Map<string, ReviewAllocationLike>;
  snowball: Map<string, ReviewAllocationLike>;
  reviewedBillIdsByMonth: Map<string, Set<string>>;
  paidBillAmountByMonth: Map<string, number>;
  reviewedBillOccurrences: Map<string, ReviewedBillOccurrenceSettlement>;
  reviewedBillSettlements: Map<string, ReviewedBillMonthSettlement>;
}

/**
 * Builds every allocation lookup in one immutable-ledger pass while preserving
 * the canonical matchedOccurrenceAllocations merge and settlement semantics.
 */
export function buildMatchedFinancialAllocationIndexes(
  transactions: ReviewTransactionLike[],
  incomes: ReviewIncomeLike[] = [],
): MatchedFinancialAllocationIndexes {
  const bill = new Map<string, ReviewAllocationLike>();
  const income = new Map<string, ReviewAllocationLike>();
  const snowball = new Map<string, ReviewAllocationLike>();
  const incomesById = new Map(incomes.map(income => [income.id, income]));
  const reviewedBillIdsByMonth = new Map<string, Set<string>>();
  const paidBillAmountByMonth = new Map<string, number>();
  const reviewedOccurrenceAggregates = new Map<string, {
    billId: string;
    occurrenceDate: string;
    actualAmount: number;
    plannedAmount: number;
    explicitlyClosed: boolean;
  }>();

  const merge = (
    matches: Map<string, ReviewAllocationLike>,
    allocation: ReviewAllocationLike,
  ) => {
    if (!allocation.targetId || !allocation.occurrenceDate) return;
    const key = occurrenceKey(allocation.targetId, allocation.occurrenceDate);
    const existing = matches.get(key);
    const amount = Math.max(0, Number(allocation.amount) || 0);
    const planned = Math.max(
      amount,
      Number(allocation.plannedAmount ?? allocation.amount) || 0,
    );
    const allocationClosed = allocation.settlement === "exact"
      || allocation.settlement === "full";
    if (!existing) {
      matches.set(key, {
        ...allocation,
        amount,
        plannedAmount: allocationClosed ? amount : planned,
      });
      return;
    }
    const combinedAmount = Math.round(
      (Number(existing.amount || 0) + amount) * 100,
    ) / 100;
    const historicalPlanned = Math.max(
      Number(existing.plannedAmount || 0),
      planned,
    );
    const existingClosed = existing.settlement === "exact"
      || existing.settlement === "full";
    const explicitlyClosed = existingClosed || allocationClosed;
    matches.set(key, {
      ...allocation,
      amount: combinedAmount,
      plannedAmount: explicitlyClosed ? combinedAmount : historicalPlanned,
      settlement: explicitlyClosed
        ? (allocationClosed ? allocation.settlement : existing.settlement)
        : historicalPlanned > 0 && combinedAmount + 0.005 < historicalPlanned
          ? "partial"
          : allocation.settlement,
    });
  };

  transactions.forEach(transaction => {
    if (transaction.review_status !== "matched") return;
    (transaction.review_allocations ?? []).forEach(allocation => {
      if (allocation.type === "bill") {
        merge(bill, allocation);
        if (allocation.targetId && allocation.occurrenceDate) {
          const occurrenceDate = allocation.occurrenceDate.slice(0, 10);
          const key = occurrenceKey(allocation.targetId, occurrenceDate);
          const existing = reviewedOccurrenceAggregates.get(key);
          reviewedOccurrenceAggregates.set(key, {
            billId: allocation.targetId,
            occurrenceDate,
            actualAmount: Math.round((
              (existing?.actualAmount ?? 0)
              + Math.max(0, Number(allocation.amount) || 0)
            ) * 100) / 100,
            plannedAmount: Math.max(
              existing?.plannedAmount ?? 0,
              Math.max(
                0,
                Number(allocation.plannedAmount ?? allocation.amount) || 0,
              ),
            ),
            explicitlyClosed: Boolean(
              existing?.explicitlyClosed
              || allocation.settlement === "exact"
              || allocation.settlement === "full"
            ),
          });
        }
      }
      else if (allocation.type === "income") {
        merge(income, resolvedMatchedIncomeAllocation(allocation, transaction.date, incomesById));
      }
      else if (
        allocation.type === "extra_principal"
        && transaction.review_resolution === "snowball"
      ) merge(snowball, allocation);
    });
  });

  bill.forEach(match => {
    if (!match.targetId || !match.occurrenceDate) return;
    const monthPrefix = match.occurrenceDate.slice(0, 7);
    const ids = reviewedBillIdsByMonth.get(monthPrefix) ?? new Set<string>();
    ids.add(match.targetId);
    reviewedBillIdsByMonth.set(monthPrefix, ids);
    paidBillAmountByMonth.set(monthPrefix,
      (paidBillAmountByMonth.get(monthPrefix) ?? 0)
      + Math.max(0, Number(match.amount) || 0));
  });

  const reviewedBillOccurrences = new Map<string, ReviewedBillOccurrenceSettlement>();
  reviewedOccurrenceAggregates.forEach((occurrence, key) => {
    const requiredAmount = occurrence.explicitlyClosed
      ? occurrence.actualAmount
      : Math.max(occurrence.actualAmount, occurrence.plannedAmount);
    reviewedBillOccurrences.set(key, {
      billId: occurrence.billId,
      occurrenceDate: occurrence.occurrenceDate,
      status: occurrence.explicitlyClosed
        || occurrence.actualAmount + 0.005 >= requiredAmount
        ? "settled"
        : "partial",
      actualAmount: occurrence.actualAmount,
      requiredAmount: Math.round(requiredAmount * 100) / 100,
    });
  });
  const reviewedBillSettlements =
    reviewedBillMonthSettlementsFromOccurrences(reviewedBillOccurrences);

  return {
    bill,
    income,
    snowball,
    reviewedBillIdsByMonth,
    paidBillAmountByMonth,
    reviewedBillOccurrences,
    reviewedBillSettlements,
  };
}

/**
 * Read-through cache for one immutable input revision. The caller owns cache
 * replacement when source inputs change, so cache hits never need to rebuild a
 * dependency merely to discover whether the value is still valid.
 */
export function getOrComputeRevisionValue<K, V>(
  cache: Map<K, V>,
  key: K,
  compute: () => V,
): V {
  if (cache.has(key)) return cache.get(key) as V;
  const value = compute();
  cache.set(key, value);
  return value;
}

export function startCancellableStageQueue<THandle>(input: {
  stages: readonly (() => void)[];
  schedule: (work: () => void, delay: number) => THandle;
  cancelScheduled: (handle: THandle) => void;
  shouldYield?: () => boolean;
  initialDelay?: number;
  yieldDelay?: number;
  onError: (error: unknown) => void;
}): () => void {
  let cancelled = false;
  let stageIndex = 0;
  let pending: THandle | null = null;
  const scheduleNext = (delay: number) => {
    pending = input.schedule(runStage, delay);
  };
  const runStage = () => {
    pending = null;
    if (cancelled) return;
    if (input.shouldYield?.()) {
      scheduleNext(input.yieldDelay ?? 16);
      return;
    }
    try {
      input.stages[stageIndex]?.();
      stageIndex += 1;
      if (stageIndex < input.stages.length && !cancelled) scheduleNext(0);
    } catch (error) {
      if (!cancelled) input.onError(error);
    }
  };
  scheduleNext(input.initialDelay ?? 0);
  return () => {
    if (cancelled) return;
    cancelled = true;
    if (pending !== null) input.cancelScheduled(pending);
    pending = null;
  };
}

export function authoritativeFreshnessTimestamp(input: {
  currentTimestamp: string | null;
  revisionBeforeRefresh: string;
  revisionAfterRefresh: string;
  authoritativeTimestamp: string;
}): string | null {
  return input.revisionBeforeRefresh === input.revisionAfterRefresh
    ? input.currentTimestamp
    : input.authoritativeTimestamp;
}

/** A month projection cache is also scoped to the household-local as-of month. */
export function financialProjectionMonthCacheKey(
  asOfMonth: string,
  month: number,
  year: number,
): string {
  return `${asOfMonth}:${year}-${month}`;
}

export interface FinancialProjectionMonth {
  month: number;
  year: number;
}

function parsedMonthSerial(date: string | null | undefined): number | null {
  const match = /^(\d{4})-(\d{2})(?:-\d{2})?$/.exec(date ?? "");
  if (!match) return null;
  const year = Number(match[1]);
  const month = Number(match[2]) - 1;
  return month >= 0 && month <= 11 ? year * 12 + month : null;
}

/**
 * Returns the canonical month prefix that must be warmed before a target
 * projection can be read without replaying years of carryover in one task.
 * An observed balance may replace older history only when it is from a month
 * strictly before today; a same-month observation still needs the canonical
 * opening/reconciliation history.
 */
export function financialProjectionPreparationMonths(input: {
  asOfDate: string;
  startingBalanceDate?: string | null;
  observedAnchorDate?: string | null;
  targetMonth: number;
  targetYear: number;
}): FinancialProjectionMonth[] {
  const asOfSerial = parsedMonthSerial(input.asOfDate);
  const targetSerial = input.targetYear * 12 + input.targetMonth;
  if (asOfSerial === null || input.targetMonth < 0 || input.targetMonth > 11) {
    return [{ month: input.targetMonth, year: input.targetYear }];
  }

  const observedSerial = parsedMonthSerial(input.observedAnchorDate);
  const configuredStartSerial = parsedMonthSerial(input.startingBalanceDate);
  let startSerial = configuredStartSerial ?? asOfSerial - 1;
  if (observedSerial !== null && observedSerial < asOfSerial) {
    startSerial = observedSerial + 1;
  }
  // Always prepare the current month even if a future plan start was entered.
  startSerial = Math.min(startSerial, asOfSerial);
  if (startSerial > targetSerial) startSerial = targetSerial;

  const months: FinancialProjectionMonth[] = [];
  for (let serial = startSerial; serial <= targetSerial; serial += 1) {
    months.push({
      month: ((serial % 12) + 12) % 12,
      year: Math.floor(serial / 12),
    });
  }
  return months;
}

function structuralFinancialEqual(left: unknown, right: unknown): boolean {
  if (Object.is(left, right)) return true;
  if (Array.isArray(left) || Array.isArray(right)) {
    if (!Array.isArray(left) || !Array.isArray(right) || left.length !== right.length) {
      return false;
    }
    for (let index = 0; index < left.length; index += 1) {
      if (!structuralFinancialEqual(left[index], right[index])) return false;
    }
    return true;
  }
  if (!left || !right || typeof left !== "object" || typeof right !== "object") {
    return false;
  }
  const leftRecord = left as Record<string, unknown>;
  const rightRecord = right as Record<string, unknown>;
  let leftKeyCount = 0;
  let rightKeyCount = 0;
  for (const key in leftRecord) {
    if (!Object.prototype.hasOwnProperty.call(leftRecord, key)) continue;
    if (leftRecord[key] === undefined) continue;
    leftKeyCount += 1;
    if (
      !Object.prototype.hasOwnProperty.call(rightRecord, key)
      || !structuralFinancialEqual(leftRecord[key], rightRecord[key])
    ) return false;
  }
  for (const key in rightRecord) {
    if (
      Object.prototype.hasOwnProperty.call(rightRecord, key)
      && rightRecord[key] !== undefined
    ) rightKeyCount += 1;
  }
  return leftKeyCount === rightKeyCount;
}

function financialRowIdentity(value: unknown): string | null {
  if (!value || typeof value !== "object") return null;
  const record = value as Record<string, unknown>;
  for (const key of ["id", "plaid_transaction_id", "plaid_account_id"] as const) {
    if (typeof record[key] === "string" && record[key]) return `${key}:${record[key]}`;
  }
  return null;
}

/**
 * Reuses an immutable financial source when cache and live normalization carry
 * identical rows. This prevents the background authoritative refresh from
 * invalidating every provider index immediately after warm-cache reveal.
 */
export function reuseStructurallyEqualFinancialValue<T>(current: T, next: T): T {
  if (Object.is(current, next)) return current;
  if (Array.isArray(current) && Array.isArray(next) && current.length === next.length) {
    // The warm-cache path normally preserves order. Compare that path directly
    // without allocating two ledger-sized JSON strings or key arrays.
    let sameOrder = true;
    for (let index = 0; index < current.length; index += 1) {
      if (!structuralFinancialEqual(current[index], next[index])) {
        sameOrder = false;
        break;
      }
    }
    if (sameOrder) return current;
    const currentByIdentity = new Map<string, unknown>();
    let identityComparable = current.length > 0;
    current.forEach(value => {
      const identity = financialRowIdentity(value);
      if (!identity || currentByIdentity.has(identity)) identityComparable = false;
      else currentByIdentity.set(identity, value);
    });
    if (identityComparable) {
      const nextIdentities = new Set<string>();
      let validIdentitySet = true;
      let changed = false;
      const sharedRows = next.map((value, index) => {
        const identity = financialRowIdentity(value);
        if (
          !identity
          || nextIdentities.has(identity)
          || !currentByIdentity.has(identity)
        ) {
          validIdentitySet = false;
          return value;
        }
        nextIdentities.add(identity);
        const prior = currentByIdentity.get(identity);
        if (!structuralFinancialEqual(prior, value)) {
          changed = true;
          return value;
        }
        // Preserve the next array's ordering contract. Reordering is a real
        // collection change even though unchanged row objects remain shared.
        if (prior !== current[index]) changed = true;
        return prior;
      });
      if (validIdentitySet && nextIdentities.size === currentByIdentity.size) {
        return (changed ? sharedRows : current) as T;
      }
    }
  }
  return structuralFinancialEqual(current, next) ? current : next;
}

import {
  isActiveTransaction,
  isDeletedTransaction,
  plaidTransactionAccountKind,
} from "./billMatching.ts";
import { canonicalDebtPaymentMethod } from "./debtOrder.ts";
import { normalizeBillImportance } from "./billImportance.ts";
import { selectFlowLedgerTransactions } from "./ledgerEngine.ts";
import { type PendingPlanMatch } from "./pendingPlanMatches.ts";
import type {
  Bill,
  MonthlyOverride,
  BillDateMove,
  Transaction,
  PendingBankTransaction,
  Account,
  ConnectedBankAccount,
  Goal,
  ExtraPayment,
  Settings,
} from "./financialProjectionTypes.ts";

export const DEFAULT_SETTINGS: Settings = {
  zeroBasedBudgetEnabled: false,
  debtPayoffEnabled: true,
  paymentMethod: "snowball",
  starting_balance: 0,
  calendar_start_date: undefined,
  safety_floor: 200,
  forecast_horizon_months: 6,
  onboarding_completed: false,
};

function finiteNumber(value: unknown, fallback = 0): number {
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : fallback;
}

function optionalFiniteNumber(value: unknown): number | undefined {
  if (value === null || value === undefined) return undefined;
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : undefined;
}

export function normalizeSettingsRow(
  row: any,
  fallback: Settings = DEFAULT_SETTINGS,
): Settings {
  return {
    zeroBasedBudgetEnabled:
      row?.zero_based_budget_enabled ?? fallback.zeroBasedBudgetEnabled,
    debtPayoffEnabled: row?.debt_payoff_enabled ?? fallback.debtPayoffEnabled,
    paymentMethod: canonicalDebtPaymentMethod(
      row?.payment_method ?? fallback.paymentMethod,
    ),
    starting_balance: Number(
      row?.starting_balance ?? fallback.starting_balance,
    ),
    starting_balance_date: row?.starting_balance_date ?? undefined,
    calendar_start_date: row?.calendar_start_date ?? undefined,
    safety_floor: Number(row?.safety_floor ?? fallback.safety_floor),
    forecast_horizon_months: Number(
      row?.forecast_horizon_months ?? fallback.forecast_horizon_months,
    ),
    onboarding_completed:
      row?.onboarding_completed ?? fallback.onboarding_completed,
  };
}

export function normalizeBillRow(bill: any): Bill {
  return {
    ...bill,
    frequency: (bill.frequency ?? "monthly") as
      | "monthly"
      | "quarterly"
      | "biweekly"
      | "weekly",
    day_of_week: bill.day_of_week ?? 0,
    next_payment_date: bill.next_payment_date ?? undefined,
    amount: finiteNumber(bill.amount),
    balance: finiteNumber(bill.balance),
    interest_rate: finiteNumber(bill.interest_rate),
    smart_priority: normalizeBillImportance(
      bill.smart_priority,
      Boolean(bill.is_debt),
    ),
    include_in_snowball: bill.include_in_snowball !== false,
    snowball_minimum_boost: finiteNumber(bill.snowball_minimum_boost),
  };
}

export function normalizeBillDateMoveRow(row: any): BillDateMove {
  const customAmount = row.custom_amount === null || row.custom_amount === undefined
    ? undefined
    : Number(row.custom_amount);
  return {
    id: String(row.id ?? genId()),
    bill_id: String(row.bill_id),
    from_date: String(row.from_date).slice(0, 10),
    to_date: String(row.to_date).slice(0, 10),
    custom_amount: customAmount !== undefined && Number.isFinite(customAmount)
      ? Math.max(0, customAmount)
      : undefined,
    is_skipped: row.is_skipped === true,
    move_reason: row.move_reason === "automatic" ? "automatic" : "manual",
    created_at: String(row.created_at ?? new Date().toISOString()),
    updated_at: row.updated_at ? String(row.updated_at) : undefined,
  };
}

export function normalizeStoredBillDateMoves(value: unknown): BillDateMove[] {
  if (!Array.isArray(value)) return [];
  return value
    .filter(row => row && typeof row === "object" && row.bill_id && row.from_date && row.to_date)
    .map(normalizeBillDateMoveRow);
}

export function normalizeGoalRow(goal: any): Goal {
  return {
    ...goal,
    target_amount: Number(goal.target_amount),
    current_amount: Number(goal.current_amount),
    goal_type:
      goal.goal_type ??
      (Number(goal.current_amount) < 0 ? "planned_expense" : "savings"),
  };
}

export function normalizeExtraPaymentRow(payment: any): ExtraPayment {
  return {
    ...payment,
    amount: Number(payment.amount),
    allocations: payment.allocations ?? [],
    payment_date: payment.payment_date ?? undefined,
    sources: payment.sources ?? [
      { type: "manual", amount: Number(payment.amount) },
    ],
  };
}

export function normalizeTransactionRow(transaction: any): Transaction {
  return {
    ...transaction,
    amount: Number(transaction.amount),
    debt_applied_amount: Number(transaction.debt_applied_amount ?? 0),
    debt_applied_bill_id: transaction.debt_applied_bill_id ?? undefined,
    review_allocations: Array.isArray(transaction.review_allocations)
      ? transaction.review_allocations.map((allocation: any) => ({
          ...allocation,
          amount: Number(allocation.amount ?? 0),
          plannedAmount:
            allocation.plannedAmount === undefined
              ? undefined
              : Number(allocation.plannedAmount),
        }))
      : [],
    linked_income_id: transaction.linked_income_id ?? undefined,
    linked_plan_id: transaction.linked_plan_id ?? undefined,
    linked_plan_type: transaction.linked_plan_type ?? undefined,
    matched_occurrence_date: transaction.matched_occurrence_date ?? undefined,
  };
}

export function splitTransactionRows(rows: any[]): {
  active: Transaction[];
  deleted: Transaction[];
} {
  const normalized = rows.map(normalizeTransactionRow);
  return {
    active: normalized.filter(isActiveTransaction),
    deleted: normalized
      .filter(isDeletedTransaction)
      .sort((left, right) =>
        String(right.deleted_at ?? "").localeCompare(
          String(left.deleted_at ?? ""),
        ),
      ),
  };
}

export function accountAwareTransactionCollections(
  rows: any[],
  accountIdentities: readonly ConnectedBankAccount[],
): {
  active: Transaction[];
  deleted: Transaction[];
  unknownPlaid: Transaction[];
} {
  const collections = splitTransactionRows(rows);
  const active = selectFlowLedgerTransactions(
    collections.active,
    accountIdentities,
  );
  const deleted = selectFlowLedgerTransactions(
    collections.deleted,
    accountIdentities,
  );
  return {
    active: active.included,
    deleted: deleted.included,
    unknownPlaid: [...active.unknownPlaid, ...deleted.unknownPlaid],
  };
}

export function checkingPendingBankRows(
  rows: PendingBankTransaction[],
  accountIdentities: readonly ConnectedBankAccount[],
): { included: PendingBankTransaction[]; unknownCount: number } {
  const included: PendingBankTransaction[] = [];
  let unknownCount = 0;
  rows.forEach((row) => {
    const kind = plaidTransactionAccountKind(
      { source: "plaid", plaid_account_id: row.plaid_account_id },
      accountIdentities,
    );
    if (kind === "checking") included.push(row);
    else if (kind === "unknown") unknownCount += 1;
  });
  return { included, unknownCount };
}

export function normalizePendingBankRows(
  rows: any[],
): PendingBankTransaction[] {
  return rows.map((row) => ({
    plaid_transaction_id: String(row.plaid_transaction_id),
    transaction_date: String(row.transaction_date).slice(0, 10),
    amount: Number(row.amount),
    name: String(row.name || row.merchant_name || "Pending transaction"),
    merchant_name: row.merchant_name || undefined,
    category: String(row.category || "Other"),
    plaid_account_id: row.plaid_account_id || undefined,
  }));
}

export function normalizePendingPlanMatchRow(row: any): PendingPlanMatch {
  return {
    id: String(row.id),
    pending_plaid_transaction_id: String(row.pending_plaid_transaction_id),
    pending_account_id: row.pending_account_id || undefined,
    target_type: row.target_type === "manual" ? "manual" : "bill",
    target_id: String(row.target_id),
    target_name: String(row.target_name || "Planned bill"),
    occurrence_date: String(row.occurrence_date).slice(0, 10),
    planned_amount: Number(row.planned_amount),
    pending_amount: Number(row.pending_amount),
    pending_transaction_date: String(row.pending_transaction_date).slice(0, 10),
    status: row.status,
    posted_transaction_id: row.posted_transaction_id || undefined,
    posted_plaid_transaction_id: row.posted_plaid_transaction_id || undefined,
    posted_amount:
      row.posted_amount == null ? undefined : Number(row.posted_amount),
    created_at: String(row.created_at),
    updated_at: String(row.updated_at),
  };
}

export function normalizeConnectedBankRows(
  rows: any[],
): ConnectedBankAccount[] {
  return rows.map((account) => {
    const currentBalance = Number(account.current_balance);
    const currentBalanceAvailable =
      account.current_balance != null && Number.isFinite(currentBalance);
    return {
      ...account,
      // Existing account presentation expects a number, but forecasting must
      // distinguish an unavailable Plaid balance from a verified zero.
      current_balance: currentBalanceAvailable ? currentBalance : 0,
      current_balance_available: currentBalanceAvailable,
      available_balance:
        account.available_balance == null
          ? undefined
          : Number(account.available_balance),
      minimum_payment_amount:
        account.minimum_payment_amount == null
          ? undefined
          : Number(account.minimum_payment_amount),
      last_statement_balance:
        account.last_statement_balance == null
          ? undefined
          : Number(account.last_statement_balance),
      purchase_apr:
        account.purchase_apr == null ? undefined : Number(account.purchase_apr),
      is_active: account.is_active !== false,
    };
  });
}

export function normalizeAccountRow(account: any): Account {
  return {
    ...account,
    current_balance: Number(account.current_balance || 0),
    last_reconciled_at: account.last_reconciled_at ?? undefined,
    is_active: account.is_active !== false,
  };
}

export function normalizeMonthlyOverrideRow(override: any): MonthlyOverride {
  return {
    ...override,
    paid_amount: finiteNumber(override.paid_amount),
    custom_amount: optionalFiniteNumber(override.custom_amount),
    planned_debt_amount: optionalFiniteNumber(override.planned_debt_amount),
    required_debt_amount: optionalFiniteNumber(override.required_debt_amount),
    custom_due_day: optionalFiniteNumber(override.custom_due_day),
    actual_amount: optionalFiniteNumber(override.actual_amount),
    paid_date: override.paid_date ?? undefined,
  };
}

function genId(): string {
  return Math.random().toString(36).slice(2) + Date.now().toString(36);
}

export interface DebtBalanceItem {
  balance: number;
  name: string;
}

export interface DebtStrategyItem extends DebtBalanceItem {
  id: string;
  interest_rate: number;
  include_in_snowball?: boolean;
}

export function canonicalDebtPaymentMethod(_method: unknown): "snowball" {
  return "snowball";
}

export function sortDebtsLeastToGreatest<T extends DebtBalanceItem>(debts: readonly T[]): T[] {
  return debts.slice().sort((left, right) =>
    left.balance - right.balance || left.name.localeCompare(right.name),
  );
}

export function orderActiveDebtsForStrategy<T extends DebtStrategyItem>(
  debts: readonly T[],
  method: "snowball" | "avalanche",
): T[] {
  const active = debts.filter(debt => debt.balance > 0.009 && debt.include_in_snowball !== false);
  if (method === "avalanche") {
    return active.slice().sort((left, right) =>
      right.interest_rate - left.interest_rate
      || left.balance - right.balance
      || left.name.localeCompare(right.name),
    );
  }
  return sortDebtsLeastToGreatest(active);
}

export function sortDebtsWithPaidLast<T extends DebtBalanceItem>(debts: readonly T[]): T[] {
  return debts.slice().sort((left, right) => {
    const leftPaid = left.balance <= 0.009;
    const rightPaid = right.balance <= 0.009;
    if (leftPaid !== rightPaid) return leftPaid ? 1 : -1;
    return left.balance - right.balance || left.name.localeCompare(right.name);
  });
}

export type BillImportance = "must" | "flexible" | "optional";

export const BILL_IMPORTANCE_OPTIONS: readonly {
  value: BillImportance;
  label: string;
  description: string;
  icon: "shield" | "sliders" | "heart";
}[] = [
  {
    value: "must",
    label: "Must Pay",
    description: "Protect this first. It counts toward your required backup days.",
    icon: "shield",
  },
  {
    value: "flexible",
    label: "Flexible",
    description: "You need it, and the date or amount can flex to help build more breathing room.",
    icon: "sliders",
  },
  {
    value: "optional",
    label: "Optional",
    description: "Good to have, but it does not count as a required expense.",
    icon: "heart",
  },
] as const;

export function normalizeBillImportance(value: unknown, isDebt = false): BillImportance {
  if (isDebt) return "must";
  return value === "flexible" || value === "optional" ? value : "must";
}

export function isRequiredBill(importance: BillImportance | null | undefined, isDebt = false): boolean {
  return normalizeBillImportance(importance, isDebt) === "must";
}

export interface PlaidAccountIdentityRow {
  id: string;
  plaid_account_id?: string | null;
  persistent_account_id?: string | null;
  name?: string | null;
  official_name?: string | null;
  mask?: string | null;
  account_type?: string | null;
  account_subtype?: string | null;
  current_balance?: number | null;
  current_balance_available?: boolean;
  available_balance?: number | null;
  is_active: boolean;
  updated_at?: string | null;
}

export interface PendingPlaidActivityRow {
  plaid_transaction_id: string;
  plaid_account_id?: string;
  transaction_date: string;
  amount: number;
  name: string;
  merchant_name?: string;
  category?: string | null;
}

export interface PendingCheckingSummary {
  currentBalance: number;
  availableBalance: number;
  pendingOutflow: number;
  pendingInflow: number;
  pendingCount: number;
}

function normalizedText(value: string | null | undefined): string {
  return String(value || "").trim().toLowerCase().replace(/\s+/g, " ");
}

export function plaidAccountIdentity(account: PlaidAccountIdentityRow): string {
  const persistentId = normalizedText(account.persistent_account_id);
  if (persistentId) return `persistent:${persistentId}`;

  const mask = normalizedText(account.mask);
  if (!mask) return `row:${account.id}`;
  const name = normalizedText(account.official_name || account.name);
  return ["fallback", mask, normalizedText(account.account_type), normalizedText(account.account_subtype), name].join(":");
}

function isNewerAccount(candidate: PlaidAccountIdentityRow, current: PlaidAccountIdentityRow): boolean {
  return String(candidate.updated_at || "") > String(current.updated_at || "");
}

export function canonicalConnectedAccounts<T extends PlaidAccountIdentityRow>(accounts: T[]): T[] {
  const canonical = new Map<string, T>();
  for (const account of accounts) {
    if (!account.is_active) continue;
    const key = plaidAccountIdentity(account);
    const current = canonical.get(key);
    if (!current || isNewerAccount(account, current)) canonical.set(key, account);
  }
  return [...canonical.values()];
}

export function visiblePendingPlaidActivity<
  T extends PendingPlaidActivityRow,
  A extends PlaidAccountIdentityRow,
>(pendingRows: T[], accounts: A[]): T[] {
  const activeAccounts = accounts.filter(account => account.is_active);
  const accountIdentityById = new Map(activeAccounts.map(account => [account.id, plaidAccountIdentity(account)]));

  // Pick one source account per real-account identity. Filtering by source
  // account (rather than amount/merchant) keeps two genuine identical charges
  // while removing the copies created by reconnecting the same bank account.
  const accountsWithPending = new Set(pendingRows.map(row => row.plaid_account_id).filter(Boolean));
  const canonicalSources = canonicalConnectedAccounts(activeAccounts.filter(account => accountsWithPending.has(account.id)));
  const sourceAccountByIdentity = new Map(canonicalSources.map(account => [plaidAccountIdentity(account), account.id]));

  return pendingRows.filter(pending => {
    const accountId = pending.plaid_account_id || "";
    if (!accountId) return true;
    const identity = accountIdentityById.get(accountId);
    if (!identity) return false;
    return sourceAccountByIdentity.get(identity) === accountId;
  });
}

function roundCurrency(value: number): number {
  return Math.round(value * 100) / 100;
}

function isCheckingAccount(account: PlaidAccountIdentityRow): boolean {
  const type = normalizedText(account.account_type);
  const subtype = normalizedText(account.account_subtype);
  const name = normalizedText(`${account.name || ""} ${account.official_name || ""}`);
  if (subtype === "savings" || name.includes("savings")) return false;
  return type === "depository" && (subtype === "checking" || name.includes("checking") || name.includes("bill account"));
}

export function summarizePendingCheckingActivity<
  T extends PendingPlaidActivityRow,
  A extends PlaidAccountIdentityRow,
>(pendingRows: T[], accounts: A[]): PendingCheckingSummary | null {
  const checkingAccounts = canonicalConnectedAccounts(accounts).filter(isCheckingAccount);
  if (!checkingAccounts.length) return null;
  if (checkingAccounts.some(account => (
    account.current_balance_available === false
    || account.current_balance == null
    || !Number.isFinite(Number(account.current_balance))
  ))) return null;

  const checkingIds = new Set(checkingAccounts.map(account => account.id));
  const checkingPending = pendingRows.filter(row => {
    if (row.plaid_account_id) return checkingIds.has(row.plaid_account_id);
    return checkingAccounts.length === 1;
  });
  const currentBalance = roundCurrency(checkingAccounts.reduce(
    (sum, account) => sum + Number(account.current_balance || 0),
    0,
  ));
  const pendingOutflow = roundCurrency(checkingPending
    .filter(row => Number(row.amount) < 0)
    .reduce((sum, row) => sum + Math.abs(Number(row.amount) || 0), 0));
  const pendingInflow = roundCurrency(checkingPending
    .filter(row => Number(row.amount) > 0)
    .reduce((sum, row) => sum + Number(row.amount || 0), 0));
  const bankSuppliesAvailable = checkingAccounts.some(account =>
    account.available_balance != null && Number.isFinite(Number(account.available_balance))
  );
  const availableBalance = bankSuppliesAvailable
    ? roundCurrency(checkingAccounts.reduce((sum, account) => {
        const available = account.available_balance == null ? Number.NaN : Number(account.available_balance);
        return sum + (Number.isFinite(available) ? available : Number(account.current_balance || 0));
      }, 0))
    : roundCurrency(currentBalance - pendingOutflow + pendingInflow);

  return {
    currentBalance,
    availableBalance,
    pendingOutflow,
    pendingInflow,
    pendingCount: checkingPending.length,
  };
}

export function unplannedPendingExpenses<T extends PendingPlaidActivityRow>(
  pendingRows: T[],
  matchedPendingIds: Iterable<string>,
): T[] {
  const matchedIds = new Set(matchedPendingIds);
  return pendingRows
    .filter(row => Number(row.amount) < 0)
    .filter(row => !matchedIds.has(row.plaid_transaction_id))
    .filter(row => !row.plaid_transaction_id.startsWith("pending-hold:"))
    .filter(row => normalizedText(row.merchant_name || row.name) !== "pending bank hold")
    .sort((left, right) =>
      right.transaction_date.localeCompare(left.transaction_date)
      || left.plaid_transaction_id.localeCompare(right.plaid_transaction_id)
    );
}

function hasMatchingPendingAmount(pendingRows: PendingPlaidActivityRow[], accountId: string, amount: number): boolean {
  return pendingRows.some(row =>
    row.plaid_account_id === accountId &&
    Math.abs(roundCurrency(Number(row.amount || 0)) - amount) < 0.005
  );
}

export function pendingPlaidActivityWithBalanceHolds<
  T extends PendingPlaidActivityRow,
  A extends PlaidAccountIdentityRow,
>(pendingRows: T[], accounts: A[], today: string): Array<PendingPlaidActivityRow & { category: string }> {
  const accountIdentityById = new Map(
    accounts.filter(account => account.is_active).map(account => [account.id, plaidAccountIdentity(account)]),
  );
  const canonicalAccountIdByIdentity = new Map(
    canonicalConnectedAccounts(accounts).map(account => [plaidAccountIdentity(account), account.id]),
  );
  const visibleRows = visiblePendingPlaidActivity(pendingRows, accounts)
    .map(row => {
      const identity = row.plaid_account_id ? accountIdentityById.get(row.plaid_account_id) : undefined;
      return {
        ...row,
        plaid_account_id: identity
          ? canonicalAccountIdByIdentity.get(identity)
          : row.plaid_account_id || undefined,
        category: String(row.category || "Pending"),
      };
    });
  const inferredRows = canonicalConnectedAccounts(accounts)
    .filter(isCheckingAccount)
    .flatMap(account => {
      if (account.current_balance_available === false) return [];
      const current = Number(account.current_balance);
      const available = Number(account.available_balance);
      if (!Number.isFinite(current) || !Number.isFinite(available)) return [];
      const hold = roundCurrency(current - available);
      if (hold <= 0.005) return [];
      const amount = -hold;
      if (hasMatchingPendingAmount(visibleRows, account.id, amount)) return [];
      return [{
        plaid_transaction_id: `pending-hold:${account.id}:${hold.toFixed(2)}`,
        plaid_account_id: account.id,
        transaction_date: today,
        amount,
        name: "Pending bank hold",
        merchant_name: undefined,
        category: "Pending",
      }];
    });
  return [...visibleRows, ...inferredRows];
}

import { dayAdd, dollars, label, matches, monthEnd, monthStart, numeric, requireSources, round, shiftMonth, sum, validDate, type AnalysisRequest, type AnalysisResult, type AnalysisSnapshot } from "./analysisTypes.ts";

export type AnalyticTransaction = { id: string; date: string; amount: number; merchant: string; category: string; account: string; accountKey?: string; kind: "spending" | "income" | "refund" | "transfer" | "repayment" | "unresolved"; repaymentKind?: "card" | "loan" | "unknown"; billId?: string };
const hasIdentity = (value: unknown): value is string => typeof value === "string" && value.trim().length > 0;
const sameIdentity = (left: unknown, right: unknown): boolean => hasIdentity(left) && hasIdentity(right) && left === right;
/** Stored Plaid amounts already use FlowLedger's sign convention. */
export function analyticTransactions(snapshot: AnalysisSnapshot): { rows: AnalyticTransaction[]; missing: string[] } {
  const source = (table: string) => snapshot.sources[table]?.rows ?? [];
  const accounts = source("plaid_accounts");
  const manual = source("transactions");
  const byProvider = new Map(source("plaid_transactions").filter(r => hasIdentity(r.plaid_transaction_id)).map(r => [r.plaid_transaction_id, r]));
  const manualIds = new Set(manual.map(r => r.id).filter(hasIdentity));
  const providerIds = new Set(manual.map(r => r.plaid_transaction_id).filter(hasIdentity));
  const debts = new Set(source("bills").filter(r => r.is_debt).map(r => r.id).filter(hasIdentity));
  const imported = source("plaid_transactions").filter(r => !providerIds.has(r.plaid_transaction_id) && !manualIds.has(r.flowledger_transaction_id));
  const rows: AnalyticTransaction[] = [];
  const missing = requireSources(snapshot, ["transactions", "plaid_transactions", "plaid_accounts", "bills", "goals"]);
  for (const entry of [...manual.map(r => ({ r, bank: false })), ...imported.map(r => ({ r, bank: true }))]) {
    const { r, bank } = entry;
    if (r.pending || r.removed_at || r.deleted_at) continue;
    const bankRow = bank ? r : hasIdentity(r.plaid_transaction_id) ? byProvider.get(r.plaid_transaction_id) : undefined;
    // Missing identifiers do not establish a relationship. Matching undefined
    // values previously attached manual salary to the first connected card and
    // classified income as a card refund.
    const account = accounts.find(a => sameIdentity(a.id, r.plaid_account_id) || sameIdentity(a.plaid_account_id, r.plaid_account_id) || sameIdentity(a.id, bankRow?.plaid_account_id) || sameIdentity(a.plaid_account_id, bankRow?.plaid_account_id));
    const credit = account?.account_type === "credit";
    const amount = numeric(r.amount);
    if (amount === null || !validDate(r.date ?? r.transaction_date)) { missing.push("Some transaction amounts or dates are invalid"); continue; }
    // A future-dated manual entry is a plan, not observed spending or income.
    if (String(r.date ?? r.transaction_date) > snapshot.today) continue;
    const category = String(r.category ?? bankRow?.category ?? "Other");
    const pfc = `${bankRow?.primary_category ?? ""} ${bankRow?.detailed_category ?? ""}`;
    const savingsGoal=r.linked_plan_type==="goal"&&source("goals").some(g=>sameIdentity(g.id,r.linked_plan_id)&&g.goal_type==="savings");
    const transfer = savingsGoal || r.review_resolution === "transfer" || r.review_status === "transfer" || Boolean(r.transfer_group_id) || /TRANSFER_(?:IN|OUT)_ACCOUNT_TRANSFER/.test(pfc);
    const cardRepayment = /CREDIT_CARD_PAYMENT|CREDIT CARD PAYMENT/i.test(`${category} ${pfc}`);
    const loanRepayment = /LOAN_PAYMENTS_(?:CAR|MORTGAGE|STUDENT|OTHER)_PAYMENT|^(?:Mortgage|Auto loan|Student loan)$/i.test(`${category} ${pfc}`.trim());
    const repayment = cardRepayment || loanRepayment || Boolean(r.linked_bill_id && debts.has(r.linked_bill_id));
    const income = Boolean(r.linked_income_id) || /^(income|paycheck|salary|wages)$/i.test(category) || /\bINCOME\b/.test(pfc);
    let kind: AnalyticTransaction["kind"] = transfer ? "transfer" : repayment ? "repayment" : r.review_status === "needs_review" ? "unresolved" : amount < 0 ? "spending" : credit ? "refund" : income ? "income" : /refund|reversal/i.test(`${category} ${pfc}`) ? "refund" : "unresolved";
    if ((bank || r.source === "plaid") && !account) kind = "unresolved";
    if(!transfer&&/TRANSFER_(?:IN|OUT)/.test(pfc))kind="unresolved";
    if(!transfer&&/^savings$/i.test(category))kind="unresolved";
    if(!transfer&&r.linked_plan_type==="goal"&&!source("goals").some(g=>sameIdentity(g.id,r.linked_plan_id)&&g.goal_type==="planned_expense"))kind="unresolved";
    // Raw credit loan-payment credits are repayments, not merchant refunds.
    if (credit && amount > 0 && /LOAN_PAYMENTS/.test(pfc)) kind = "repayment";
    const manualAccount=source("accounts").find(a=>sameIdentity(a.id,r.account_id));
    const accountKey=hasIdentity(account?.id)?`connected:${account.id}`:hasIdentity(r.account_id)?`manual:${r.account_id}`:undefined;
    const base:AnalyticTransaction = { id: String(r.id), date: String(r.date ?? r.transaction_date), amount, merchant: label(r.merchant_name ?? r.note ?? r.name), category: label(category), account: label(account?.display_name ?? account?.name ?? manualAccount?.name ?? r.account_id ?? "Unassigned account"), accountKey, kind, repaymentKind:repayment ? cardRepayment||credit ? "card" : loanRepayment ? "loan" : "unknown" : undefined, billId: r.linked_bill_id };
    const allocations = Array.isArray(r.review_allocations) ? r.review_allocations : [];
    if (kind === "spending" && allocations.length && Math.abs(sum(allocations.map((a: any) => Math.abs(numeric(a.amount) ?? NaN))) - Math.abs(amount)) < .005) {
      allocations.forEach((a: any, index: number) => rows.push({ ...base, id: `${base.id}:${index}`, amount: -Math.abs(Number(a.amount)), category: label(a.category ?? a.name ?? category), kind: a.type === "transfer" ? "transfer" : a.type === "extra_principal" || debts.has(a.targetId) ? "repayment" : "spending" }));
    } else if(kind === "spending" && allocations.length) {
      rows.push({...base,kind:"unresolved"});
      missing.push("A split transaction does not reconcile to its recorded amount");
    } else rows.push(base);
  }
  return { rows, missing: [...new Set(missing)] };
}

export function aggregateSpending(rows: AnalyticTransaction[], start: string, end: string) {
  const period = rows.filter(r => r.date >= start && r.date <= end);
  const spending = period.filter(r => r.kind === "spending" || r.kind === "refund");
  const group = (key: "category" | "merchant") => {
    const totals = new Map<string, number>();
    spending.forEach(r => totals.set(r[key], (totals.get(r[key]) ?? 0) - Math.round(r.amount * 100)));
    return [...totals].map(([name, value]) => ({ name, amount: value / 100 })).sort((a, b) => b.amount - a.amount);
  };
  return { start, end, spending: -sum(spending.map(r => r.amount)) || 0, income: sum(period.filter(r => r.kind === "income").map(r => r.amount)), repayments: -sum(period.filter(r => r.kind === "repayment" && r.amount < 0).map(r => r.amount)) || 0, nonCardRepayments:-sum(period.filter(r=>r.kind==="repayment"&&r.repaymentKind==="loan"&&r.amount<0).map(r=>r.amount))||0, unclassifiedDebt:period.filter(r=>r.kind==="repayment"&&(!r.repaymentKind||r.repaymentKind==="unknown")).length, unresolved: period.filter(r => r.kind === "unresolved").length, categories: group("category"), merchants: group("merchant"), rows: period };
}

/** A recorded settlement cannot be treated as expense history unless its
 * payment is present in classified posted activity. Transfers and refunds do
 * not prove that an expense or required repayment was included. */
export function historicalExpenseCoverage(snapshot: AnalysisSnapshot, rows: readonly AnalyticTransaction[], start: string, end: string): { complete: boolean; missing: string[] } {
  const missing = requireSources(snapshot, ["monthly_overrides"]);
  const period = rows.filter(r => r.date >= start && r.date <= end);
  let unreconciled = false;
  for (const settlement of snapshot.sources.monthly_overrides?.rows ?? []) {
    const year = numeric(settlement.year), monthIndex = numeric(settlement.month);
    if (year === null || monthIndex === null || !Number.isInteger(year) || year < 1900 || year > 9999 || !Number.isInteger(monthIndex) || monthIndex < 0 || monthIndex > 11) {
      missing.push("A bill settlement period is invalid, so its expense-history coverage cannot be verified");
      continue;
    }
    const month = `${year}-${String(monthIndex + 1).padStart(2, "0")}`;
    if (month < start.slice(0, 7) || month > end.slice(0, 7)) continue;
    const paid = numeric(settlement.paid_amount), actual = settlement.actual_amount == null ? null : numeric(settlement.actual_amount);
    if (paid === null || paid < 0 || (settlement.actual_amount != null && (actual === null || actual < 0))) {
      missing.push("A bill settlement amount is invalid; its recorded payment cannot be verified against expense history");
      continue;
    }
    if (paid === 0) continue;
    const linked = sum(period.filter(t => sameIdentity(t.billId, settlement.bill_id) && t.date.slice(0, 7) === month && t.amount < 0 && (t.kind === "spending" || t.kind === "repayment")).map(t => -t.amount));
    if (linked + .005 < paid) unreconciled = true;
  }
  if (unreconciled) missing.push("Some recorded bill payments are not reconciled to posted transaction history; the expense baseline could omit obligations. Match those payments before relying on a historical expense baseline");
  return { complete: missing.length === 0, missing: [...new Set(missing)] };
}

export function spendingAnalysis(snapshot: AnalysisSnapshot, request: AnalysisRequest): AnalysisResult {
  const all = analyticTransactions(snapshot);
  const lastPayment=request.purpose==="transaction_last";
  const defaultMonthlyIncome=request.domain==="income"&&request.operation==="average"&&request.startDate===null&&request.endDate===null;
  const start = request.startDate ?? (defaultMonthlyIncome?monthStart(shiftMonth(snapshot.today,-3)):lastPayment?all.rows.map(r=>r.date).sort()[0]??snapshot.today:monthStart(snapshot.today));
  const requestedEnd = request.endDate ?? (defaultMonthlyIncome?dayAdd(monthStart(snapshot.today),-1):snapshot.today);
  const end = requestedEnd < snapshot.today ? requestedEnd : snapshot.today;
  if(start>end)return {text:"That range is in the future. Recorded spending and received income can only be reviewed through today; ask for a forecast for future money.",facts:{},sources:["transactions","plaid_transactions"],assumptions:[],missing:["The requested range has no elapsed dates"],scenario:false};
  const filtered = all.rows.filter(r => matches(r.merchant, request.merchant ?? (request.domain === "transactions" ? request.entity : null)) && matches(r.category, request.category));
  const current = aggregateSpending(filtered, start, end);
  const missing = [...all.missing];
  if (current.unresolved) missing.push(`${current.unresolved} transactions need classification and are excluded from income/spending totals`);
  const facts: AnalysisResult["facts"] = { spending: current.spending, income: current.income, debtRepayments: current.repayments, startDate: start, endDate: end };
  const lines: string[] = [];
  if(lastPayment) {
    const payments=current.rows.filter(r=>r.amount<0&&["spending","repayment"].includes(r.kind)).sort((a,b)=>b.date.localeCompare(a.date)||a.id.localeCompare(b.id));
    const latest=payments[0]?.date;
    const sameDay=payments.filter(r=>r.date===latest);
    facts.lastPaymentDate=latest??null;facts.matchCount=payments.length;facts.latestDayPaymentCount=sameDay.length;
    lines.push(latest?`The latest matching recorded payment date is ${latest}${request.merchant??request.entity?` for ${label(request.merchant??request.entity)}`:""}. ${sameDay.map(r=>`${r.merchant}: ${dollars(-r.amount)}`).slice(0,8).join("; ")}.`:`No matching posted payment was found in the retained records from ${start} through ${end}.`);
    lines.push(`Searched retained posted history from ${start} through ${end}; records outside that coverage are not checked. Same-day payments have no verified posting order.`);
    if(!request.merchant&&!request.entity)missing.push("No merchant was specified; this is the most recent recorded payment across merchants");
  } else if(request.domain==="income") {
    const received=current.rows.filter(r=>r.kind==="income"&&matches(r.merchant,request.entity));
    const total=sum(received.map(r=>r.amount));
    facts.income=total;facts.paycheckCount=received.length;facts.averagePaycheck=received.length?round(total/received.length):null;
    lines.push(`${dollars(total)} in confirmed recorded income from ${start} through ${end}${request.entity?` matching ${label(request.entity)}`:""}.`);
    if(received.length)lines.push(`Average recorded payment: ${dollars(total/received.length)} across ${received.length} payments. Most recent: ${received.sort((a,b)=>b.date.localeCompare(a.date))[0].date}.`);
    if(request.operation==="average") {
      const completeStart=monthStart(start)===start;const completeEnd=dayAdd(end,1).endsWith("-01");
      const months=(Number(end.slice(0,4))-Number(start.slice(0,4)))*12+Number(end.slice(5,7))-Number(start.slice(5,7))+1;
      let covered=completeStart&&completeEnd&&months>0&&!current.unresolved&&!all.missing.length;
      for(let month=monthStart(start);month<=end;month=shiftMonth(month,1))if(!current.rows.some(r=>r.date.slice(0,7)===month.slice(0,7)))covered=false;
      if(covered){facts.averageMonthlyIncome=round(total/months);lines.push(`Average per calendar month in that recorded range: ${dollars(total/months)}.`);}
      else missing.push(!completeStart||!completeEnd?"Use complete calendar months for a normal monthly-income average":"Recorded classified history does not cover every selected month; a normal monthly-income average cannot be established");
    }
  } else if (request.domain === "transactions") {
    const found = current.rows.filter(r => request.amount === null || (request.operation === "threshold" ? Math.abs(r.amount) >= request.amount : Math.abs(Math.abs(r.amount) - request.amount) < .005)).sort((a, b) => b.date.localeCompare(a.date));
    lines.push(`${found.length} matching recorded transactions from ${start} through ${end}.`, ...found.slice(0, 8).map(r => `${r.date}: ${r.merchant}, ${dollars(r.amount)} (${r.category}).`));
    facts.matchCount = found.length;
    if (found.length > 8) lines.push("Showing the eight most recent matches. Narrow the dates to see more.");
  } else if (request.domain === "fees") {
    const fees = current.rows.filter(r => r.amount < 0 && /fee|overdraft|nsf/i.test(`${r.category} ${r.merchant}`));
    const total = -sum(fees.map(r => r.amount));
    lines.push(`${dollars(total)} in recorded fee-labeled charges from ${start} through ${end}.`, ...fees.slice(-5).map(r => `${r.date}: ${r.merchant}, ${dollars(-r.amount)} (${r.account}).`));
    facts.fees = total;
    const byAccount=new Map<string,{account:string;cents:number}>();
    fees.filter(r=>r.accountKey).forEach(r=>{const prior=byAccount.get(r.accountKey!);byAccount.set(r.accountKey!,{account:r.account,cents:(prior?.cents??0)+Math.round(-r.amount*100)});});
    const accountFees=[...byAccount].map(([key,r])=>({key,account:r.account,amount:r.cents/100})).sort((a,b)=>b.amount-a.amount);
    const display=(r:typeof accountFees[number])=>accountFees.filter(a=>a.account===r.account).length>1?`${r.account} (separate account ${accountFees.indexOf(r)+1})`:r.account;
