            const paydays=new Set(engine.getIncomeOccurrencesInMonth(m,y).filter(i=>i.effectiveAmount>0).flatMap(i=>i.days).map(day=>`${prefix}-${String(day).padStart(2,"0")}`).filter(date=>date>=extraDate));
