        facts.timelineOutcome="duration";facts.timelineDuration=periods;facts.timelineUnit=contribution.frequency==="monthly"?"months":"household_paydays";
        lines.unshift(`Scenario: ${label(goal.name)} needs ${periods} ${contribution.frequency==="monthly"?"monthly contributions":"household-payday contributions"} at your stated ${dollars(contribution.amount)} to reach ${dollars(goalTarget)} from its ${dollars(current)} earmarked funding. This is not confirmation those contributions are affordable.`);
      } else {
        lines.unshift(`I cannot estimate when ${label(goal.name)} will reach ${dollars(goalTarget)} without a contribution amount and frequency. Its ${dollars(goalTarget-current)} remaining target is not a per-contribution amount.`);
        missing.push("State a contribution amount and frequency for a goal timeline");
      }
    }
  }
  missing.push(...requireSources(snapshot,sources));
  return {text:lines.join("\n\n"),facts,sources,assumptions,missing:[...new Set(missing)],scenario:request.operation==="scenario" || request.scenario!==null};
}

import { orderDebts, projectSnowballMonth, type SnowballDebtInput, type DatedSnowballMonthPlanResult } from "../../../artifacts/mobile/lib/snowball.ts";
import { round, sum } from "./analysisTypes.ts";

/** Reuses canonical interest/minimum/rollover calculations. The only added
 * operation is an explicitly selected extra-principal allocation on a copy. */
export function projectAnalystDebt(options:{debts:SnowballDebtInput[];method:"snowball"|"avalanche";year:number;month:number;currentPlan:DatedSnowballMonthPlanResult;targetId?:string;extra:(month:number,year:number)=>number}) {
  const balances=new Map(options.currentPlan.balances);
  let rolled=options.currentPlan.rolledPayment;
  const months:Array<{month:number;year:number;endingDebt:number;interest:number;extra:number;paidOffNames:string[];paidOffIds:string[]}>=[];
  const order=[...options.currentPlan.payoffOrder];
  for(let offset=0;offset<=360;offset++) {
    const absolute=options.year*12+options.month+offset,year=Math.floor(absolute/12),month=absolute%12;
    const beforeMonth=offset===0?new Map(options.debts.map(d=>[d.id,d.balance])):new Map(balances);
    let interest=0;
    const paidOffNames:string[]=offset===0?[...options.currentPlan.paidOffNames]:[];
    if(offset>0) {
      const planned=projectSnowballMonth({debts:options.debts,method:options.method,startingBalances:balances,rolledPayment:rolled,extraPayment:0});
      balances.clear();planned.balances.forEach((value,id)=>balances.set(id,value));rolled=planned.rolledPayment;interest=planned.interest;paidOffNames.push(...planned.paidOffNames);
    }
    let extra=round(Math.max(0,options.extra(month,year))),applied=0;
    const eligible=options.debts.filter(d=>d.included&&(balances.get(d.id)??0)>.009).map(d=>({...d,balance:balances.get(d.id)!}));
    const target=eligible.find(d=>d.id===options.targetId);
    const targets=target?[target,...orderDebts(eligible.filter(d=>d.id!==target.id),options.method)]:orderDebts(eligible,options.method);
    for(const debt of targets) {
      const before=balances.get(debt.id)??0,payment=Math.min(before,extra),after=round(before-payment);
      balances.set(debt.id,after);extra=round(extra-payment);applied=round(applied+payment);
      if(before>.009&&after<=.009) {rolled=round(rolled+debt.minimum);paidOffNames.push(debt.name);}
      if(extra<=.009)break;
    }
    for(const name of paidOffNames)if(!order.includes(name))order.push(name);
    const endingDebt=sum(options.debts.filter(d=>d.included).map(d=>balances.get(d.id)??0));
    const paidOffIds=options.debts.filter(d=>(beforeMonth.get(d.id)??0)>.009&&(balances.get(d.id)??0)<=.009).map(d=>d.id);
    months.push({month,year,endingDebt,interest,extra:applied,paidOffNames,paidOffIds});
    if(endingDebt<=.009)return {months,payoffOrder:order,debtFreeDate:`${year}-${String(month+1).padStart(2,"0")}`};
  }
  return {months,payoffOrder:order,debtFreeDate:null};
}

import { canonicalConnectedAccounts } from "../../../artifacts/mobile/lib/plaidActivity.ts";
import { dollars, label, numeric, requireSources, round, type AnalysisRequest, type AnalysisResult, type AnalysisSnapshot } from "./analysisTypes.ts";

/** Rank the complete scoped set, never a truncated display list. */
export function rankCreditOrDebt(snapshot:AnalysisSnapshot,request:AnalysisRequest & {metric?:string|null}):AnalysisResult {
  const credit=request.domain==="credit",sources=[credit?"plaid_accounts":"bills"];
  const missing=requireSources(snapshot,sources);
  const metric=request.metric;
  if(!metric||!["balance","apr",...(credit?["utilization"]:[])].includes(metric))return {text:"Should I compare balances, APRs, or credit-card utilization?",facts:{},sources,missing:["A supported comparison metric is required"],assumptions:[],scenario:false};
  const rows=credit?canonicalConnectedAccounts((snapshot.sources.plaid_accounts?.rows??[]).map(r=>({...r,id:String(r.id),is_active:r.is_active!==false}))).filter((r:any)=>r.account_type==="credit"):(snapshot.sources.bills?.rows??[]).filter(r=>r.is_debt&&(!r.end_date||r.end_date>=snapshot.today)&&(numeric(r.balance)===null||numeric(r.balance)!>0));
  const selected=rows.filter((r:any)=>!request.entity||String(r.display_name??r.name).trim().toLowerCase()===request.entity.trim().toLowerCase());
  const uncertainEligibility=!credit&&selected.some((r:any)=>numeric(r.balance)===null);
  if(uncertainEligibility)missing.push("Some debt balances are unavailable, so active positive-balance eligibility cannot be verified; known metrics from those candidates remain included");
  const values=selected.map((r:any)=>{
    const balance=numeric(credit?r.current_balance:r.balance),apr=numeric(credit?r.purchase_apr:r.interest_rate),limit=numeric(r.credit_limit);
    const value=metric==="balance"?balance:metric==="apr"?apr:balance!==null&&limit!==null&&limit>0?Math.max(0,balance)/limit*100:null;
    return {name:label(r.display_name??r.name),value};
  }).filter(r=>r.value!==null&&Number.isFinite(r.value)&&r.value>=0) as {name:string;value:number}[];
  if(values.length!==selected.length)missing.push(`Some ${metric} values are unavailable; this ranking covers verified values only`);
  if(!values.length)return {text:`No matching ${credit?"connected cards":"active debts"} have a verified ${metric} to compare.`,facts:{},sources,missing:[...missing,"No comparable records"],assumptions:[],scenario:false};
  const best=(request.operation==="minimum"?Math.min:Math.max)(...values.map(r=>r.value));
  const tied=values.filter(r=>Math.abs(r.value-best)<1e-9);
  return {text:`${tied.map(r=>r.name).join(", ")} ${tied.length===1?"has":"tie for"} the ${request.operation==="minimum"?"lowest":"highest"} ${metric} among ${values.length} checked ${credit?"connected cards":uncertainEligibility?"debt candidates (some balances unverified)":"active debts"}: ${metric==="balance"?dollars(best):`${round(best)}%`}.${missing.length?" Some records or their eligibility could not be fully verified; this is not a complete-account ranking.":""}`,facts:{rankedNames:tied.map(r=>r.name).join(", "),rankedValue:round(best),rankedCount:values.length,metric},sources,missing,assumptions:["Ranks recorded values, not live statement data. Ties are retained; credit limits are required only for utilization. A ranking alone does not establish which payment is affordable."],scenario:false};
}

import { buildAnalysisForecast, projectionSources } from "./analysisProjection.ts";
import { aggregateSpending, analyticTransactions, historicalExpenseCoverage } from "./analysisSpending.ts";
import { scheduleAnalysis } from "./analysisSchedule.ts";
import { dayAdd, dollars, label, matches, monthEnd, monthStart, numeric, round, shiftMonth, sum, type AnalysisRequest, type AnalysisResult, type AnalysisSnapshot } from "./analysisTypes.ts";

export function stabilityAnalysis(snapshot: AnalysisSnapshot, request: AnalysisRequest): AnalysisResult {
  const timeline=request.purpose==="buffer_timeline" || request.domain==="buffer"&&request.operation==="plan";
  const proposed=timeline?request.contribution:null;
  const contributionFacts:AnalysisResult["facts"]=proposed?{explicitContribution:proposed.amount,contributionFrequency:proposed.frequency}:{};
  const contributionNote=proposed?`You proposed ${dollars(proposed.amount)} ${proposed.frequency==="paycheck"?"per paycheck":proposed.frequency==="monthly"?"per month":"once"}. This is your stated contribution, not verified spare money or confirmation it is affordable.`:null;
  if(timeline&&request.amount===null&&(!request.target||request.target==="none"))return {text:"What cash-buffer amount do you want to reach, or do you mean one paycheck or one month ahead?",facts:{timelineOutcome:"not_estimable",...contributionFacts},sources:[],assumptions:contributionNote?[contributionNote]:[],missing:["A buffer target is needed; no target or contribution amount was inferred"],scenario:false};
  const forecast=buildAnalysisForecast(snapshot,request.endDate??monthEnd(shiftMonth(snapshot.today,2)));
  const missing=[...forecast.missing,...forecast.affordabilityMissing];
  const assumptions=["This plan uses recorded obligations and expected paychecks. Estimated spending is included only when a three-month baseline is available. No balances or plans are changed."];
  if(contributionNote)assumptions.push(contributionNote);
  const days=forecast.days, floor=forecast.input.settings.safety_floor;
  const events=days.flatMap(d=>d.events).filter(e=>e.date>=snapshot.today&&!["actual","applied","finalized"].includes(e.status));
  const income=events.filter(e=>e.kind==="scheduled_income"&&e.amount>0);
  const payDates=[...new Set(income.map(e=>e.date))].sort();
  const nextDate=payDates[0];
  const nextPay=sum(income.filter(e=>e.date===nextDate).map(e=>e.amount));
  const needsPaycheckTarget=request.amount===null&&request.target!=="month_ahead";
  if(needsPaycheckTarget&&(!nextDate||nextPay<=0))return {text:"I cannot determine a paycheck-sized buffer target because no positive future paycheck is scheduled. State an explicit cash target or add the expected income schedule.",facts:timeline?{timelineOutcome:"not_estimable",timelineDuration:null,...contributionFacts}:{},sources:projectionSources,assumptions:contributionNote?[contributionNote]:[],missing:["A positive expected paycheck is required to derive the target; zero was not assumed"],scenario:false};
  const low=days.reduce((a,b)=>a.estimatedBalance<=b.estimatedBalance?a:b);
  const scheduledBuffer=round(Math.max(0,Math.min(forecast.availableNow??0,low.estimatedBalance)-floor));
  const bufferVerified=forecast.historyAvailable&&forecast.anchorDate===snapshot.today&&forecast.availableNow!==null&&!missing.length;
  const free=bufferVerified?scheduledBuffer:null;
  const activity=analyticTransactions(snapshot);
  const priorStart=shiftMonth(snapshot.today,-3), priorEnd=dayAdd(monthStart(snapshot.today),-1);
  const prior=aggregateSpending(activity.rows,priorStart,priorEnd);
  // Historical surplus needs evidence that known paid bills are represented.
  // Keep this separate from the current forecast, which includes future bills.
  const expenseCoverage=historicalExpenseCoverage(snapshot,prior.rows,priorStart,priorEnd);
  missing.push(...expenseCoverage.missing);
  const monthlyIncome=round(prior.income/3), monthlyExpense=round((prior.spending+prior.nonCardRepayments)/3);
  const nextMonth=shiftMonth(snapshot.today,1), nextMonthEnd=monthEnd(nextMonth);
  const nextMonthObligations=-sum(events.filter(e=>e.amount<0&&e.date>=nextMonth&&e.date<=nextMonthEnd).map(e=>e.amount));
  const monthTarget=round(nextMonthObligations+forecast.dailyEstimate*Number(nextMonthEnd.slice(-2)));
  const target=request.amount??(request.target==="month_ahead"?monthTarget:nextPay);
  const incompleteMonthTarget=request.target==="month_ahead"&&request.amount===null&&!forecast.historyAvailable;
  const remaining=free===null?null:round(Math.max(0,target-free));
  const facts:AnalysisResult["facts"]={currentPlanBuffer:free,cashCushion:floor,nextPayday:nextDate??null,nextPaycheck:nextPay,oneMonthTarget:monthTarget,target,remaining,minimumBalance:low.estimatedBalance,minimumDate:low.date,...contributionFacts};
  if(!expenseCoverage.complete){facts.historicalMonthlySurplus=null;facts.daysAhead=null;}
  if(!forecast.historyAvailable)facts.oneMonthTarget=null;
  if(incompleteMonthTarget){facts.target=null;facts.monthScheduledObligations=nextMonthObligations;missing.push("The full month-ahead target is unknown without everyday living costs; scheduled obligations are only one portion");}
  const lines=[free===null?`Your available cash buffer cannot yet be verified. The recorded plan's lowest projected balance is ${dollars(low.estimatedBalance)} on ${low.date}, with a ${dollars(floor)} cushion.`:`Your checked plan has ${dollars(free)} of additional cash buffer above the ${dollars(floor)} cushion. Its lowest projected balance is ${dollars(low.estimatedBalance)} on ${low.date}.`];
  if(contributionNote)lines.push(contributionNote);
  if(!forecast.historyAvailable) missing.push("A full classified spending baseline is missing, so these buffer amounts are scheduled-plan estimates only");
  if(!nextDate&&needsPaycheckTarget) missing.push("An expected paycheck date and amount are needed for a paycheck-ahead plan");
  const nextEnd=payDates[1]?dayAdd(payDates[1],-1):nextMonthEnd;
  const committed=-sum(events.filter(e=>e.amount<0&&e.date>=(nextDate??snapshot.today)&&e.date<=nextEnd).map(e=>e.amount));
  if(nextPay>0) {
    facts.paycheckCommitted=committed; facts.paycheckCommittedPercent=round(committed/nextPay*100);
    lines.push(`Your next expected paycheck is ${dollars(nextPay)} on ${nextDate}. ${dollars(committed)} (${facts.paycheckCommittedPercent}%) of that amount corresponds to recorded obligations through ${nextEnd}, before additional everyday spending.`);
  }
  if(["buffer","stability","paycheck","health"].includes(request.domain)) {
    lines.push(incompleteMonthTarget?`The scheduled-obligation portion of getting one month ahead is ${dollars(nextMonthObligations)}. The full target is unknown until everyday living costs are included.`:`A ${request.target==="month_ahead"?"month-ahead":"paycheck/buffer"} target is ${dollars(target)}${remaining===null?"; the remaining amount cannot be verified until the available buffer is known":`, needing another ${dollars(remaining)} beyond that available buffer`}.`);
    const monthsOfHistory=[1,2,3].every(offset=>activity.rows.some(r=>r.date>=shiftMonth(snapshot.today,-offset)&&r.date<=monthEnd(shiftMonth(snapshot.today,-offset))))&&!activity.missing.length&&!prior.unresolved&&!prior.unclassifiedDebt&&expenseCoverage.complete;
    if(monthsOfHistory) {
      const surplus=round(monthlyIncome-monthlyExpense);
      facts.historicalMonthlySurplus=surplus;
      if(free!==null&&monthlyExpense>0){facts.daysAhead=round(free/(monthlyExpense/30.4375));lines.push(`Your available buffer covers about ${facts.daysAhead} days at the recorded expense pace. This is an average-spending measure, not a guarantee bills arrive evenly.`);}
      lines.push(`Recorded monthly average: ${dollars(monthlyIncome)} confirmed income versus ${dollars(monthlyExpense)} consumption and debt payments, leaving ${dollars(surplus)} before other unclassified flows.`);
      // A hypothetical monthly capacity is not an amount the user has chosen
      // to save from each paycheck. Do not use it to answer a paycheck count,
      // or compete with an explicitly stated contribution schedule.
      if(surplus>0&&remaining!==null&&remaining>0&&!proposed&&request.timelineUnit!=="household_paydays") {
        const monthlyCapacity=Math.min(surplus,Math.max(0,low.estimatedBalance-floor));
        if(monthlyCapacity>0) {
          const months=Math.ceil(remaining/monthlyCapacity);
          facts.monthsToTargetScenario=months;
          lines.push(`Scenario: setting aside ${dollars(monthlyCapacity)}/month would need about ${months} months. Recheck each payday; the current forecast does not guarantee that surplus indefinitely.`);
          facts.targetMonthScenario=shiftMonth(snapshot.today,months).slice(0,7);
          const historicalPaydays=[...new Set(activity.rows.filter(r=>r.kind==="income"&&r.date>=priorStart&&r.date<=priorEnd).map(r=>r.date))];
          if(historicalPaydays.length){const perPay=round(monthlyCapacity/(historicalPaydays.length/3));facts.contributionPerPaydayScenario=perPay;facts.paydaysToTargetScenario=perPay>0?Math.ceil(remaining/perPay):null;lines.push(`That is roughly ${dollars(perPay)} per payday at your recorded payday frequency, targeting ${facts.targetMonthScenario}. This assumes that contribution remains affordable; pause it if the cash-flow check drops below your cushion.`);}
        } else lines.push("Do not commit a recurring savings amount yet: the forecast has no spare capacity above your cushion.");
      }
      const needed=Math.max(0,-surplus);
      if(needed>0) lines.push(`Closing the recorded shortfall would require approximately ${dollars(needed/4.345)} less spending or more income each week.`);
      const top=prior.categories.filter(c=>!/rent|mortgage|utilities|insurance|debt/i.test(c.name)).slice(0,3);
      if(top.length) lines.push(`Categories to review first (not automatically nonessential): ${top.map(c=>`${c.name} ${dollars(c.amount/3)}/month`).join("; ")}.`);
    } else missing.push("At least three months of classified income and expenses are needed to estimate a sustainable contribution and target date");
    lines.push(low.estimatedBalance<floor ? "Next steps: protect essentials and required payments first, resolve the upcoming cash shortfall, then rebuild the checking cushion before adding extra debt payments." : "Next steps: leave the bill reserve and cushion untouched, review everyday-spending needs, then direct verified spare cash toward your chosen buffer or debt target.");
  }
  const closes=(snapshot.sources.household_daily_checking_closes?.rows??[]).filter(r=>r.balance_date>=priorStart&&r.balance_date<=priorEnd&&numeric(r.checking_balance)!==null);
  const lows=Object.entries(Object.groupBy(closes,r=>String(r.balance_date).slice(0,7))).map(([month,values])=>({month,low:Math.min(...values!.map(r=>Number(r.checking_balance))),days:values!.length})).sort((a,b)=>a.month.localeCompare(b.month));
  if(request.domain==="progress"||request.domain==="stability"||request.domain==="health") {
    if(lows.length>=2) lines.push(`Observed monthly lows: ${lows.slice(-3).map(m=>`${m.month} ${dollars(m.low)} (${m.days} recorded days)`).join("; ")}.`);
    const historicalPaydays=[...new Set(activity.rows.filter(r=>r.kind==="income"&&r.date>=priorStart&&r.date<=priorEnd).map(r=>r.date))];
    const before=historicalPaydays.map(date=>closes.find(c=>c.balance_date===dayAdd(date,-1))).filter(Boolean);
    const tight=before.filter(c=>Number(c!.checking_balance)<floor).length;
    if(snapshot.sources.household_daily_checking_closes?.complete && before.length>=3 && new Set(before.map(c=>String(c!.balance_date).slice(0,7))).size>=2 && prior.income>0 && !prior.unresolved && !prior.unclassifiedDebt && expenseCoverage.complete) lines.push(`${tight} of ${before.length} observed pre-payday balances were below your cushion. Combined with income, expenses and the forecast, ${tight>=Math.ceil(before.length/2)&&monthlyIncome<=monthlyExpense ? "this is evidence of paycheck-to-paycheck pressure" : "this does not by itself establish persistent paycheck-to-paycheck dependence"}.`);
    else missing.push("Not enough recorded pre-payday balances for a reliable paycheck-to-paycheck diagnosis; a single low balance is not enough");
    assumptions.push("Historical progress uses recorded daily closes only, never today's forecast rewritten as past actuals. Debt principal changes cannot be reconstructed from payments alone.");
  }
  if(timeline) {
    facts.timelineOutcome="not_estimable";
    facts.timelineDuration=null;
    if(request.timelineUnit)facts.timelineUnit=request.timelineUnit;
    const contribution=request.contribution;
    if(free!==null&&remaining===0) {
      facts.timelineOutcome="already_reached";facts.timelineDuration=0;
      lines.unshift(`You already have the ${dollars(target)} additional cash-buffer target under the checked plan. This means money above the ${dollars(floor)} cushion, not total checking or savings. No waiting time is needed.`);
    } else if(request.timelineUnit==="household_paydays"&&contribution?.frequency!=="paycheck") {
      const cadence=contribution?` You specified ${dollars(contribution.amount)} ${contribution.frequency==="monthly"?"per month":"once"}; that does not establish an amount per paycheck.`:"";
      lines.unshift(`How much would you like to set aside from each paycheck toward the ${dollars(target)} additional cash buffer? I need that amount to calculate how many paychecks it would take.${cadence}`);
      missing.push("A stated contribution amount per paycheck is needed to calculate the requested paycheck count");
      if(free===null)missing.push("The current available buffer must also be verified before calculating the remaining paycheck count");
    } else if(free!==null&&remaining!==null&&remaining>0&&contribution) {
      // Explicit contributions are hypothetical, never inferred from the target.
      const periods=Math.ceil(remaining/contribution.amount);
      facts.contributionPeriods=periods;facts.explicitContribution=contribution.amount;
      if(contribution.frequency==="once") {
        lines.unshift(`Another ${dollars(remaining)} is needed above the ${dollars(floor)} cushion. One ${dollars(contribution.amount)} contribution ${periods<=1?"would cover that gap, but its date is not specified":"would not reach the target"}. I cannot give a timeline without a recurring contribution schedule.`);
        missing.push("A recurring contribution frequency or one-time date is needed for a timeline");
      } else if(request.timelineUnit==="months"&&contribution.frequency==="paycheck") {
        lines.unshift(`Scenario: your remaining additional buffer needs ${periods} contributions at your stated ${dollars(contribution.amount)} per paycheck. I cannot translate those paychecks into calendar months without verified contribution dates. This does not confirm the contributions are affordable.`);
        missing.push("Verified payday contribution dates are needed to express the buffer timeline in the requested months");
      } else {
        facts.timelineOutcome="duration";facts.timelineDuration=periods;facts.timelineUnit=contribution.frequency==="monthly"?"months":"household_paydays";
        lines.unshift(`Scenario: reaching ${dollars(target)} of additional buffer above your ${dollars(floor)} cushion would take ${periods} ${contribution.frequency==="monthly"?"monthly contributions":"distinct household paydays"} at your stated ${dollars(contribution.amount)} each. That contribution has not been confirmed affordable; recheck the bill reserve before each transfer.`);
        assumptions.push("Explicit-contribution timing is a what-if count, not certification of recurring affordability. Paydays mean distinct household income dates, not each source separately.");
      }
    } else if(free!==null&&typeof facts.monthsToTargetScenario==="number"&&Number(facts.monthsToTargetScenario)>0) {
      facts.timelineOutcome="duration";facts.timelineDuration=facts.monthsToTargetScenario;facts.timelineUnit="months";
      lines.unshift(`The checked scenario needs about ${facts.monthsToTargetScenario} months to build ${dollars(target)} of additional cash buffer above your ${dollars(floor)} cushion, targeting ${facts.targetMonthScenario}. This uses recorded surplus, not an assumed contribution equal to your target.`);
    } else {
      const reason=free===null?"the available buffer, living-expense baseline or older obligations cannot yet be verified":!expenseCoverage.complete?"recorded bill payments are not fully reconciled with historical expenses":"the checked plan has no positive sustainable contribution capacity";
      lines.unshift(incompleteMonthTarget?"I cannot estimate when you will be one month ahead yet: the full target is unknown without everyday living costs.":`I cannot estimate how long it will take to reach ${dollars(target)} of additional cash buffer yet because ${reason}. The target is above your ${dollars(floor)} cushion, not your savings-account balance.`);
      missing.push(`Buffer timeline unavailable: ${reason}`);
    }
  }
  return {text:lines.join("\n\n"),facts,sources:[...projectionSources,"household_daily_checking_closes"],assumptions,missing:[...new Set(missing)],scenario:false};
}

export function scenarioAnalysis(snapshot: AnalysisSnapshot, request: AnalysisRequest): AnalysisResult {
  let scenario=request.scenario;
  if(!scenario) throw new Error("A scenario change is required");
  if(scenario.kind==="income_change"&&request.dateEvent==="next_payday") {
    const schedule=scheduleAnalysis(snapshot,{...request,domain:"income",purpose:"general",startDate:snapshot.today,endDate:null,entity:scenario.entity,dateEvent:"next_payday"});
    if(schedule.missing.length||typeof schedule.facts.nextPayday!=="string")return {...schedule,scenario:true};
    scenario={...scenario,date:schedule.facts.nextPayday};
    if(request.endDate&&request.endDate<scenario.date)return {text:"The requested window ends before the next scheduled paycheck. Choose a window including that income event.",facts:{},sources:projectionSources,assumptions:[],missing:["The income scenario's effective payday is outside the requested window"],scenario:true};
  }
  let end=request.endDate??(scenario.repeat==="once"?scenario.date:monthEnd(shiftMonth(scenario.date,1)));
  const configuredEnd=monthEnd(shiftMonth(snapshot.today,Number(snapshot.sources.household_settings?.rows[0]?.forecast_horizon_months??1)-1));
  const obligationWindow=monthEnd(shiftMonth(scenario.date,1));
  const assessmentEnd=(obligationWindow>end?obligationWindow:end)>configuredEnd?configuredEnd:(obligationWindow>end?obligationWindow:end);
  if(end>configuredEnd)throw new Error("Requested scenario exceeds the configured forecast");
  const forecast=buildAnalysisForecast(snapshot,assessmentEnd);
  const missing=[...forecast.missing];
  const original=forecast.days.flatMap(d=>d.events);
  const changes: {date:string;amount:number}[]=[];
  const named=original.filter(e=>e.date>=(scenario.kind==="move_bill"?snapshot.today:scenario.date)&&(!scenario.sourceDate||e.date===scenario.sourceDate)&&matches(e.name,scenario.entity)&&["scheduled","planned"].includes(e.status)).sort((a,b)=>a.date.localeCompare(b.date));
  if(["cancel_bill","move_bill","bill_increase"].includes(scenario.kind)) {
    const billIds=new Set(named.filter(e=>e.kind==="bill").map(e=>e.sourceId));
    if(!scenario.entity||billIds.size!==1) missing.push("The scenario must identify exactly one scheduled bill");
    else {
      const selected=named.filter(e=>e.kind==="bill"&&e.amount<0).slice(0,scenario.repeat==="once"?1:undefined);
      if(!selected.length) missing.push("No matching unpaid scheduled bill occurrence exists in the checked window");
      if(!request.endDate&&scenario.repeat==="once"&&selected[0])end=scenario.kind==="move_bill"&&scenario.date>selected[0].date?scenario.date:selected[0].date;
      if(scenario.kind==="move_bill"&&scenario.repeat!=="once") return {text:"Choose one bill occurrence and its new date. Recurring date changes need individual dates to avoid stacking payments on one day.",facts:{},sources:projectionSources,assumptions:[],missing:["A single source occurrence is required for a bill-date scenario"],scenario:true};
      for(const event of selected) {
        if(scenario.kind==="bill_increase") {
          if(scenario.amountMode==="absolute") {
            const configured=numeric(event.configuredOccurrenceAmount),settled=numeric(event.settledOccurrenceAmount);
            if(configured===null||settled===null||configured<0||settled<0||Math.abs(Math.max(0,configured-settled)+event.amount)>0.01) {
              missing.push("The configured bill amount and prior settlement cannot be reconciled for this price-change scenario");
              continue;
            }
            // Replace the full occurrence price, preserving money already paid.
            // A price below the settlement clears the remainder, not a refund.
            const remaining=Math.max(0,scenario.amount-settled);
            changes.push({date:event.date,amount:round(-remaining-event.amount)});
          } else changes.push({date:event.date,amount:-scenario.amount});
        }
        else { changes.push({date:event.date,amount:-event.amount}); if(scenario.kind==="move_bill") changes.push({date:scenario.date,amount:event.amount}); }
      }
    }
  } else {
    let dates=[scenario.date];
    if(scenario.repeat==="paycheck") {
      const incomeSource=scenario.kind==="income_change"?scenario.entity:null;
      const paychecks=original.filter(e=>e.kind==="scheduled_income"&&e.amount>0&&e.date>=scenario.date&&(!incomeSource||matches(e.name,incomeSource)));
      if(incomeSource&&new Set(paychecks.map(e=>e.sourceId)).size!==1) missing.push("The paycheck source must identify exactly one income schedule");
      if(!paychecks.length) missing.push("No matching future paycheck dates were found");
      dates=[...new Set(paychecks.map(e=>e.date))];
    }
    else if(scenario.repeat==="monthly") { dates=[]; for(let month=monthStart(scenario.date);month<=assessmentEnd;month=shiftMonth(month,1)) dates.push(`${month.slice(0,7)}-${String(Math.min(Number(scenario.date.slice(-2)),Number(monthEnd(month).slice(-2)))).padStart(2,"0")}`); }
    const amount=scenario.kind==="income_change" ? scenario.amount : -Math.abs(scenario.amount);
    dates.forEach(date=>changes.push({date,amount}));
  }
  if(missing.length) return {text:"I could not safely calculate that scenario from the available records.",facts:{},sources:projectionSources,assumptions:[],missing,scenario:true};
  let delta=0;
  const altered=forecast.days.map(d=>{delta=round(delta+sum(changes.filter(c=>c.date===d.date).map(c=>c.amount))); return {...d,scenarioBalance:round(d.estimatedBalance+delta)};});
  const lowest=altered.reduce((a,b)=>a.scenarioBalance<=b.scenarioBalance?a:b);
  const baseLow=forecast.days.reduce((a,b)=>a.estimatedBalance<=b.estimatedBalance?a:b);
  const last=altered.find(d=>d.date===end)!;
  const changedDates=[...new Set(changes.map(change=>change.date))].sort();
  const timingAssumption=`The scenario applies on ${changedDates.slice(0,6).join(", ")}${changedDates.length>6?` and ${changedDates.length-6} later dates`:""} (${scenario.repeat==="once"?"one occurrence":"repeated scheduled occurrences"}).`;
  missing.push(...forecast.affordabilityMissing);
  if(forecast.anchorDate!==snapshot.today)missing.push("Refresh the balance observation before judging this scenario affordable");
  const safety=lowest.scenarioBalance<forecast.input.settings.safety_floor ? "This scenario falls below your configured cash cushion." : forecast.historyAvailable&&!missing.length ? "The scenario stays above the configured cushion under the checked assumptions, but this is not a guarantee of affordability." : "Recorded flows stay above the cushion, but affordability cannot be confirmed until everyday spending, current funds, and older obligations are verified.";
  return {text:`Scenario only — nothing was changed.\n\nBy ${end}, the projected balance would be ${dollars(last.scenarioBalance)}, compared with ${dollars(last.estimatedBalance)} in the baseline. Looking beyond the change through ${assessmentEnd}, the scenario's lowest balance is ${dollars(lowest.scenarioBalance)} on ${lowest.date}; the baseline low is ${dollars(baseLow.estimatedBalance)}.\n\n${safety}`,facts:{scenarioEndBalance:last.scenarioBalance,baselineEndBalance:last.estimatedBalance,scenarioLow:lowest.scenarioBalance,scenarioLowDate:lowest.date,assessmentEndDate:assessmentEnd},sources:projectionSources,assumptions:[timingAssumption,"Changes are applied to a copy of the canonical forecast. Savings transfers reduce checking but do not reduce net worth. Extra debt payments here show cash impact; interest/payoff changes require the separate debt projection.",forecast.historyAvailable?`Additional spending estimate: ${dollars(forecast.dailyEstimate)}/day.`:"No reliable everyday-spending baseline is available."],missing,scenario:true};
}

import { scheduleAnalysis } from "./analysisSchedule.ts";
import { analyticTransactions } from "./analysisSpending.ts";
import { dayAdd, dollars, label, matches, monthStart, numeric, requireSources, round, shiftMonth, sum, validDate, type AnalysisRequest, type AnalysisResult, type AnalysisSnapshot } from "./analysisTypes.ts";

/** Recurring-charge detection is evidence of a pattern, not proof of an active
 * subscription or a duplicate service. Never cancel or mutate from this read. */
export function recurringAnalysis(snapshot:AnalysisSnapshot,request:AnalysisRequest):AnalysisResult {
  const rows=(name:string)=>snapshot.sources[name]?.rows??[];
  const history=analyticTransactions(snapshot);
  if(request.purpose==="bill_settlement"||request.purpose==="bills_overdue") {
    const overdue=request.purpose==="bills_overdue";
    const end=request.endDate??(overdue?dayAdd(snapshot.today,-1):snapshot.today);
    const earliest=monthStart(shiftMonth(snapshot.today,-23));
    const origins=rows("bills").filter(b=>!request.entity||matches(b.name,request.entity)).map(b=>b.start_date??monthStart(String(b.created_at??"").slice(0,10)));
    const validOrigins=origins.filter(d=>validDate(d)&&d<=end).sort();
    const start=request.startDate??(overdue?(validOrigins[0]??monthStart(end)):monthStart(end));
    if(!validDate(end)||end>snapshot.today||!validDate(start)||start>end)return {text:"Choose an elapsed date range to check recorded bill settlements.",facts:{},sources:["bills","monthly_overrides","transactions"],assumptions:[],missing:["Settlement checks cannot confirm future payments"],scenario:false};
    const boundedStart=start<earliest?earliest:start;
    const base=scheduleAnalysis(snapshot,{...request,domain:"bills",startDate:boundedStart,endDate:end,dateEvent:"none"});
    if(start<earliest)base.missing.push("Earlier obligations extend beyond this 24-month settlement check; the overdue list is incomplete");
    if(overdue&&origins.some(d=>!validDate(d)))base.missing.push("A bill start date is unavailable; complete overdue coverage cannot be verified");
    if(overdue&&!request.startDate&&rows("bills").some(b=>(!request.entity||matches(b.name,request.entity))&&!validDate(b.start_date)))base.missing.push("A bill has no explicit obligation start date. Record creation is not proof of when bills began; earlier-month overdue coverage is unverified. Provide an explicit historical window to check retained settlements.");
